/**
 * The ONE switch for customer/public dedicated-server surfaces.
 *
 * Every customer route (app/(marketing)/dedicated-servers, app/dashboard/dedicated/**)
 * calls `requireDedicatedPublic()` first: while Setting dedicated_public_enabled is
 * off it is a plain 404, exactly as if the route did not exist. Admin previews
 * (app/admin/preview/dedicated/**) do NOT use this gate — they are admin-only
 * and render the same components with `preview` set.
 *
 * test/dedicated-gate.test.ts asserts every customer route file calls this, and
 * that no sitemap section / customer nav lists the routes while the flag is off.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";

export const DEDICATED_PUBLIC_FLAG = "dedicated_public_enabled";
export const DEDICATED_PUBLIC_PATH = "/dedicated-servers";
export const DEDICATED_DASHBOARD_PATH = "/dashboard/dedicated";

/** Pure decision (unit-tested): render, or 404. */
export function dedicatedRouteDecision(flagOn: boolean): "render" | "not-found" {
  return flagOn ? "render" : "not-found";
}

export async function dedicatedPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(DEDICATED_PUBLIC_FLAG, false);
  } catch {
    return false; // fail CLOSED: a DB hiccup must never expose an unreleased page
  }
}

export async function requireDedicatedPublic(): Promise<void> {
  if (dedicatedRouteDecision(await dedicatedPublicEnabled()) === "not-found") notFound();
}

/** Sitemap paths contributed by this feature (empty while the flag is off). */
export function dedicatedSitemapPaths(flagOn: boolean): string[] {
  return flagOn ? [DEDICATED_PUBLIC_PATH] : [];
}
/**
 * Loader for the PUBLIC catalogue (marketing page + its admin preview).
 * Returns only brand-safe PublicCatalogEntry rows (lib/dedicated/customer-view.ts).
 *
 * Only items an admin marked `visible`, not removed upstream, priced in USD,
 * and orderable in at least one OFFERED, non-hidden region are listed.
 * `previewAll` (admin preview only) treats every live item as visible so the
 * page design can be reviewed before any item is opted in.
 */
import { db } from "../db";
import { defaultConfig, itemRegions, loadAvailability, loadRules, priceView, stockByDc } from "./catalog-view";
import { toPublicCatalogEntry, type PublicCatalogEntry } from "./customer-view";
import { sellMonthlyCents } from "./pricing";

export async function loadPublicCatalog(opts: { previewAll?: boolean; limit?: number } = {}): Promise<PublicCatalogEntry[]> {
  const { rules, enabledRegions } = await loadRules();
  const items = await db.dedicatedCatalogItem.findMany({
    where: { removedAt: null, currency: "USD", ...(opts.previewAll ? {} : { visible: true }) },
    include: { options: true },
    orderBy: { monthlyCents: "asc" },
  });
  const avail = await loadAvailability(items.map((i) => i.planCode));
  const out: PublicCatalogEntry[] = [];
  for (const it of items) {
    const stock = stockByDc(avail.get(it.planCode) ?? [], defaultConfig(it.options));
    const regions = itemRegions(it.datacenters, stock, enabledRegions, it.hiddenRegions);
    const entry = toPublicCatalogEntry(it, priceView(it, rules), regions, (cost) => sellMonthlyCents(0, { ...rules, markupFixedCents: 0, rounding: "none" }, { markupPercent: it.markupPercent }, cost));
    if (entry.regions.length === 0) continue;
    out.push(entry);
  }
  // One card per hardware build: regional variants of the same build merge their regions (cheapest price wins).
  const merged = new Map<string, PublicCatalogEntry>();
  for (const e of out) {
    const key = `${e.cpu}|${e.ramGb}|${e.storage}`;
    const prev = merged.get(key);
    if (!prev) {
      merged.set(key, { ...e, regions: [...e.regions] });
      continue;
    }
    for (const r of e.regions) {
      const have = prev.regions.find((x) => x.code === r.code);
      if (!have) prev.regions.push(r);
      else if (r.monthlyCents < have.monthlyCents) Object.assign(have, r);
    }
    if (e.monthlyCents < prev.monthlyCents) Object.assign(prev, { ...e, regions: prev.regions });
  }
  const list = [...merged.values()].sort((a, b) => a.tierOrder - b.tierOrder || a.monthlyCents - b.monthlyCents);
  return opts.limit ? list.slice(0, opts.limit) : list;
}
/**
 * DB loaders for the customer dedicated-server dashboard (and its admin preview).
 * Always returns the brand-safe projections from customer-view.ts.
 */
import type { DedicatedServer } from "@prisma/client";
import { db } from "../db";
import { toCustomerServerView, type CustomerInvoiceRow, type CustomerServerView } from "./customer-view";

export async function loadCustomerServers(userId: string): Promise<CustomerServerView[]> {
  const rows = await db.dedicatedServer.findMany({
    where: { userId, status: { not: "CANCELLED" } },
    include: { requests: { where: { status: "OPEN" }, select: { id: true, kind: true, status: true, createdAt: true } } },
    orderBy: { createdAt: "desc" },
  });
  return rows.map((r) => toCustomerServerView(r, r.requests));
}

/** One server, ONLY if it belongs to `userId` (pass null from the admin preview to skip the owner check). */
export async function loadCustomerServer(id: string, userId: string | null): Promise<{ view: CustomerServerView; invoices: CustomerInvoiceRow[] } | null> {
  const s = await db.dedicatedServer.findUnique({ where: { id }, include: { requests: { select: { id: true, kind: true, status: true, createdAt: true } } } });
  if (!s || (userId !== null && s.userId !== userId)) return null;
  const invoices = s.invoiceIds.length
    ? await db.invoice.findMany({ where: { id: { in: s.invoiceIds }, userId: s.userId }, orderBy: { createdAt: "desc" }, select: { id: true, number: true, description: true, amountCents: true, status: true, createdAt: true } })
    : [];
  return {
    view: toCustomerServerView(s, s.requests),
    invoices: invoices.map((i) => ({ ...i, status: String(i.status), createdAt: i.createdAt.toISOString() })),
  };
}

/**
 * A sample machine for the admin preview when no DedicatedServer exists yet.
 * Addresses are RFC 5737 / RFC 3849 documentation ranges, never real ones.
 */
export function sampleServer(now = new Date()): { view: CustomerServerView; invoices: CustomerInvoiceRow[] } {
  const renewal = new Date(now.getTime() + 18 * 86_400_000);
  const row = {
    id: "preview",
    userId: "preview",
    label: "Production database",
    hostname: "db1.example.com",
    catalogItemId: null,
    offerId: null,
    cpu: "AMD EPYC 4344P",
    cores: 8,
    threads: 16,
    ramGb: 64,
    storage: "2x 960GB NVMe (Soft RAID)",
    bandwidth: "1 Gbps public bandwidth",
    region: "sgp1",
    datacenter: null,
    providerServiceName: null,
    costMonthlyCents: null,
    ipv4: ["203.0.113.24", "203.0.113.25"],
    ipv6: ["2001:db8:3c4d:15::1/64"],
    os: "Ubuntu 24.04 LTS",
    status: "ACTIVE",
    credentialsUser: "root",
    credentialsEnc: "preview",
    credentialsDeliveredAt: now,
    renewalDate: renewal,
    renewalMonthlyCents: 18999,
    termMonths: 1,
    setupFeeCents: 0,
    invoiceIds: [],
    notes: "",
    provisionedAt: now,
    suspendedAt: null,
    suspendReason: null,
    cancelledAt: null,
    createdById: null,
    createdAt: now,
    updatedAt: now,
  } as unknown as DedicatedServer;
  return {
    view: toCustomerServerView(row, [{ id: "r1", kind: "REBOOT", status: "OPEN", createdAt: now }]),
    invoices: [
      { id: "i2", number: 1042, description: "Dedicated server", amountCents: 18999, status: "PAID", createdAt: new Date(now.getTime() - 12 * 86_400_000).toISOString() },
      { id: "i1", number: 987, description: "Dedicated server + setup", amountCents: 18999, status: "PAID", createdAt: new Date(now.getTime() - 42 * 86_400_000).toISOString() },
    ],
  };
}
import type { Metadata } from "next";
import { requireDedicatedPublic, dedicatedPublicEnabled } from "@/lib/dedicated/gate";
import { loadPublicCatalog } from "@/lib/dedicated/public-catalog";
import { DedicatedMarketing } from "@/components/dedicated/DedicatedMarketing";

/**
 * Public dedicated-server page. UNRELEASED: 404s until Setting
 * dedicated_public_enabled is on (lib/dedicated/gate.ts). Admins review it at
 * /admin/preview/dedicated. Not in the sitemap while the flag is off.
 */
export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const on = await dedicatedPublicEnabled();
  return {
    title: "Dedicated Servers — single-tenant bare metal",
    description: "Single-tenant dedicated servers with full root, dedicated IPv4 and always-on DDoS protection, in Nxeon regions. Live stock and monthly pricing.",
    alternates: { canonical: "/dedicated-servers" },
    robots: on ? { index: true, follow: true } : { index: false, follow: false },
  };
}

export default async function DedicatedServersPage() {
  await requireDedicatedPublic();
  const entries = await loadPublicCatalog();
  return <DedicatedMarketing entries={entries} />;
}
import { requireUser } from "@/lib/auth";
import { requireDedicatedPublic } from "@/lib/dedicated/gate";
import { loadCustomerServers } from "@/lib/dedicated/customer-data";
import { PageShell } from "@/components/nx/PageShell";
import { DedicatedServerList } from "@/components/dedicated/DedicatedServerList";

/** Customer dedicated servers. UNRELEASED: 404 until dedicated_public_enabled is on. */
export const dynamic = "force-dynamic";

export default async function DedicatedServersDashboard() {
  await requireDedicatedPublic();
  const user = await requireUser();
  const servers = await loadCustomerServers(user.id);
  return (
    <PageShell narrow eyebrow="Dedicated" title="Dedicated servers" sub="Single-tenant machines our team runs for you.">
      <DedicatedServerList servers={servers} />
    </PageShell>
  );
}
import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { requireDedicatedPublic } from "@/lib/dedicated/gate";
import { loadCustomerServer } from "@/lib/dedicated/customer-data";
import { DedicatedServerDashboard } from "@/components/dedicated/DedicatedServerDashboard";

/** One customer dedicated server. UNRELEASED: 404 until dedicated_public_enabled is on. */
export const dynamic = "force-dynamic";

export default async function DedicatedServerPage({ params }: { params: Promise<{ id: string }> }) {
  await requireDedicatedPublic();
  const user = await requireUser();
  const { id } = await params;
  const data = await loadCustomerServer(id, user.id);
  if (!data) notFound();
  return <DedicatedServerDashboard view={data.view} invoices={data.invoices} />;
}

/**
 * BRAND-SAFE projections for every customer/public dedicated-server surface.
 *
 * Nxeon speaks as the owner of its hardware: customers must never see an
 * upstream company/range name, plan code, service name, datacenter code or
 * URL. This module is the ONLY bridge from the admin catalogue/server rows to
 * customer components, and it:
 *   - copies only whitelisted, generic fields (CPU model, cores, RAM, disks,
 *     bandwidth, Nxeon region labels, Nxeon prices);
 *   - runs every free-text string through `brandSafe()` as a second net;
 *   - never includes providerServiceName / datacenter / planCode / costs.
 * test/dedicated-brand-voice.test.ts checks both the code and real fixtures.
 */
import type { DedicatedServer, DedicatedServerRequest } from "@prisma/client";
import type { PriceView, RegionRow } from "./catalog-view";
import { tierFor } from "./tiers";
import { customerDedicatedRegionLabel } from "./regions";

/** Words that would reveal a third-party supplier. Case-insensitive. */
export const BANNED_TERMS = ["ovhcloud", "ovh", "kimsufi", "so you start", "soyoustart", "so-you-start", "vrack", "hgr"] as const;

const BANNED_RE = new RegExp(`\\b(${BANNED_TERMS.map((t) => t.replace(/[-\s]/g, "[-\\s]?")).join("|")})\\b`, "gi");

export function containsBannedTerm(s: string): boolean {
  BANNED_RE.lastIndex = 0;
  return BANNED_RE.test(s);
}

/** Strip any supplier-revealing token from a string (and tidy the gaps it leaves). */
export function brandSafe(s: string | null | undefined): string {
  if (!s) return "";
  return s
    .replace(BANNED_RE, "")
    .replace(/\(\s*\)/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/^[\s|·,-]+|[\s|·,-]+$/g, "")
    .trim();
}

/** The supplier's default reverse-DNS hostname pattern (e.g. ns123.ip-1-2-3.net) gives the supplier away. */
export function isUpstreamDefaultHostname(h: string): boolean {
  return /^ns\d+\.ip-\d+-\d+-\d+\.[a-z]+$/i.test(h.trim());
}

export type PublicStock = "in-stock" | "limited" | "made-to-order" | "sold-out";

/** Customer wording for an upstream stock code. No delivery-time promise: we build by hand. */
export function publicStock(code: string): PublicStock {
  const m = /^(\d+)H(-low)?/.exec(code);
  if (!m) return "sold-out";
  if (Number(m[1]) > 24) return "made-to-order";
  return m[2] ? "limited" : "in-stock";
}

export const PUBLIC_STOCK_LABEL: Record<PublicStock, string> = {
  "in-stock": "In stock",
  limited: "Limited stock",
  "made-to-order": "Built to order",
  "sold-out": "Sold out",
};

export type PublicOption = { label: string; extraMonthlyCents: number; isDefault: boolean };

export type PublicCatalogEntry = {
  id: string;
  name: string;
  tier: string;
  tierBlurb: string;
  tierOrder: number;
  cpu: string;
  cores: number;
  threads: number;
  baseGhz: number | null;
  boostGhz: number | null;
  ramGb: number | null;
  storage: string;
  bandwidth: string;
  ddos: string;
  sla: number | null;
  monthlyCents: number;
  setupCents: number;
  /** Per-region Nxeon price: regional builds can cost more in some metros. */
  regions: { code: string; label: string; stock: PublicStock; monthlyCents: number; setupCents: number }[];
  ram: PublicOption[];
  disks: PublicOption[];
  network: PublicOption[];
};

export type CatalogSource = {
  id: string;
  range: string;
  displayName: string;
  cpuBrand: string;
  cpuModel: string;
  cpuCount: number;
  cpuCores: number;
  cpuThreads: number;
  cpuFrequencyGhz: number | null;
  cpuBoostGhz: number | null;
  defaultRamGb: number | null;
  defaultStorage: string | null;
  defaultBandwidthMbps: number | null;
  slaPercent: number | null;
  options: { family: string; label: string; isDefault: boolean; monthlyCents: number; removedAt?: Date | null }[];
};

const bw = (mbps: number | null) => (mbps == null ? "" : mbps >= 1000 ? `${+(mbps / 1000).toFixed(1)} Gbps` : `${mbps} Mbps`);

/**
 * One public catalogue card. `price` comes from catalog-view priceView (Nxeon
 * price only — cost and margin are deliberately not accepted as fields here).
 * `markOption` turns an option's upstream monthly cost into Nxeon's extra price.
 */
export function toPublicCatalogEntry(
  src: CatalogSource,
  price: Pick<PriceView, "sellMonthly" | "sellSetup">,
  regions: RegionRow[],
  markOption: (costCents: number) => number,
): PublicCatalogEntry {
  const t = tierFor(src.range);
  const cpu = brandSafe(`${src.cpuCount > 1 ? `${src.cpuCount}x ` : ""}${src.cpuBrand} ${src.cpuModel}`);
  const live = src.options.filter((o) => !o.removedAt);
  const opts = (fam: string[]): PublicOption[] =>
    live
      .filter((o) => fam.includes(o.family))
      .map((o) => ({ label: brandSafe(o.label), extraMonthlyCents: o.monthlyCents > 0 ? markOption(o.monthlyCents) : 0, isDefault: o.isDefault }))
      .sort((a, b) => a.extraMonthlyCents - b.extraMonthlyCents);
  return {
    id: src.id,
    name: brandSafe(src.displayName) || `${t.tier} ${cpu.replace(/^(AMD|Intel)\s+/i, "")}`.trim(),
    tier: t.tier,
    tierBlurb: t.blurb,
    tierOrder: t.order,
    cpu,
    cores: src.cpuCores * Math.max(1, src.cpuCount),
    threads: src.cpuThreads * Math.max(1, src.cpuCount),
    baseGhz: src.cpuFrequencyGhz,
    boostGhz: src.cpuBoostGhz,
    ramGb: src.defaultRamGb,
    storage: brandSafe(src.defaultStorage),
    bandwidth: src.defaultBandwidthMbps ? `${bw(src.defaultBandwidthMbps)} public bandwidth` : "",
    ddos: "Always-on DDoS protection",
    sla: src.slaPercent,
    monthlyCents: price.sellMonthly,
    setupCents: price.sellSetup,
    regions: regions
      .filter((r) => r.offered && !r.hidden)
      .map((r) => ({ code: r.code, label: r.customerLabel, stock: publicStock(r.stock), monthlyCents: price.sellMonthly, setupCents: price.sellSetup })),
    ram: opts(["memory"]),
    disks: opts(["storage", "system-storage"]),
    network: opts(["bandwidth"]).map((o) => ({ ...o, label: o.label.replace(/private bandwidth/i, "private network") })),
  };
}

/* ---------------- customer dashboard ---------------- */

export type CustomerServerStatus = "Being prepared" | "Being built" | "Online" | "Suspended" | "Cancelled";

const STATUS_LABEL: Record<string, CustomerServerStatus> = {
  PENDING: "Being prepared",
  PROVISIONING: "Being built",
  ACTIVE: "Online",
  SUSPENDED: "Suspended",
  CANCELLED: "Cancelled",
};

export type CustomerServerView = {
  id: string;
  label: string;
  hostname: string | null;
  status: CustomerServerStatus;
  statusKey: string;
  region: string;
  cpu: string;
  cores: number;
  threads: number;
  ramGb: number;
  storage: string;
  bandwidth: string;
  os: string | null;
  ipv4: string[];
  ipv6: string[];
  renewalDate: string | null;
  renewalMonthlyCents: number | null;
  termMonths: number;
  credentialsReady: boolean;
  credentialsUser: string | null;
  provisionedAt: string | null;
  suspendReason: string | null;
  openRequests: { id: string; kind: string; createdAt: string }[];
};

/**
 * Customer view of one machine. Takes the full row but copies a whitelist:
 * datacenter, providerServiceName, costMonthlyCents, notes, credentialsEnc and
 * createdById never leave this function.
 */
export function toCustomerServerView(s: DedicatedServer, requests: Pick<DedicatedServerRequest, "id" | "kind" | "status" | "createdAt">[] = []): CustomerServerView {
  return {
    id: s.id,
    label: brandSafe(s.label) || "Dedicated server",
    hostname: s.hostname && !containsBannedTerm(s.hostname) && !isUpstreamDefaultHostname(s.hostname) ? s.hostname : null,
    status: STATUS_LABEL[s.status] ?? "Being prepared",
    statusKey: s.status,
    region: customerDedicatedRegionLabel(s.region),
    cpu: brandSafe(s.cpu),
    cores: s.cores,
    threads: s.threads,
    ramGb: s.ramGb,
    storage: brandSafe(s.storage),
    bandwidth: brandSafe(s.bandwidth),
    os: s.os ? brandSafe(s.os) : null,
    ipv4: s.ipv4,
    ipv6: s.ipv6,
    renewalDate: s.renewalDate ? s.renewalDate.toISOString() : null,
    renewalMonthlyCents: s.renewalMonthlyCents,
    termMonths: s.termMonths,
    credentialsReady: !!s.credentialsDeliveredAt && !!s.credentialsEnc,
    credentialsUser: s.credentialsDeliveredAt ? s.credentialsUser : null,
    provisionedAt: s.provisionedAt ? s.provisionedAt.toISOString() : null,
    suspendReason: s.status === "SUSPENDED" ? brandSafe(s.suspendReason) || null : null,
    openRequests: requests.filter((r) => r.status === "OPEN").map((r) => ({ id: r.id, kind: r.kind, createdAt: r.createdAt.toISOString() })),
  };
}

export type CustomerInvoiceRow = { id: string; number: number; description: string; amountCents: number; status: string; createdAt: string };

export const REQUEST_KINDS = ["REBOOT", "REINSTALL", "RESCUE"] as const;
export type RequestKind = (typeof REQUEST_KINDS)[number];
export const REQUEST_LABEL: Record<RequestKind, string> = {
  REBOOT: "Reboot",
  REINSTALL: "Reinstall the OS",
  RESCUE: "Boot into rescue mode",
};
/**
 * Dedicated-server pricing rules — PURE (no DB, no clock), so the money math is
 * unit-tested in isolation (test/dedicated-pricing.test.ts).
 *
 * Nxeon price = round( cost x (1 + markup%) + fixed markup ), per the rounding
 * mode, unless the item carries a hard price override. The markup applies to
 * the configured options (RAM/storage/bandwidth upgrades) too, so a bigger
 * build never sells below cost. All amounts are integer cents in the
 * catalogue currency (USD for the subsidiary we sync by default).
 *
 * Where the knobs live:
 *   - global defaults: Settings (dedicated_markup_percent, dedicated_markup_fixed_cents,
 *     dedicated_rounding, dedicated_setup_policy, dedicated_setup_custom_cents)
 *   - per item: DedicatedCatalogItem.markupPercent / markupFixedCents /
 *     overrideMonthlyCents / setupPolicy / setupCustomCents (null = inherit)
 */

export const ROUNDING_MODES = ["none", "whole", "ninety-nine", "five"] as const;
export type RoundingMode = (typeof ROUNDING_MODES)[number];

export const SETUP_POLICIES = ["pass", "waived", "custom"] as const;
export type SetupPolicy = (typeof SETUP_POLICIES)[number];

export type PricingRules = {
  markupPercent: number;
  markupFixedCents: number;
  rounding: RoundingMode;
  setupPolicy: SetupPolicy;
  setupCustomCents: number;
};

export type ItemPricingOverride = {
  markupPercent?: number | null;
  markupFixedCents?: number | null;
  overrideMonthlyCents?: number | null;
  setupPolicy?: string | null;
  setupCustomCents?: number | null;
};

export const DEFAULT_RULES: PricingRules = {
  markupPercent: 25,
  markupFixedCents: 0,
  rounding: "ninety-nine",
  setupPolicy: "pass",
  setupCustomCents: 0,
};

export function isRoundingMode(v: string): v is RoundingMode {
  return (ROUNDING_MODES as readonly string[]).includes(v);
}
export function isSetupPolicy(v: string): v is SetupPolicy {
  return (SETUP_POLICIES as readonly string[]).includes(v);
}

/** Build rules from raw setting strings; anything unparseable falls back to DEFAULT_RULES. */
export function rulesFromSettings(s: Record<string, string | undefined>): PricingRules {
  const n = (v: string | undefined, d: number) => {
    const x = Number(v);
    return v != null && v.trim() !== "" && Number.isFinite(x) ? x : d;
  };
  const rounding = s.dedicated_rounding ?? "";
  const policy = s.dedicated_setup_policy ?? "";
  return {
    markupPercent: clampPercent(n(s.dedicated_markup_percent, DEFAULT_RULES.markupPercent)),
    markupFixedCents: Math.round(n(s.dedicated_markup_fixed_cents, DEFAULT_RULES.markupFixedCents)),
    rounding: isRoundingMode(rounding) ? rounding : DEFAULT_RULES.rounding,
    setupPolicy: isSetupPolicy(policy) ? policy : DEFAULT_RULES.setupPolicy,
    setupCustomCents: Math.max(0, Math.round(n(s.dedicated_setup_custom_cents, DEFAULT_RULES.setupCustomCents))),
  };
}

/** A markup below -100% would produce a negative price; above 1000% is a typo. */
export function clampPercent(p: number): number {
  if (!Number.isFinite(p)) return DEFAULT_RULES.markupPercent;
  return Math.min(1000, Math.max(-100, p));
}

/** Apply a rounding mode. Every mode rounds UP (never below the computed price). */
export function roundPrice(cents: number, mode: RoundingMode): number {
  const c = Math.max(0, Math.round(cents));
  switch (mode) {
    case "none":
      return c;
    case "whole":
      return Math.ceil(c / 100) * 100;
    case "ninety-nine":
      // smallest X.99 >= c  (13375 -> 13399, 13399 -> 13399, 13400 -> 13499, 0 -> 99)
      return Math.ceil((c + 1) / 100) * 100 - 1;
    case "five":
      return Math.ceil(c / 500) * 500;
  }
}

/** Effective markup for one item (item override wins, else the global rule). */
export function effectiveMarkup(rules: PricingRules, o: ItemPricingOverride = {}): { percent: number; fixedCents: number } {
  return {
    percent: o.markupPercent != null ? clampPercent(o.markupPercent) : rules.markupPercent,
    fixedCents: o.markupFixedCents != null ? Math.round(o.markupFixedCents) : rules.markupFixedCents,
  };
}

/**
 * Nxeon monthly price for a cost (base plan + any chosen option costs).
 * `overrideMonthlyCents` is a hard price for the DEFAULT build; options chosen
 * on top of it are still marked up so an override can't silently give away
 * upgrades at cost.
 */
export function sellMonthlyCents(baseCostCents: number, rules: PricingRules, o: ItemPricingOverride = {}, optionCostCents = 0): number {
  const { percent, fixedCents } = effectiveMarkup(rules, o);
  const markOpts = optionCostCents * (1 + percent / 100);
  if (o.overrideMonthlyCents != null && o.overrideMonthlyCents >= 0) {
    return Math.round(o.overrideMonthlyCents) + Math.ceil(markOpts);
  }
  const raw = (baseCostCents + optionCostCents) * (1 + percent / 100) + fixedCents;
  return roundPrice(raw, rules.rounding);
}

/**
 * Nxeon setup fee. "pass" passes through what the setup costs us right now —
 * the promotional setup when a live upstream promotion lowers it, else the
 * list setup fee. "waived" = 0. "custom" = a fixed admin-set fee.
 */
export function sellSetupCents(
  costSetupCents: number,
  rules: PricingRules,
  o: ItemPricingOverride = {},
  promoSetupCents: number | null = null,
): number {
  const policy = o.setupPolicy && isSetupPolicy(o.setupPolicy) ? o.setupPolicy : rules.setupPolicy;
  if (policy === "waived") return 0;
  if (policy === "custom") return Math.max(0, Math.round(o.setupCustomCents ?? rules.setupCustomCents));
  return Math.max(0, Math.round(promoSetupCents ?? costSetupCents));
}

/** What the setup actually costs us (promotion-aware). */
export function effectiveSetupCost(setupCents: number, promoSetupCents: number | null): number {
  return Math.max(0, promoSetupCents ?? setupCents);
}

export type Margin = { cents: number; percent: number | null };

/** Margin of a sell price over a cost; percent is of the SELL price (gross margin). */
export function margin(costCents: number, sellCents: number): Margin {
  const cents = sellCents - costCents;
  return { cents, percent: sellCents > 0 ? Math.round((cents / sellCents) * 1000) / 10 : null };
}

/**
 * First-year economics for one build: what we pay, what we charge, the margin —
 * including the setup fee leg (which can be negative when setup is waived).
 */
export function firstYearMargin(args: { monthlyCost: number; monthlySell: number; setupCost: number; setupSell: number }): Margin {
  const cost = args.monthlyCost * 12 + args.setupCost;
  const sell = args.monthlySell * 12 + args.setupSell;
  return margin(cost, sell);
}

/** Months until the setup fee we absorb is paid back by the monthly margin (null = never). */
export function setupPaybackMonths(args: { monthlyCost: number; monthlySell: number; setupCost: number; setupSell: number }): number | null {
  const absorbed = args.setupCost - args.setupSell;
  if (absorbed <= 0) return 0;
  const perMonth = args.monthlySell - args.monthlyCost;
  if (perMonth <= 0) return null;
  return Math.ceil(absorbed / perMonth);
}

export function money(cents: number, currency = "USD"): string {
  const sign = cents < 0 ? "-" : "";
  const v = Math.abs(cents) / 100;
  const sym = currency === "USD" || currency === "CAD" || currency === "AUD" || currency === "SGD" ? "$" : currency === "EUR" ? "€" : currency === "GBP" ? "£" : `${currency} `;
  return `${sign}${sym}${v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}
