"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { dedicatedIpPurchaseQuote, applyDedicatedIpPurchase, DedicatedIpPurchaseError } from "./dedicated-ip-purchase";
import { createDedicatedIpCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Add dedicated IP": give an ALREADY-provisioned server (VPS or
 * game) its own dedicated public IPv4, for a server that doesn't already have
 * one. Money path is a carbon copy of lib/actions-disk.ts expandServerDisk:
 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
 * The wallet is only ever debited by applyDedicatedIpPurchase, and only after
 * the card portion has cleared, so displayed === charged and nothing is
 * charged twice. The actual IP claim + network reconfiguration happens
 * asynchronously in the worker (ASSIGN_DEDICATED_IP) — see
 * lib/dedicated-ip-purchase.ts's header for why that split is deliberate.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function purchaseDedicatedIp(
  serverId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating — same
  // guard as every other money movement on a server (resizeServer,
  // expandServerDisk).
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: this is an irreversible real-infra charge. See
  // lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  if (server.dedicatedIp) return { error: "This server already has a dedicated IP." };

  // Reject while another job is in flight, and only from a steady run state.
  // (applyDedicatedIpPurchase re-checks both; this returns the friendlier
  // message first.)
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to add a dedicated IP." };
  }
  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  let quote;
  try {
    quote = await dedicatedIpPurchaseQuote(serverId);
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the resize/disk-expand flows.
  // AddDedicatedIp computes the same split (lib/wallet-split.ts) so
  // displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  if (cardCents > 0) {
    const checkout = await createDedicatedIpCheckout(user, cardCents, {
      serverId,
      hostname: server.hostname,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `A dedicated IP costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  try {
    await applyDedicatedIpPurchase({ serverId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

