/**
 * Shared, mostly-pure computations over the synced catalogue: per-region stock,
 * sell prices, and the admin/customer row shapes. DB loaders at the bottom.
 * ADMIN data (upstream names/codes) flows through here; the CUSTOMER projection
 * is lib/dedicated/customer-view.ts, which only takes what this module computes
 * and drops every upstream identifier.
 */
import { db } from "../db";
import { getAllSettings } from "../settings";
import { isInStock, stockRank } from "./ovh-catalog";
import { DEDICATED_DC_REGIONS, regionForDc, type DedicatedRegion } from "./regions";
import {
  effectiveSetupCost,
  margin,
  rulesFromSettings,
  sellMonthlyCents,
  sellSetupCents,
  type ItemPricingOverride,
  type Margin,
  type PricingRules,
} from "./pricing";

export type AvailRow = { planCode: string; memory: string | null; storage: string | null; datacenter: string; availability: string };

/** Best stock code per datacenter for a plan; optionally only the given memory/storage configuration. */
export function stockByDc(rows: AvailRow[], config?: { memory?: string | null; storage?: string | null }): Map<string, string> {
  const out = new Map<string, string>();
  for (const r of rows) {
    if (config?.memory && r.memory && r.memory !== config.memory) continue;
    if (config?.storage && r.storage && r.storage !== config.storage) continue;
    const prev = out.get(r.datacenter);
    if (!prev || stockRank(r.availability) < stockRank(prev)) out.set(r.datacenter, r.availability);
  }
  return out;
}

export type RegionRow = DedicatedRegion & {
  dcs: string[];
  /** Best stock across the region's datacenters ("" when the feed has nothing). */
  stock: string;
  inStock: boolean;
  /** Owner offers dedicated servers in this region (setting). */
  offered: boolean;
  /** Hidden for this item only. */
  hidden: boolean;
};

/** Group an item's datacenters into Nxeon regions with stock + offer flags. */
export function itemRegions(datacenters: string[], stock: Map<string, string>, enabledRegions: Set<string>, hiddenRegions: string[]): RegionRow[] {
  const byCode = new Map<string, RegionRow>();
  for (const dc of datacenters) {
    const r = regionForDc(dc);
    const s = stock.get(dc) ?? "";
    const prev = byCode.get(r.code);
    if (prev) {
      prev.dcs.push(dc);
      if (s && (!prev.stock || stockRank(s) < stockRank(prev.stock))) {
        prev.stock = s;
        prev.inStock = isInStock(s);
      }
      continue;
    }
    byCode.set(r.code, { ...r, dcs: [dc], stock: s, inStock: isInStock(s), offered: enabledRegions.has(r.code), hidden: hiddenRegions.includes(r.code) });
  }
  return [...byCode.values()];
}

export function parseRegionList(v: string | undefined | null): Set<string> {
  return new Set((v ?? "").split(",").map((s) => s.trim()).filter(Boolean));
}

export type PriceView = {
  costMonthly: number;
  sellMonthly: number;
  costSetup: number;
  sellSetup: number;
  margin: Margin;
};

export function priceView(
  item: { monthlyCents: number; setupCents: number; promoSetupCents: number | null } & ItemPricingOverride,
  rules: PricingRules,
  optionCostCents = 0,
): PriceView {
  const costMonthly = item.monthlyCents + optionCostCents;
  const sellMonthly = sellMonthlyCents(item.monthlyCents, rules, item, optionCostCents);
  const costSetup = effectiveSetupCost(item.setupCents, item.promoSetupCents);
  const sellSetup = sellSetupCents(item.setupCents, rules, item, item.promoSetupCents);
  return { costMonthly, sellMonthly, costSetup, sellSetup, margin: margin(costMonthly, sellMonthly) };
}

export { TIER_BY_RANGE, tierFor } from "./tiers";

/* ---------------- DB loaders ---------------- */

export async function loadRules(): Promise<{ rules: PricingRules; enabledRegions: Set<string>; settings: Record<string, string> }> {
  const settings = await getAllSettings();
  return { rules: rulesFromSettings(settings), enabledRegions: parseRegionList(settings.dedicated_enabled_regions), settings };
}

export async function loadAvailability(planCodes: string[]): Promise<Map<string, AvailRow[]>> {
  const rows = planCodes.length
    ? await db.dedicatedAvailability.findMany({ where: { planCode: { in: planCodes } }, select: { planCode: true, memory: true, storage: true, datacenter: true, availability: true } })
    : [];
  const out = new Map<string, AvailRow[]>();
  for (const r of rows) {
    const a = out.get(r.planCode) ?? [];
    a.push(r);
    out.set(r.planCode, a);
  }
  return out;
}

/** Default memory/storage product codes for an item's stock lookup. */
export function defaultConfig(options: { family: string; isDefault: boolean; productCode: string; removedAt?: Date | null }[]): { memory: string | null; storage: string | null } {
  const live = options.filter((o) => !o.removedAt);
  return {
    memory: live.find((o) => o.family === "memory" && o.isDefault)?.productCode ?? null,
    storage: live.find((o) => o.family === "storage" && o.isDefault)?.productCode ?? null,
  };
}

