6	/* The page frame every account-area screen shares.
7	 *
8	 * WIDTH. These pages had no `max-width` at all, so they filled `<main>` — about
9	 * 1630px on a 1878px screen — while the dashboard is capped at 1520. That is
10	 * the whole reason they read as "very wide": nothing was holding them in. This
11	 * caps them at the SAME 1520 the dashboard uses, so the measure is identical
12	 * from page to page. (The original concept boards are tighter still, about
13	 * 1250 of content inside a 1536 board; `narrow` opts into that for pages whose
14	 * content is a single column of forms and rows rather than a grid, where a long
15	 * measure is genuinely harder to read.)
16	 *
17	 * HERO. Every concept screen opens the same way: a tracked magenta eyebrow, an
18	 * H1, one line of explanation, and the right-aligned tracked tagline block.
19	 * Reproducing that by hand on six pages is how six pages end up with six
20	 * slightly different heroes.
21	 */
22	export function PageShell({
23	  eyebrow, title, sub, tagline = ["SAME INFRASTRUCTURE.", "A BRIGHTER TOMORROW."],
24	  action, narrow = false, wisp = true, heroImage, heroArt, children,
25	}: {
26	  eyebrow: string;
27	  title: string;
28	  sub?: string;
29	  /** The tracked block on the right. Two or three short lines, in caps. */
30	  tagline?: string[];
31	  /** Optional control in the hero's top-right (below the tagline on mobile). */
32	  action?: React.ReactNode;
33	  narrow?: boolean;
34	  /**
35	   * The static radial-gradient patch behind the header. Every other page with
36	   * its OWN animated aurora (Mail, Billing, Team, Support...) doesn't render
37	   * this header at all — it hand-rolls one and skips the wisp entirely, which
38	   * is why they never collided with it. Tools is the first page to keep using
39	   * this shared header while ALSO mounting a dedicated aurora underneath, and
40	   * the two stacked into a visible boxy patch on top of the animated one. Set
41	   * `false` when the page already supplies its own atmosphere.
42	   */
43	  wisp?: boolean;
44	  /**
45	   * A large decorative illustration anchored to the header's right side (a
46	   * real image, not a drawn glyph — e.g. the domains globe or the SSL shield).
47	   * Grows the header to give it real room instead of squeezing it into the
48	   * text row's leftover space.
49	   */
50	  heroImage?: string;
51	  /**
52	   * Vector hero art (an inline SVG composition) in place of a raster
53	   * `heroImage`. Crisp at any pixel density and theme-aware, because it draws
54	   * from the colour tokens instead of baking a palette into pixels. Anchored
55	   * BELOW the tracked tagline (not beside it), so the two never overlap, and
56	   * hidden under `sm` — the header only reserves height for it where it shows,
57	   * so phones don't get the empty band a hidden raster used to leave.
58	   */
59	  heroArt?: React.ReactNode;
60	  children: React.ReactNode;
61	}) {
62	  const hasArt = !!heroImage || !!heroArt;
63	  return (
64	    <div className={"mx-auto flex w-full flex-col gap-4 " + (narrow ? "max-w-[1180px]" : "max-w-[1520px]")}>
65	      <header className={"relative overflow-hidden " + (heroImage ? "min-h-[280px] sm:min-h-[300px]" : heroArt ? "sm:min-h-[248px]" : "")}>
66	        {/* The aurora wisp the concept runs behind every hero. Decorative, so it
67	            is `pointer-events-none` and sits under the text. Skipped when a real
68	            hero image is present — the two washes fight for the same corner. */}
69	        {wisp && !hasArt && (
70	          <span aria-hidden
71	                className="pointer-events-none absolute -top-10 right-[16%] hidden h-[210px] w-[52%] opacity-70 md:block"
72	                style={{
73	                  background:
74	                    "radial-gradient(60% 120% at 50% 50%, rgba(64,150,255,0.20), transparent 70%)," +
75	                    "radial-gradient(38% 90% at 66% 42%, rgba(168,60,255,0.16), transparent 72%)",
76	                  filter: "blur(14px)",
77	                }} />
78	        )}
79	        {heroImage && (
80	          // eslint-disable-next-line @next/next/no-img-element -- a static hero illustration, not an optimizable content image.
81	          //
82	          // `right-[13%]`, NOT flush against the edge: the tracked tagline block
83	          // below is pinned to the header's true right edge (`ml-auto`), same as
84	          // this image's box. Anchoring the image flush right (its original
85	          // `-right-4`) put both in the same corner and the wide 900x600 source
86	          // art (this renders ~1.5x wider than tall) drew straight over the
87	          // tagline text — SSL's is the only page exercising this prop so far.
88	          // `right-[13%]` is the same inset the domains page's hand-rolled hero
89	          // uses for its own tagline-vs-globe pairing at a similar image size;
90	          // it leaves the tagline its own clear strip at the edge.
91	          <img
92	            src={heroImage}
93	            alt=""
94	            aria-hidden
95	            className="pointer-events-none absolute -top-6 right-[13%] hidden h-[280px] w-auto object-contain sm:block sm:h-[300px]"
96	          />
97	        )}
98	        {heroArt && (
99	          <div aria-hidden
100	               className="pointer-events-none absolute right-0 top-9 hidden h-[212px] w-[min(48%,380px)] sm:block md:h-[232px] md:w-[min(46%,414px)]">
101	            {heroArt}
102	          </div>
103	        )}
104	        <div className="relative flex flex-wrap items-start justify-between gap-x-6 gap-y-3 pb-1">
105	          <div className={"flex min-w-0 flex-col gap-1 " + (heroArt ? "sm:max-w-[52%]" : "")}>
106	            <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#f21cff]">{eyebrow}</span>
107	            <h1 className="text-[27px] font-extrabold leading-[1.08] tracking-[-0.032em] text-white sm:text-[31px]">
108	              {title}
109	            </h1>
110	            {sub && <p className="max-w-[62ch] text-[13px] leading-[1.5] text-tx-mute">{sub}</p>}
111	          </div>
112	          <div className="ml-auto flex flex-none items-center gap-4">
113	            <span className="hidden flex-col items-end gap-[3px] lg:flex">
114	              {tagline.map((l) => (
115	                <span key={l} className="text-[10px] font-semibold uppercase tracking-[0.28em] text-tx-faint">{l}</span>
116	              ))}
117	            </span>
118	            {action}
119	          </div>
120	        </div>
121	      </header>
122	      {children}
123	    </div>
124	  );
125	}
