127	/** A card with the concept's header row: title left, optional control right. */
128	export function Panel({
129	  title, sub, action, className = "", bodyClass = "", style, glassId, children,
130	}: {
131	  title?: string; sub?: string; action?: React.ReactNode;
132	  className?: string; bodyClass?: string;
133	  /** For .card-glass's --tone custom property. */
134	  style?: React.CSSProperties;
135	  /** Mounts this panel's OWN <GlassFilters> and points --lens at it. Give
136	      every `card-glass` panel a DIFFERENT id — one filter definition shared
137	      by several cards is a confirmed way to ghost their text (see
138	      GlassFilters.tsx). Omit entirely for a panel that should not use the
139	      lens distortion at all. */
140	  glassId?: string;
141	  children: React.ReactNode;
142	}) {
143	  const glassStyle = glassId
144	    ? { ...style, "--lens": `url(#${glassId})` } as React.CSSProperties
145	    : style;
146	  return (
147	    <section style={glassStyle} className={"card flex min-w-0 flex-col gap-3 p-4 " + className}>
148	      {glassId && <GlassFilters id={glassId} />}
149	      {(title || action) && (
150	        <div className="flex flex-none items-start justify-between gap-3">
151	          <span className="flex min-w-0 flex-col gap-0.5">
152	            {title && <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">{title}</span>}
153	            {sub && <span className="text-[11.5px] text-tx-faint">{sub}</span>}
154	          </span>
155	          {action}
156	        </div>
157	      )}
158	      <div className={"flex min-w-0 flex-col " + bodyClass}>{children}</div>
159	    </section>
160	  );
161	}
