163	/* One of the small figure cards the concept opens each page with: a number, a
164	   label, and a mark. Kept here so billing, support and activity cannot each
165	   invent their own version. */
166	export function StatCard({
167	  icon, value, label, foot, tone = "blue", volatileValue, bareIcon,
168	}: {
169	  icon: string; value: string; label: string; foot?: React.ReactNode;
170	  tone?: "blue" | "mint" | "amber" | "violet";
171	  /** Set when `value` is derived from the reader's locale or clock (a formatted
172	      date, a "3 days" countdown). Those legitimately differ between the server
173	      render and the browser's, and React tears the tree down over it unless it
174	      is told the difference is expected. */
175	  volatileValue?: boolean;
176	  /** No bordered plate behind the mark, and a larger mark so it still reads as
177	   *  intentional without one. Sized against the value's cap height rather than
178	   *  the whole text block — the first pass doubled it to 34 (51px after
179	   *  ICON_SCALE), which was about 2.4x the number beside it and read as
180	   *  oversized on every page that uses these. */
181	  bareIcon?: boolean;
182	}) {
183	  const ring = tone === "mint" ? "rgba(17,200,142,0.30)"
184	             : tone === "amber" ? "rgba(240,180,60,0.30)"
185	             : tone === "violet" ? "rgba(147,51,255,0.32)"
186	             : "rgba(47,126,239,0.32)";
187	  return (
188	    // `min-h` so a card with a `foot` line (an extra line of text under the
189	    // label) doesn't render visibly taller than its foot-less siblings in
190	    // the same stat row — every consumer mixes the two (Support's "Avg
191	    // response time" card only grows a foot when there's no data yet).
192	    <section className="card flex min-h-[88px] min-w-0 items-start gap-3 p-3.5">
193	      {bareIcon ? (
194	        <Icon name={icon} size={24} />
195	      ) : (
196	        <span className="grid h-[42px] w-[42px] flex-none place-items-center rounded-[11px] border border-rim-hi"
197	              style={{ background: "linear-gradient(180deg, rgba(24,74,180,0.55), rgba(4,20,60,0.9))", boxShadow: `inset 0 0 0 1px ${ring}` }}>
198	          <Icon name={icon} size={17} />
199	        </span>
200	      )}
201	      <span className="flex min-w-0 flex-col gap-0.5">
202	        <span suppressHydrationWarning={volatileValue} className="num text-[23px] leading-none text-white">{value}</span>
203	        <span className="text-[11.5px] text-tx-dim">{label}</span>
204	        {foot}
205	      </span>
206	    </section>
207	  );
208	}
