224	            <li key={s} className="flex min-w-0 flex-1 items-center gap-2">
225	              <button
226	                onClick={() => i <= at && onJump(i)}
227	                disabled={i > at}
228	                className={"flex min-w-0 items-center gap-2.5 rounded-[10px] px-3 py-2 transition-colors " +
229	                  (now ? "bg-[linear-gradient(100deg,rgba(26,85,207,0.9),rgba(111,46,224,0.55))] shadow-[0_0_16px_-10px_rgba(31,123,255,0.52)]"
230	                       : done ? "hover:bg-[rgba(72,148,255,0.08)]" : "opacity-55")}
231	              >
232	                <span className={"grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold " +
233	                  (done ? "bg-[linear-gradient(100deg,#0f9169,#11c88e)] text-[#01201a]"
234	                        : now ? "bg-[#fff] text-[#0a1f52]" : "border border-rim-hi text-tx-faint")}>
235	                  {/* tone="inherit" — the icon otherwise forces its own mint-green
236	                      class, which on this cyan/green gradient is a green tick on
237	                      a green disc: unreadable in both themes. */}
238	                  {done ? <Icon name="checkcircle" size={13} tone="inherit" /> : i + 1}
239	                </span>
240	                <span className={"trunc text-[13px] font-bold " + (now ? "text-white" : done ? "text-tx-body" : "text-tx-faint")}>
241	                  {s}
242	                </span>
243	              </button>
244	              {i < steps.length - 1 && (
245	                <span className={"h-px min-w-3 flex-1 " + (done ? "bg-[rgba(0,227,154,0.4)]" : "bg-rim-soft")} />
246	              )}
247	            </li>
248	          );
249	        })}
250	      </ol>
251	
252	      <div className="flex flex-col gap-2 md:hidden">
253	        <div className="flex items-baseline justify-between">
254	          <span className="text-[15px] font-extrabold text-white">{steps[at]}</span>
255	          <span className="label">Step {at + 1} of {steps.length}</span>
256	        </div>
257	        <div className="meter"><i style={{ width: `${((at + 1) / steps.length) * 100}%` }} /></div>
258	      </div>
259	    </>
260	  );
261	}
