529	   Floating, no panel behind them: done is a filled mint disc with a tick,
530	   the current step is a filled brand disc with a ring, the rest are hollow.
531	   The connector fills as you advance. */
532	export function StepMarks({ steps, i, go }: {
533	  steps: { key: string; label: string; done: boolean; live: boolean }[];
534	  i: number; go: (n: number) => void;
535	}) {
536	  return (
537	    /* `overflow-x-auto` was already here, but `justify-center` on a flex row
538	       that overflows is a well-known trap: the browser centers the content
539	       BEFORE laying out the scrollable area, so the steps before whatever
540	       lands at `scrollLeft: 0` sit at a negative x-offset — reachable by
541	       scrolling right from the middle, but `scrollLeft` can never go
542	       negative, so the earliest step(s) were permanently unreachable, not
543	       just visually cramped. `justify-start` below the phone breakpoint
544	       gives the scroll area a real, reachable 0 at the actual first step;
545	       `sm:justify-center` keeps the original centered look once the whole
546	       rail fits without scrolling. */
547	    <ol className="noscroll mx-auto flex w-full max-w-[720px] items-start justify-start gap-0 overflow-x-auto px-2 sm:justify-center">
548	      {steps.map((s, n) => {
549	        const cur = n === i, past = n < i;
550	        return (
551	          <li key={s.key} className="flex flex-none items-start">
552	            <button onClick={() => s.live && go(n)} disabled={!s.live}
553	                    aria-current={cur ? "step" : undefined}
554	                    className="group flex w-[104px] flex-col items-center gap-2 disabled:cursor-default">
555	              <span className={"grid h-[30px] w-[30px] place-items-center rounded-full text-[12.5px] font-extrabold transition-all duration-300 " +
556	                (past ? "bg-[linear-gradient(135deg,#14c5e4,#11c88e)] text-[#012019]"
557	                      : cur ? "bg-[linear-gradient(135deg,#2f7eef,#6f2ee0)] text-[#fff] ring-[3px] ring-[rgba(111,46,224,0.28)]"
558	                            : "border border-rim-hi text-tx-faint")}>
559	                {/* tone="inherit" — see the same fix in Band above. */}
560	                {past ? <Icon name="checkcircle" size={14} tone="inherit" /> : n + 1}
561	              </span>
562	              <span className={"whitespace-nowrap text-[11.5px] font-bold transition-colors " +
563	                (cur ? "text-white" : past ? "text-tx-body" : "text-tx-faint")}>{s.label}</span>
564	            </button>
565	            {n < steps.length - 1 && (
566	              <span aria-hidden
567	                    className={"mt-[15px] h-px w-8 flex-none transition-colors duration-300 " +
568	                      (past ? "bg-[linear-gradient(90deg,#14c5e4,#11c88e)]" : "bg-rim-hi")} />
569	            )}
570	          </li>
571	        );
572	      })}
573	    </ol>
574	  );
575	}
