"use server";

/**
 * CUSTOMER actions on a dedicated server. We do not automate reboot /
 * reinstall / rescue on dedicated hardware, so each "action" is a REQUEST:
 * it opens an ordinary support ticket (same path as /dashboard/support) and a
 * DedicatedServerRequest row that staff close from the admin server page.
 *
 * Every action: flag-gated (dedicated_public_enabled — off means the feature
 * does not exist), owner-checked, rate-limited. All customer-visible text is in
 * Nxeon's own voice (no supplier names).
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { decryptSecret } from "./crypto-box";
import { createTicketCore } from "./reply-core";
import { mirrorNewTicketToDiscord } from "./discord-bridge";
import { dedicatedPublicEnabled } from "./dedicated/gate";
import { REQUEST_KINDS, REQUEST_LABEL, type RequestKind } from "./dedicated/customer-view";

type Result = { ok: true; ticketId?: string } | { ok: false; error: string };

async function ownedDedicated(serverId: string) {
  const user = await requireUser();
  if (!(await dedicatedPublicEnabled())) throw new Error("Not found");
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || s.userId !== user.id) throw new Error("Not found");
  return { user, server: s };
}

export async function requestDedicatedAction(serverId: string, kind: string, detail: string): Promise<Result> {
  try {
    await assertNotImpersonating();
    const { user, server } = await ownedDedicated(serverId);
    if (!(REQUEST_KINDS as readonly string[]).includes(kind)) return { ok: false, error: "Unknown request." };
    if (server.status === "CANCELLED") return { ok: false, error: "This server has been cancelled." };
    if (!checkRateLimit(`dedicated-req:${user.id}`, { max: 6, windowMs: 60 * 60_000 }).ok) {
      return { ok: false, error: "Too many requests in the last hour. Our team already has your earlier ones." };
    }
    const open = await db.dedicatedServerRequest.findFirst({ where: { dedicatedServerId: server.id, kind, status: "OPEN" }, select: { ticketId: true } });
    if (open) return { ok: false, error: "That request is already with our team." };
    const k = kind as RequestKind;
    const note = detail.trim().slice(0, 2000);
    const ticket = await createTicketCore({
      userId: user.id,
      subject: `${REQUEST_LABEL[k]}: ${server.label}`.slice(0, 150),
      body:
        `Request from the dedicated server dashboard.\n\n` +
        `Server: ${server.label}${server.hostname ? ` (${server.hostname})` : ""}\n` +
        `Requested: ${REQUEST_LABEL[k]}\n` +
        (server.ipv4[0] ? `Primary IP: ${server.ipv4[0]}\n` : "") +
        (note ? `\nNotes from the customer:\n${note}\n` : ""),
      priority: k === "RESCUE" ? "HIGH" : "NORMAL",
    });
    await db.dedicatedServerRequest.create({ data: { dedicatedServerId: server.id, userId: user.id, kind: k, detail: note, ticketId: ticket.ticketId } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: user.id, action: `request_${k.toLowerCase()}`, detail: `ticket ${ticket.ticketId}` } });
    await mirrorNewTicketToDiscord(ticket.ticketId);
    revalidatePath(`/dashboard/dedicated/${server.id}`);
    return { ok: true, ticketId: ticket.ticketId };
  } catch (e) {
    return { ok: false, error: e instanceof Error && e.message !== "UNAUTHORIZED" ? e.message : "Not found" };
  }
}

/** Reveal the delivered login once the customer asks (decrypted server-side, never logged). */
export async function revealDedicatedCredentials(serverId: string): Promise<{ ok: true; username: string; secret: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedDedicated(serverId);
    if (!checkRateLimit(`dedicated-cred:${user.id}`, { max: 20, windowMs: 60 * 60_000 }).ok) return { ok: false, error: "Try again later." };
    if (!server.credentialsDeliveredAt || !server.credentialsEnc) return { ok: false, error: "Your login details are not ready yet." };
    const secret = decryptSecret(server.credentialsEnc);
    if (!secret) return { ok: false, error: "Could not read the stored login. Please contact support." };
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: user.id, action: "credentials_viewed" } });
    return { ok: true, username: server.credentialsUser ?? "root", secret };
  } catch {
    return { ok: false, error: "Not found" };
  }
}
