/**
 * Dedicated-server CHECKOUT — the server side of /dashboard/dedicated/order.
 *
 *   catalogue  loadOrderCatalog()        brand-safe cards (one per hardware build)
 *   configure  loadOrderBuild(id)        one build's regions, options, in-stock combos, exact prices
 *   quote      quoteDedicatedOrder()     re-prices an intent from the pricing rules (never trusts the client)
 *   place      placeDedicatedOrder()     wallet debit + PAID invoice + DedicatedServer(PENDING), atomically
 *
 * Money path is the portal's standard wallet-then-card shape (same as the VPS /
 * dedicated-IP flows): quote -> walletSplit -> card remainder via a Stripe
 * Custom Checkout session whose metadata stamps the intent + the price ->
 * lib/fulfil-checkout.ts credits the card leg to the wallet and calls
 * placeDedicatedOrder with the STAMPED price. The wallet is only ever debited
 * here, once, guarded by a FulfilledSession claim on the order key.
 *
 * Nothing is provisioned automatically: the row lands as PENDING in
 * /admin/dedicated/servers and staff build the machine by hand. Upstream plan
 * codes, datacenters and costs are written ONLY to admin-only columns.
 *
 * Every function that returns data to a customer returns brand-safe fields only
 * (see lib/dedicated/customer-view.ts). Option and item ids are opaque cuids.
 */
import type { DedicatedCatalogItem, DedicatedCatalogOption, User } from "@prisma/client";
import { db } from "../db";
import { debitWallet, InsufficientBalanceError } from "../wallet";
import { invoiceCreateData } from "../invoices";
import { taxContextForUser } from "../tax";
import { assertSpendCap, SpendCapError } from "../spend-caps";
import { defaultConfig, itemRegions, loadAvailability, loadRules, priceView, stockByDc, type AvailRow } from "./catalog-view";
import { brandSafe, publicStock, type PublicStock } from "./customer-view";
import { tierFor } from "./tiers";
import { regionByCode, regionForDc } from "./regions";
import { stockRank } from "./ovh-catalog";
import type { PricingRules } from "./pricing";
import { addMonths, orderMoney, osById, renewalLabel, termLabel, type DedicatedOrderIntent, type DedicatedOrderMoney } from "./order-core";

type ItemWithOptions = DedicatedCatalogItem & { options: DedicatedCatalogOption[] };

export class DedicatedOrderError extends Error {}

/** Stock codes a customer may order: delivered within 24h. */
export function orderableStock(code: string | undefined | null): boolean {
  const s = publicStock(code ?? "");
  return s === "in-stock" || s === "limited";
}

/* ---------------- loading ---------------- */

/**
 * Items a customer may order. Normally only items an admin marked `visible`.
 * `previewAll`: the private preview shows every live item while NO item has been
 * published yet, so the owner can test the flow before curating the catalogue.
 */
export async function orderPreviewAll(preview: boolean): Promise<boolean> {
  if (!preview) return false;
  const visible = await db.dedicatedCatalogItem.count({ where: { visible: true, removedAt: null } });
  return visible === 0;
}

async function loadItems(previewAll: boolean, where: Record<string, unknown> = {}): Promise<ItemWithOptions[]> {
  return db.dedicatedCatalogItem.findMany({
    where: { removedAt: null, currency: "USD", ...(previewAll ? {} : { visible: true }), ...where },
    include: { options: true },
    orderBy: { monthlyCents: "asc" },
  });
}

const live = (o: DedicatedCatalogOption) => !o.removedAt;
const fam = (it: ItemWithOptions, f: string) => it.options.filter((o) => live(o) && o.family === f);
const defaultOf = (it: ItemWithOptions, f: string) => fam(it, f).find((o) => o.isDefault) ?? fam(it, f)[0] ?? null;

function hardwareKey(it: ItemWithOptions): string {
  return `${it.cpuBrand}|${it.cpuModel}|${it.cpuCount}|${it.defaultRamGb}|${it.defaultStorage}`;
}

/** Monthly option cost delta of a chosen option over its family default (never negative). */
function optionDelta(it: ItemWithOptions, f: string, chosen: DedicatedCatalogOption | null): number {
  if (!chosen) return 0;
  const d = defaultOf(it, f);
  return Math.max(0, chosen.monthlyCents - (d?.monthlyCents ?? 0));
}

function sellFor(it: ItemWithOptions, rules: PricingRules, mem: DedicatedCatalogOption | null, disk: DedicatedCatalogOption | null, bw: DedicatedCatalogOption | null) {
  const optCost = optionDelta(it, "memory", mem) + optionDelta(it, "storage", disk) + optionDelta(it, "bandwidth", bw);
  return { ...priceView(it, rules, optCost), optCost };
}

/** Best stock code for one memory x storage combo across a region's datacenters. */
function comboStock(rows: AvailRow[], dcs: string[], mem: DedicatedCatalogOption | null, disk: DedicatedCatalogOption | null): { code: string; dc: string | null } {
  const m = stockByDc(rows, { memory: mem?.productCode ?? null, storage: disk?.productCode ?? null });
  let best: { code: string; dc: string | null } = { code: "", dc: null };
  for (const dc of dcs) {
    const c = m.get(dc);
    if (c && (!best.code || stockRank(c) < stockRank(best.code))) best = { code: c, dc };
  }
  return best;
}

const bwText = (mbps: number | null) => (mbps == null ? "" : mbps >= 1000 ? `${+(mbps / 1000).toFixed(1)} Gbps` : `${mbps} Mbps`);

function optLabel(o: DedicatedCatalogOption): string {
  return brandSafe(o.label).replace(/\s*unmetered and guaranteed public bandwidth/i, " unmetered bandwidth");
}

function cpuText(it: ItemWithOptions): string {
  return brandSafe(`${it.cpuCount > 1 ? `${it.cpuCount}x ` : ""}${it.cpuBrand} ${it.cpuModel}`);
}

function totalStorageGb(label: string | null | undefined): number {
  let gb = 0;
  for (const m of (label ?? "").matchAll(/(\d+)\s*x\s*([\d.]+)\s*(TB|GB)/gi)) gb += Number(m[1]) * Number(m[2]) * (m[3].toUpperCase() === "TB" ? 1000 : 1);
  return Math.round(gb);
}

/* ---------------- customer projections ---------------- */

export type OrderRegion = { code: string; label: string; area: string; country: string; itemId: string; inStock: boolean; fromMonthlyCents: number; setupCents: number };

export type OrderCatalogCard = {
  id: string;
  name: string;
  tier: string;
  tierBlurb: string;
  tierOrder: number;
  cpu: string;
  cpuBrand: "AMD" | "Intel" | "Other";
  cores: number;
  threads: number;
  baseGhz: number | null;
  boostGhz: number | null;
  ramGb: number;
  maxRamGb: number;
  storage: string;
  storageGb: number;
  bandwidth: string;
  fromMonthlyCents: number;
  regions: OrderRegion[];
};

export type OrderOption = { id: string; label: string; isDefault: boolean; extraMonthlyCents: number; ramGb: number | null };

export type OrderVariant = {
  region: string;
  label: string;
  area: string;
  country: string;
  itemId: string;
  setupCents: number;
  memory: OrderOption[];
  storage: OrderOption[];
  bandwidth: OrderOption[];
  /** "memoryId|storageId" pairs in stock (<= 24h) in this region; "" stands for a family with no options. */
  inStock: string[];
  /** Exact Nxeon monthly price per "memoryId|storageId|bandwidthId" for every in-stock combo. */
  prices: Record<string, number>;
};

export type OrderBuild = Omit<OrderCatalogCard, "regions"> & { variants: OrderVariant[] };

function cardBase(it: ItemWithOptions): Omit<OrderCatalogCard, "regions" | "fromMonthlyCents"> {
  const t = tierFor(it.range);
  const cpu = cpuText(it);
  const mem = fam(it, "memory");
  const brand = /amd/i.test(it.cpuBrand) ? "AMD" : /intel/i.test(it.cpuBrand) ? "Intel" : "Other";
  return {
    id: it.id,
    name: brandSafe(it.displayName) || `${t.tier} ${cpu.replace(/^(AMD|Intel)\s+/i, "")}`.trim(),
    tier: t.tier,
    tierBlurb: t.blurb,
    tierOrder: t.order,
    cpu,
    cpuBrand: brand,
    cores: it.cpuCores * Math.max(1, it.cpuCount),
    threads: it.cpuThreads * Math.max(1, it.cpuCount),
    baseGhz: it.cpuFrequencyGhz,
    boostGhz: it.cpuBoostGhz,
    ramGb: it.defaultRamGb ?? 0,
    maxRamGb: Math.max(it.defaultRamGb ?? 0, ...mem.map((m) => m.ramGb ?? 0)),
    storage: brandSafe(it.defaultStorage),
    storageGb: totalStorageGb(it.defaultStorage),
    bandwidth: it.defaultBandwidthMbps ? bwText(it.defaultBandwidthMbps) : "",
  };
}

/** Regions (offered, not hidden) for one item with "any combo in stock" and the default price. */
function regionsFor(it: ItemWithOptions, rows: AvailRow[], rules: PricingRules, enabled: Set<string>): OrderRegion[] {
  const any = stockByDc(rows);
  const price = priceView(it, rules);
  return itemRegions(it.datacenters, any, enabled, it.hiddenRegions)
    .filter((r) => r.offered && !r.hidden && !r.code.startsWith("unmapped:"))
    .map((r) => ({
      code: r.code,
      label: r.customerLabel,
      area: r.area,
      country: r.country,
      itemId: it.id,
      inStock: r.dcs.some((dc) => orderableStock(any.get(dc))),
      fromMonthlyCents: price.sellMonthly,
      setupCents: price.sellSetup,
    }));
}

/** The catalogue: one card per hardware build, regional variants merged (cheapest per region wins). */
export async function loadOrderCatalog(previewAll: boolean): Promise<OrderCatalogCard[]> {
  const { rules, enabledRegions } = await loadRules();
  const items = await loadItems(previewAll);
  const avail = await loadAvailability(items.map((i) => i.planCode));
  const groups = new Map<string, OrderCatalogCard>();
  for (const it of items) {
    const regions = regionsFor(it, avail.get(it.planCode) ?? [], rules, enabledRegions);
    if (!regions.length) continue;
    const key = hardwareKey(it);
    const g = groups.get(key);
    if (!g) {
      groups.set(key, { ...cardBase(it), regions, fromMonthlyCents: Math.min(...regions.map((r) => r.fromMonthlyCents)) });
      continue;
    }
    for (const r of regions) {
      const have = g.regions.find((x) => x.code === r.code);
      if (!have) g.regions.push(r);
      else if ((r.inStock && !have.inStock) || (r.inStock === have.inStock && r.fromMonthlyCents < have.fromMonthlyCents)) Object.assign(have, r);
    }
  }
  const out = [...groups.values()];
  for (const c of out) {
    const inStock = c.regions.filter((r) => r.inStock);
    c.fromMonthlyCents = Math.min(...(inStock.length ? inStock : c.regions).map((r) => r.fromMonthlyCents));
    c.regions.sort((a, b) => Number(b.inStock) - Number(a.inStock) || a.label.localeCompare(b.label));
  }
  return out.sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents);
}

/** One build for the configurator (null when it is not orderable by this viewer). */
export async function loadOrderBuild(id: string, previewAll: boolean): Promise<OrderBuild | null> {
  const seed = await db.dedicatedCatalogItem.findFirst({ where: { id, removedAt: null, currency: "USD", ...(previewAll ? {} : { visible: true }) }, include: { options: true } });
  if (!seed) return null;
  const key = hardwareKey(seed);
  const { rules, enabledRegions } = await loadRules();
  const siblings = (await loadItems(previewAll, { cpuModel: seed.cpuModel, cpuBrand: seed.cpuBrand })).filter((it) => hardwareKey(it) === key);
  const avail = await loadAvailability(siblings.map((i) => i.planCode));
  const byRegion = new Map<string, OrderVariant & { _rank: number }>();
  for (const it of siblings) {
    const rows = avail.get(it.planCode) ?? [];
    const mems = fam(it, "memory");
    const disks = fam(it, "storage");
    const bws = fam(it, "bandwidth");
    const memList: (DedicatedCatalogOption | null)[] = mems.length ? mems : [null];
    const diskList: (DedicatedCatalogOption | null)[] = disks.length ? disks : [null];
    const bwList: (DedicatedCatalogOption | null)[] = bws.length ? bws : [null];
    const base = sellFor(it, rules, defaultOf(it, "memory"), defaultOf(it, "storage"), defaultOf(it, "bandwidth"));
    const extra = (f: "memory" | "storage" | "bandwidth", o: DedicatedCatalogOption) =>
      sellFor(it, rules, f === "memory" ? o : defaultOf(it, "memory"), f === "storage" ? o : defaultOf(it, "storage"), f === "bandwidth" ? o : defaultOf(it, "bandwidth")).sellMonthly - base.sellMonthly;
    const view = (f: "memory" | "storage" | "bandwidth", list: DedicatedCatalogOption[]): OrderOption[] =>
      list
        .map((o) => ({ id: o.id, label: optLabel(o), isDefault: o.id === defaultOf(it, f)?.id, extraMonthlyCents: Math.max(0, extra(f, o)), ramGb: o.ramGb }))
        .sort((a, b) => a.extraMonthlyCents - b.extraMonthlyCents);
    for (const r of itemRegions(it.datacenters, stockByDc(rows), enabledRegions, it.hiddenRegions)) {
      if (!r.offered || r.hidden || r.code.startsWith("unmapped:")) continue;
      const inStock: string[] = [];
      const prices: Record<string, number> = {};
      for (const m of memList) for (const d of diskList) {
        if (!orderableStock(comboStock(rows, r.dcs, m, d).code)) continue;
        inStock.push(`${m?.id ?? ""}|${d?.id ?? ""}`);
        for (const b of bwList) prices[`${m?.id ?? ""}|${d?.id ?? ""}|${b?.id ?? ""}`] = sellFor(it, rules, m, d, b).sellMonthly;
      }
      const v: OrderVariant & { _rank: number } = {
        region: r.code, label: r.customerLabel, area: r.area, country: r.country, itemId: it.id, setupCents: base.sellSetup,
        memory: view("memory", mems), storage: view("storage", disks), bandwidth: view("bandwidth", bws), inStock, prices,
        _rank: (inStock.length ? 0 : 1e9) + base.sellMonthly,
      };
      const prev = byRegion.get(r.code);
      if (!prev || v._rank < prev._rank) byRegion.set(r.code, v);
    }
  }
  if (byRegion.size === 0) return null;
  const variants = [...byRegion.values()].map(({ _rank, ...v }) => v);
  variants.sort((a, b) => Number(b.inStock.length > 0) - Number(a.inStock.length > 0) || a.label.localeCompare(b.label));
  const card = cardBase(seed);
  const cheapest = Math.min(...variants.flatMap((v) => Object.values(v.prices)).concat(variants.length && !variants.some((v) => v.inStock.length) ? [priceView(seed, rules).sellMonthly] : []));
  return { ...card, fromMonthlyCents: Number.isFinite(cheapest) ? cheapest : priceView(seed, rules).sellMonthly, variants };
}

/* ---------------- quote ---------------- */

export type DedicatedSpec = { cpu: string; cores: number; threads: number; ramGb: number; storage: string; bandwidth: string };

export type InternalQuote = {
  item: ItemWithOptions;
  memory: DedicatedCatalogOption | null;
  storage: DedicatedCatalogOption | null;
  bandwidth: DedicatedCatalogOption | null;
  /** ADMIN-ONLY */
  datacenter: string | null;
  /** ADMIN-ONLY */
  costMonthlyCents: number;
  stock: PublicStock;
  spec: DedicatedSpec;
  regionLabel: string;
  osLabel: string;
  money: DedicatedOrderMoney;
};

/** What a customer may see of a quote. */
export type CustomerQuote = {
  spec: DedicatedSpec;
  regionLabel: string;
  osLabel: string;
  termLabel: string;
  renewal: string;
  stock: PublicStock;
  money: DedicatedOrderMoney;
};

export function toCustomerQuote(q: InternalQuote): CustomerQuote {
  return {
    spec: q.spec,
    regionLabel: q.regionLabel,
    osLabel: q.osLabel,
    termLabel: termLabel(q.money.termMonths),
    renewal: renewalLabel(q.money.monthlyCents, q.money.termMonths),
    stock: q.stock,
    money: q.money,
  };
}

function pickOption(it: ItemWithOptions, f: string, id: string | null): DedicatedCatalogOption | null {
  const list = fam(it, f);
  if (!list.length) {
    if (id) throw new DedicatedOrderError("That option isn't available for this build.");
    return null;
  }
  if (!id) return defaultOf(it, f);
  const o = list.find((x) => x.id === id);
  if (!o) throw new DedicatedOrderError("That option isn't available for this build any more. Please pick again.");
  return o;
}

/**
 * Re-price an intent from the catalogue + pricing rules. Throws DedicatedOrderError
 * with a customer-safe message when the build, region, option or stock is not orderable.
 * `requireStock` is false only at card-leg fulfilment (the card already cleared; a
 * stock change in the meantime is handled by staff, never by eating the payment).
 */
export async function quoteDedicatedOrder(
  intent: DedicatedOrderIntent,
  user: Pick<User, "billingCountry" | "vatId">,
  opts: { previewAll: boolean; requireStock?: boolean },
): Promise<InternalQuote> {
  const item = await db.dedicatedCatalogItem.findFirst({
    where: { id: intent.itemId, currency: "USD", ...(opts.requireStock === false ? {} : { removedAt: null, ...(opts.previewAll ? {} : { visible: true }) }) },
    include: { options: true },
  });
  if (!item) throw new DedicatedOrderError("This build is no longer available.");
  const os = osById(intent.os);
  if (!os) throw new DedicatedOrderError("Pick an operating system.");
  const region = regionByCode(intent.region);
  if (!region) throw new DedicatedOrderError("Pick a location.");
  const { rules, enabledRegions } = await loadRules();
  const rows = (await loadAvailability([item.planCode])).get(item.planCode) ?? [];
  const regionRow = itemRegions(item.datacenters, stockByDc(rows), enabledRegions, item.hiddenRegions).find((r) => r.code === intent.region);
  if (!regionRow || (opts.requireStock !== false && (!regionRow.offered || regionRow.hidden))) throw new DedicatedOrderError("This build isn't offered in that location.");

  const memory = pickOption(item, "memory", intent.memoryId);
  const storage = pickOption(item, "storage", intent.storageId);
  const bandwidth = pickOption(item, "bandwidth", intent.bandwidthId);
  const st = comboStock(rows, regionRow.dcs, memory, storage);
  const stock = publicStock(st.code);
  if (opts.requireStock !== false && !orderableStock(st.code)) {
    throw new DedicatedOrderError(`That configuration isn't in stock in ${region.customerLabel} right now. Try another memory or storage choice, or another location.`);
  }
  const price = sellFor(item, rules, memory, storage, bandwidth);
  const tax = await taxContextForUser(user);
  const money = orderMoney({ monthlyCents: price.sellMonthly, termMonths: intent.termMonths, setupCents: price.sellSetup, taxRatePercent: tax.ratePercent, taxCountry: tax.country });
  const fallbackDc = regionRow.dcs[0] ?? null;
  return {
    item,
    memory,
    storage,
    bandwidth,
    datacenter: st.dc ?? fallbackDc,
    costMonthlyCents: price.costMonthly,
    stock,
    spec: {
      cpu: cpuText(item),
      cores: item.cpuCores * Math.max(1, item.cpuCount),
      threads: item.cpuThreads * Math.max(1, item.cpuCount),
      ramGb: memory?.ramGb ?? item.defaultRamGb ?? 0,
      storage: storage ? optLabel(storage) : brandSafe(item.defaultStorage),
      bandwidth: bandwidth ? optLabel(bandwidth) : item.defaultBandwidthMbps ? `${bwText(item.defaultBandwidthMbps)} public bandwidth` : "",
    },
    regionLabel: region.customerLabel,
    osLabel: os.label,
    money,
  };
}

/* ---------------- place ---------------- */

/** Parse a price stamped into Stripe metadata (null when malformed). */
export function parseStampedMoney(raw: unknown): DedicatedOrderMoney | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const int = (v: unknown) => (typeof v === "number" && Number.isInteger(v) && v >= 0 ? v : null);
  const monthly = int(r.monthlyCents), setup = int(r.setupCents), total = int(r.totalCents), tax = int(r.taxCents);
  const term = r.termMonths === 1 || r.termMonths === 12 ? r.termMonths : null;
  if (monthly == null || setup == null || total == null || tax == null || term == null) return null;
  const rate = typeof r.taxRatePercent === "number" && Number.isFinite(r.taxRatePercent) ? r.taxRatePercent : 0;
  const m = orderMoney({ monthlyCents: monthly, termMonths: term, setupCents: setup, taxRatePercent: 0 });
  // Re-derive the totals; refuse a stamp whose arithmetic doesn't add up.
  if (m.netCents + tax !== total) return null;
  return { ...m, taxCents: tax, taxRatePercent: rate, taxCountry: typeof r.taxCountry === "string" ? r.taxCountry.slice(0, 2) : "", totalCents: total };
}

/** Claim an order key exactly once (FulfilledSession's UNIQUE id is the lock). */
async function claimOrderKey(userId: string, orderKey: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: `dedorder:${userId}:${orderKey}`, kind: "dedicatedOrder" } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false;
    throw e;
  }
}

/**
 * Debit the wallet for the order total, write the PAID invoice and the PENDING
 * DedicatedServer row — one transaction. `sold` is the price stamped before a card
 * leg cleared (fulfilment path); omitted on the wallet-only path, where the price
 * is the fresh quote taken in the same request. Idempotent on intent.orderKey:
 * a repeat returns the server created the first time.
 */
export async function placeDedicatedOrder(
  user: User,
  intent: DedicatedOrderIntent,
  opts: { previewAll: boolean; sold?: DedicatedOrderMoney | null; via: "wallet" | "card" },
): Promise<{ serverId: string; created: boolean }> {
  const existing = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
  if (existing) return { serverId: existing.id, created: false };

  const q = await quoteDedicatedOrder(intent, user, { previewAll: opts.previewAll, requireStock: opts.via === "wallet" });
  const money = opts.sold ?? q.money;
  if (!(await claimOrderKey(user.id, intent.orderKey))) {
    const again = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
    if (again) return { serverId: again.id, created: false };
    throw new DedicatedOrderError("This order is already being placed. Refresh in a moment.");
  }

  const now = new Date();
  const renewalDate = addMonths(now, money.termMonths);
  const label = intent.label || `${q.spec.cpu.replace(/^(AMD|Intel)\s+/i, "")} · ${q.regionLabel}`;
  const desc = `Dedicated server — ${label}`;
  const lines = [
    {
      description:
        `${q.spec.cpu}, ${q.spec.ramGb} GB RAM, ${q.spec.storage}${q.spec.bandwidth ? `, ${q.spec.bandwidth}` : ""} · ${q.regionLabel} · ${q.osLabel}\n` +
        `${termLabel(money.termMonths)} term · renews ${renewalLabel(money.monthlyCents, money.termMonths)} on ${renewalDate.toISOString().slice(0, 10)}`,
      qty: 1,
      unitCents: money.termCents,
      amountCents: money.termCents,
    },
    ...(money.setupCents > 0 ? [{ description: "One-time setup", qty: 1, unitCents: money.setupCents, amountCents: money.setupCents }] : []),
  ];
  const orderConfig = {
    via: opts.via,
    catalogItemId: q.item.id,
    planCode: q.item.planCode, // ADMIN-ONLY (orderConfig never reaches a customer view)
    memory: q.memory ? { id: q.memory.id, label: q.memory.label, productCode: q.memory.productCode } : null,
    storage: q.storage ? { id: q.storage.id, label: q.storage.label, productCode: q.storage.productCode } : null,
    bandwidth: q.bandwidth ? { id: q.bandwidth.id, label: q.bandwidth.label, productCode: q.bandwidth.productCode } : null,
    os: intent.os,
    osLabel: q.osLabel,
    region: intent.region,
    datacenter: q.datacenter,
    stockAtOrder: q.stock,
    money,
  };

  try {
    const serverId = await db.$transaction(async (tx) => {
      await assertSpendCap(user, money.totalCents, tx);
      await debitWallet(tx, user.id, money.totalCents);
      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -money.totalCents, description: desc.slice(0, 190) } });
      const inv = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: desc.slice(0, 190),
          status: "PAID",
          lineItems: lines,
          taxCents: money.taxCents,
          taxRatePercent: money.taxRatePercent,
          taxCountry: money.taxCountry || null,
          period: { start: now, end: renewalDate },
        }),
        select: { id: true },
      });
      const s = await tx.dedicatedServer.create({
        data: {
          userId: user.id,
          label,
          catalogItemId: q.item.id,
          cpu: q.spec.cpu,
          cores: q.spec.cores,
          threads: q.spec.threads,
          ramGb: q.spec.ramGb,
          storage: q.spec.storage,
          bandwidth: q.spec.bandwidth,
          region: intent.region,
          datacenter: q.datacenter,
          costMonthlyCents: q.costMonthlyCents,
          os: q.osLabel,
          status: "PENDING",
          renewalDate,
          renewalMonthlyCents: money.monthlyCents,
          termMonths: money.termMonths,
          setupFeeCents: money.setupCents,
          invoiceIds: [inv.id],
          orderKey: intent.orderKey,
          orderConfig: orderConfig as object,
          notes: `Ordered online (${opts.via}). Build: ${q.item.planCode} in ${q.datacenter ?? "?"}; memory ${q.memory?.label ?? "default"}; storage ${q.storage?.label ?? "default"}; bandwidth ${q.bandwidth?.label ?? "default"}; OS ${q.osLabel}. Stock at order: ${q.stock}.`,
        },
        select: { id: true },
      });
      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: user.id, action: "ordered", detail: `paid ${money.totalCents}c via ${opts.via}; invoice ${inv.id}` } });
      await tx.auditLog.create({ data: { userId: user.id, action: "dedicated.order", detail: `${s.id} item=${q.item.id} region=${intent.region} total=${money.totalCents} via=${opts.via}` } });
      return s.id;
    });

    // Best-effort notices (never undo a placed, paid order).
    try {
      await db.notification.create({
        data: { userId: user.id, title: "Dedicated server ordered", body: `We're building ${label}. It will be online within 24 hours; we'll post its IP and login on the server page.`, href: `/dashboard/dedicated/${serverId}` },
      });
      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
      if (admins.length) {
        await db.notification.createMany({
          data: admins.map((a) => ({ userId: a.id, title: `New dedicated server order: ${label}`, body: `${user.email} paid ${renewalLabel(money.monthlyCents, money.termMonths)} (${q.regionLabel}). Build it by hand.`, href: `/admin/dedicated/servers/${serverId}` })),
        });
      }
    } catch {
      /* notices are best-effort */
    }
    return { serverId, created: true };
  } catch (e) {
    // Release the claim so a retry (after a top-up) can place the order.
    await db.fulfilledSession.delete({ where: { stripeSessionId: `dedorder:${user.id}:${intent.orderKey}` } }).catch(() => {});
    if (e instanceof InsufficientBalanceError) throw new DedicatedOrderError("Insufficient balance. Top up your wallet or pay the rest by card.");
    if (e instanceof SpendCapError) throw new DedicatedOrderError(e.message);
    throw e;
  }
}

export { regionForDc };

