"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): small shared pieces of the dedicated
 * order flow, built from the portal's own primitives (components/nx).
 */
import { Icon } from "@/components/nx/Icon";
import { Flag } from "@/components/nx/Bits";

/** Countries the portal's flag set draws; anything else gets a neutral globe. */
const FLAG_FOR: Record<string, string> = { us: "us", de: "de", sg: "sg", gb: "gb", jp: "jp", au: "au", ae: "ae", br: "br", ca: "ca", fr: "eu", pl: "eu" };

export function RegionFlag({ country, size = 18 }: { country: string; size?: number }) {
  const f = FLAG_FOR[country];
  if (f) return <Flag code={f} size={size} />;
  return (
    <span className="grid flex-none place-items-center rounded-full ring-1 ring-[rgba(160,200,255,0.28)]" style={{ width: Math.round(size * 1.5), height: Math.round(size * 1.5) }} aria-hidden>
      <Icon name="globe" size={Math.round(size * 0.7)} />
    </span>
  );
}

export const FIELD =
  "h-[40px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 text-[13px] " +
  "text-white outline-none transition placeholder:text-tx-faint focus:border-brand-400/70";

/** Native <select> with the portal's drawn chevron (same idiom as SettingsView). */
export function Select({ value, onChange, label, children, className = "" }: {
  value: string; onChange: (v: string) => void; label: string; children: React.ReactNode; className?: string;
}) {
  return (
    <label className={"flex min-w-0 flex-col gap-1 " + className}>
      <span className="nx-label">{label}</span>
      <span className="relative flex items-center">
        <select value={value} onChange={(e) => onChange(e.target.value)} className={FIELD + " cursor-pointer appearance-none pr-9"}>
          {children}
        </select>
        <svg aria-hidden width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="pointer-events-none absolute right-3 text-tx-faint">
          <path d="m6 9 6 6 6-6" />
        </svg>
      </span>
    </label>
  );
}

/** "Online within 24 hours" — the delivery promise for an in-stock build. */
export function EtaNote({ className = "" }: { className?: string }) {
  return (
    <span className={"inline-flex items-center gap-1.5 text-[11.5px] font-semibold text-[#8fe6ff] " + className}>
      <Icon name="clock" size={12} tone="inherit" />
      Online within 24 hours
    </span>
  );
}

export function StockDot({ on }: { on: boolean }) {
  return (
    <span aria-hidden className={"h-1.5 w-1.5 flex-none rounded-full " + (on ? "bg-[#22d3ee] shadow-[0_0_8px_rgba(34,211,238,0.85)]" : "bg-[rgba(140,160,200,0.45)]")} />
  );
}

export function SpecLine({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: React.ReactNode }) {
  return (
    <div className="flex min-w-0 items-start gap-2.5">
      <Icon name={icon} size={14} className="mt-[3px] flex-none opacity-90" />
      <div className="min-w-0">
        <div className="nx-label uppercase">{k}</div>
        <div className="text-[13px] font-bold leading-snug text-white">{v}</div>
        {sub && <div className="text-[11px] text-tx-faint">{sub}</div>}
      </div>
    </div>
  );
}

export const money = (c: number) => `$${(Math.round(c) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

