"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): step 1 of the dedicated order flow —
 * browse every in-stock build, filter by location, CPU, memory, storage and price.
 * Receives brand-safe OrderCatalogCard rows only (lib/dedicated/order.ts).
 */
import { useMemo, useState } from "react";
import Link from "next/link";
import type { OrderCatalogCard } from "@/lib/dedicated/order";
import { Icon } from "@/components/nx/Icon";
import { Stepper } from "@/components/nx/Stepper";
import { EtaNote, RegionFlag, Select, SpecLine, StockDot, money } from "./bits";

const RAM_STEPS = [0, 32, 64, 128, 256, 512];
const DISK_STEPS = [0, 1000, 2000, 4000, 8000, 16000];
const PRICE_STEPS = [0, 50, 100, 200, 400, 800];
const CORE_STEPS = [0, 6, 8, 12, 16, 24, 32];
type Sort = "price" | "cores" | "ram" | "disk";

const gb = (n: number) => (n >= 1000 ? `${+(n / 1000).toFixed(n % 1000 ? 2 : 0)} TB` : `${n} GB`);

export function DedicatedOrderCatalog({ cards, preview, previewAll }: { cards: OrderCatalogCard[]; preview: boolean; previewAll: boolean }) {
  const allRegions = useMemo(() => {
    const m = new Map<string, { code: string; label: string; area: string; country: string; inStock: number }>();
    for (const c of cards) for (const r of c.regions) {
      const p = m.get(r.code) ?? { code: r.code, label: r.label, area: r.area, country: r.country, inStock: 0 };
      if (r.inStock) p.inStock++;
      m.set(r.code, p);
    }
    return [...m.values()].sort((a, b) => a.area.localeCompare(b.area) || a.label.localeCompare(b.label));
  }, [cards]);

  const [region, setRegion] = useState("all");
  const [brand, setBrand] = useState<"all" | "AMD" | "Intel">("all");
  const [cores, setCores] = useState(0);
  const [ram, setRam] = useState(0);
  const [disk, setDisk] = useState(0);
  const [maxPrice, setMaxPrice] = useState(0);
  const [sort, setSort] = useState<Sort>("price");

  const shown = useMemo(() => {
    const rows = cards
      .map((c) => {
        const regions = c.regions.filter((r) => r.inStock && (region === "all" || r.code === region));
        const from = regions.length ? Math.min(...regions.map((r) => r.fromMonthlyCents)) : Infinity;
        return { c, regions, from };
      })
      .filter(({ c, regions, from }) =>
        regions.length > 0 &&
        (brand === "all" || c.cpuBrand === brand) &&
        c.cores >= cores &&
        c.maxRamGb >= ram &&
        c.storageGb >= disk &&
        (maxPrice === 0 || from <= maxPrice * 100));
    rows.sort((a, b) =>
      sort === "price" ? a.from - b.from
        : sort === "cores" ? b.c.cores - a.c.cores || a.from - b.from
        : sort === "ram" ? b.c.maxRamGb - a.c.maxRamGb || a.from - b.from
        : b.c.storageGb - a.c.storageGb || a.from - b.from);
    return rows;
  }, [cards, region, brand, cores, ram, disk, maxPrice, sort]);

  const filtered = region !== "all" || brand !== "all" || cores || ram || disk || maxPrice;
  const reset = () => { setRegion("all"); setBrand("all"); setCores(0); setRam(0); setDisk(0); setMaxPrice(0); };
  const totalInStock = cards.filter((c) => c.regions.some((r) => r.inStock)).length;

  return (
    <div className="flex flex-col gap-4">
      <Stepper steps={["Choose a build", "Configure", "Review", "Pay"]} at={0} onJump={() => {}} />

      {preview && (
        <p className="flex items-start gap-2 rounded-[12px] border border-[rgba(147,51,255,0.35)] bg-[rgba(60,20,110,0.28)] px-3.5 py-2.5 text-[12px] text-[#d9c8ff]">
          <Icon name="eye" size={14} tone="inherit" className="mt-[1px]" />
          <span>
            <b className="text-white">Private preview.</b> Only your account can see dedicated servers.
            {previewAll ? " No builds are published yet, so every live build is listed for you." : ""}
          </span>
        </p>
      )}

      {/* filters */}
      <section className="card flex flex-col gap-3 p-4" aria-label="Filters">
        <div className="flex flex-wrap items-center gap-2">
          <span className="nx-label mr-1 uppercase">Processor</span>
          {(["all", "AMD", "Intel"] as const).map((b) => (
            <button key={b} type="button" onClick={() => setBrand(b)} aria-pressed={brand === b} className={"chip " + (brand === b ? "chip-on" : "")}>
              {b === "all" ? "Any" : b}
            </button>
          ))}
          {filtered ? (
            <button type="button" onClick={reset} className="ml-auto text-[12px] font-semibold text-[#8dbde8] hover:text-white">Clear filters</button>
          ) : null}
        </div>
        <div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6">
          <Select label="Location" value={region} onChange={setRegion} className="col-span-2 md:col-span-1 xl:col-span-2">
            <option value="all">All locations</option>
            {allRegions.map((r) => (
              <option key={r.code} value={r.code}>{r.label}{r.inStock ? ` · ${r.inStock} in stock` : " · sold out"}</option>
            ))}
          </Select>
          <Select label="Cores" value={String(cores)} onChange={(v) => setCores(Number(v))}>
            {CORE_STEPS.map((n) => <option key={n} value={n}>{n ? `${n}+ cores` : "Any"}</option>)}
          </Select>
          <Select label="Memory" value={String(ram)} onChange={(v) => setRam(Number(v))}>
            {RAM_STEPS.map((n) => <option key={n} value={n}>{n ? `${n} GB+` : "Any"}</option>)}
          </Select>
          <Select label="Storage" value={String(disk)} onChange={(v) => setDisk(Number(v))}>
            {DISK_STEPS.map((n) => <option key={n} value={n}>{n ? `${gb(n)}+` : "Any"}</option>)}
          </Select>
          <Select label="Price" value={String(maxPrice)} onChange={(v) => setMaxPrice(Number(v))}>
            {PRICE_STEPS.map((n) => <option key={n} value={n}>{n ? `Up to $${n}/mo` : "Any"}</option>)}
          </Select>
        </div>
      </section>

      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-[12px] text-tx-mute">
          <span className="font-bold text-white">{shown.length}</span> of {totalInStock} in-stock builds · prices in USD, per month · every build ready within 24 hours
        </p>
        <Select label="" value={sort} onChange={(v) => setSort(v as Sort)} className="w-[170px] [&>span:first-child]:hidden">
          <option value="price">Lowest price</option>
          <option value="cores">Most cores</option>
          <option value="ram">Most memory</option>
          <option value="disk">Most storage</option>
        </Select>
      </div>

      {cards.length === 0 ? (
        <EmptyCatalog />
      ) : shown.length === 0 ? (
        <section className="card flex flex-col items-center gap-2 px-6 py-10 text-center">
          <Icon name="filter" size={22} />
          <span className="text-[15px] font-extrabold text-white">Nothing in stock matches those filters</span>
          <span className="max-w-[46ch] text-[12.5px] text-tx-mute">Loosen a filter or pick another location. Stock moves through the day, and our team can also source a specific machine for you.</span>
          <div className="mt-2 flex flex-wrap justify-center gap-2">
            <button type="button" onClick={reset} className="btn-primary btn-sm">Clear filters</button>
            <Link href="/dashboard/support" className="btn-ghost btn-sm">Ask for a custom build</Link>
          </div>
        </section>
      ) : (
        <ul className="grid gap-3.5 md:grid-cols-2 2xl:grid-cols-3">
          {shown.map(({ c, regions, from }) => (
            <li key={c.id} className="card card-i flex min-w-0 flex-col p-0">
              <div className="flex items-start justify-between gap-3 border-b border-rim-soft px-4 pb-3.5 pt-4">
                <div className="min-w-0">
                  <span className="text-[10.5px] font-extrabold uppercase tracking-[0.18em] text-[#b48cff]">{c.tier}</span>
                  <h3 className="trunc mt-0.5 text-[17px] font-extrabold tracking-[-0.02em] text-white" title={c.cpu}>{c.cpu}</h3>
                  <p className="text-[11.5px] text-tx-faint">{c.tierBlurb}</p>
                </div>
                <div className="flex-none text-right">
                  <div className="text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">from</div>
                  <div className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[23px] text-transparent">{money(from)}</div>
                  <div className="text-[11px] text-tx-dim">/mo</div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-x-3 gap-y-3 px-4 py-3.5">
                <SpecLine icon="cpu" k="CPU" v={`${c.cores} cores · ${c.threads} threads`} sub={c.baseGhz ? `${c.baseGhz} GHz${c.boostGhz ? `, boost ${c.boostGhz} GHz` : ""}` : undefined} />
                <SpecLine icon="ram" k="Memory" v={`${c.ramGb} GB`} sub={c.maxRamGb > c.ramGb ? `up to ${c.maxRamGb} GB` : "ECC where supported"} />
                <SpecLine icon="database" k="Storage" v={c.storage || "—"} />
                <SpecLine icon="nodes" k="Network" v={c.bandwidth || "—"} sub="DDoS protection included" />
              </div>
              <div className="mt-auto flex flex-col gap-3 px-4 pb-4">
                <ul className="flex flex-wrap gap-1.5" aria-label="In stock in">
                  {regions.slice(0, 6).map((r) => (
                    <li key={r.code} className="flex items-center gap-1.5 rounded-full border border-rim bg-surface px-2 py-[3px] text-[11px] text-tx-body">
                      <RegionFlag country={r.country} size={10} />
                      {r.label}
                      <StockDot on />
                    </li>
                  ))}
                  {regions.length > 6 && <li className="px-1 py-[3px] text-[11px] text-tx-faint">+{regions.length - 6} more</li>}
                </ul>
                <div className="flex items-center justify-between gap-3">
                  <EtaNote />
                  <Link href={`/dashboard/dedicated/order/${c.id}${region !== "all" ? `?region=${region}` : ""}`} className="btn-primary btn-sm">
                    Configure <span aria-hidden>→</span>
                  </Link>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function EmptyCatalog() {
  return (
    <section className="card flex flex-col items-center gap-2 px-6 py-12 text-center">
      <Icon name="server2" size={26} />
      <span className="text-[16px] font-extrabold text-white">No builds are available right now</span>
      <span className="max-w-[50ch] text-[12.5px] text-tx-mute">Our dedicated stock is fully reserved at the moment. Tell us what you need and our team will find you a machine.</span>
      <Link href="/dashboard/support" className="btn-primary btn-sm mt-2">Talk to our team</Link>
    </section>
  );
}

