"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): steps 2-4 of the dedicated order flow —
 * Configure (location, memory, storage, network, OS, term, name) -> Review (the
 * server's own quote, wallet toggle) -> Pay (wallet, or the portal's inline card
 * form for the remainder). Every price shown on Review/Pay is the SERVER quote
 * (lib/actions-dedicated-order.ts); the Configure step's figures come from the
 * same server-computed price table, so displayed === charged.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { OrderBuild, OrderOption, OrderVariant } from "@/lib/dedicated/order";
import type { DedicatedQuoteResult } from "@/lib/actions-dedicated-order";
import { payDedicatedOrder, quoteDedicatedOrderAction } from "@/lib/actions-dedicated-order";
import { DEDICATED_OS, renewalLabel, type DedicatedTerm } from "@/lib/dedicated/order-core";
import { Icon } from "@/components/nx/Icon";
import { Stepper } from "@/components/nx/Stepper";
import { Band, Pick } from "@/components/nx/OrderBits";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { EtaNote, FIELD, RegionFlag, StockDot, money } from "./bits";

const STEPS = ["Choose a build", "Configure", "Review", "Pay"];

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

const comboKey = (m: string | null, d: string | null) => `${m ?? ""}|${d ?? ""}`;
const priceKey = (m: string | null, d: string | null, b: string | null) => `${m ?? ""}|${d ?? ""}|${b ?? ""}`;
const defId = (list: OrderOption[]) => list.find((o) => o.isDefault)?.id ?? list[0]?.id ?? null;

/** Pick the cheapest in-stock storage for a memory choice (or vice versa). */
function bestPartner(v: OrderVariant, fixed: "memory" | "storage", id: string | null): string | null {
  const other = fixed === "memory" ? v.storage : v.memory;
  if (!other.length) return null;
  const ok = other.filter((o) => v.inStock.includes(fixed === "memory" ? comboKey(id, o.id) : comboKey(o.id, id)));
  return (ok[0] ?? other.find((o) => o.isDefault) ?? other[0]).id;
}

export function DedicatedConfigurator({ build, initialRegion, balanceCents, email }: {
  build: OrderBuild; initialRegion: string | null; balanceCents: number; email: string;
}) {
  const router = useRouter();
  const firstRegion = build.variants.find((v) => v.region === initialRegion && v.inStock.length) ?? build.variants.find((v) => v.inStock.length) ?? build.variants[0];
  const [step, setStep] = useState(1);
  const [region, setRegion] = useState(firstRegion.region);
  const variant = build.variants.find((v) => v.region === region) ?? firstRegion;
  const initialCombo = (v: OrderVariant) => {
    const m = defId(v.memory), d = defId(v.storage);
    if (v.inStock.includes(comboKey(m, d)) || !v.inStock.length) return { m, d };
    const [mm, dd] = v.inStock[0].split("|");
    return { m: mm || null, d: dd || null };
  };
  const [memoryId, setMemoryId] = useState<string | null>(initialCombo(firstRegion).m);
  const [storageId, setStorageId] = useState<string | null>(initialCombo(firstRegion).d);
  const [bandwidthId, setBandwidthId] = useState<string | null>(defId(firstRegion.bandwidth));
  const [os, setOs] = useState(DEDICATED_OS[0].id);
  const [term, setTerm] = useState<DedicatedTerm>(1);
  const [label, setLabel] = useState("");
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  const orderKey = useRef<string>("");
  if (!orderKey.current) orderKey.current = newKey();

  /* Switching location: carry the choices over by label (option ids are per-location). */
  const chooseRegion = (code: string) => {
    const next = build.variants.find((v) => v.region === code);
    if (!next) return;
    const byLabel = (from: OrderOption[], to: OrderOption[], id: string | null) => to.find((o) => o.label === from.find((x) => x.id === id)?.label)?.id ?? defId(to);
    let m = byLabel(variant.memory, next.memory, memoryId);
    let d = byLabel(variant.storage, next.storage, storageId);
    if (next.inStock.length && !next.inStock.includes(comboKey(m, d))) {
      const alt = bestPartner(next, "memory", m);
      if (next.inStock.includes(comboKey(m, alt))) d = alt;
      else ({ m, d } = initialCombo(next));
    }
    setRegion(code);
    setMemoryId(m);
    setStorageId(d);
    setBandwidthId(byLabel(variant.bandwidth, next.bandwidth, bandwidthId));
  };
  const chooseMemory = (id: string) => {
    setMemoryId(id);
    if (!variant.inStock.includes(comboKey(id, storageId))) setStorageId(bestPartner(variant, "memory", id));
  };
  const chooseStorage = (id: string) => {
    setStorageId(id);
    if (!variant.inStock.includes(comboKey(memoryId, id))) setMemoryId(bestPartner(variant, "storage", id));
  };

  const inStock = variant.inStock.includes(comboKey(memoryId, storageId));
  const monthly = variant.prices[priceKey(memoryId, storageId, bandwidthId)] ?? null;
  const memOk = (id: string) => variant.inStock.some((k) => k.startsWith(`${id}|`));
  const diskOk = (id: string) => variant.inStock.some((k) => k.endsWith(`|${id}`));

  const intent = useMemo(() => ({
    itemId: variant.itemId, region, os, termMonths: term, memoryId, storageId, bandwidthId, label: label.trim(), orderKey: orderKey.current,
  }), [variant.itemId, region, os, term, memoryId, storageId, bandwidthId, label]);

  /* ---------- review: the server's quote ---------- */
  const [quote, setQuote] = useState<DedicatedQuoteResult | null>(null);
  const [quoting, startQuote] = useTransition();
  const runQuote = useCallback(() => startQuote(async () => setQuote(await quoteDedicatedOrderAction(intent, useWallet))), [intent, useWallet]);
  useEffect(() => { if (step === 2) runQuote(); }, [step, runQuote]);

  /* ---------- pay ---------- */
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number; walletApplied: number } | null>(null);
  const [payError, setPayError] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [preparing, startPrep] = useTransition();
  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const onConfirmReady = useCallback((fn: (() => Promise<void>) | null) => { cardConfirm.current = fn; setCanConfirm(!!fn); }, []);
  const onBusy = useCallback((b: boolean, err: string | null) => { setPaying(b); setPayError(err); }, []);
  const q = quote && quote.ok ? quote : null;
  const walletOnly = !!q && q.cardCents === 0;

  const goPay = () => {
    setPayError(null);
    setCheckout(null);
    setStep(3);
    if (q && q.cardCents > 0) {
      startPrep(async () => {
        const r = await payDedicatedOrder(intent, useWallet);
        if (!r.ok) setPayError(r.error);
        else if ("checkout" in r) setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied });
        else router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
      });
    }
  };
  const payNow = () => {
    setPayError(null);
    if (walletOnly) {
      setPaying(true);
      startPrep(async () => {
        const r = await payDedicatedOrder(intent, useWallet);
        if (!r.ok) { setPayError(r.error); setPaying(false); return; }
        if ("serverId" in r) router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
        else { setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied }); setPaying(false); }
      });
      return;
    }
    void cardConfirm.current?.();
  };

  const mem = variant.memory.find((o) => o.id === memoryId);
  const disk = variant.storage.find((o) => o.id === storageId);
  const bw = variant.bandwidth.find((o) => o.id === bandwidthId);
  const osObj = DEDICATED_OS.find((o) => o.id === os)!;
  const canContinue = inStock && monthly != null;

  return (
    <div className="flex flex-col gap-5">
      <Stepper steps={STEPS} at={step} onJump={(i) => (i === 0 ? router.push("/dashboard/dedicated/order") : setStep(i))} />

      {step === 1 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]">
          <div className="flex min-w-0 flex-col gap-7">
            <BuildHeader build={build} />

            <Band n={1} id="ded-region" title="Location" help="Where the machine lives. Only locations with this build in stock can be ordered." live done>
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {build.variants.map((v) => {
                  const ok = v.inStock.length > 0;
                  const from = ok ? Math.min(...Object.values(v.prices)) : null;
                  return (
                    <Pick key={v.region} on={v.region === region} onClick={() => ok && chooseRegion(v.region)} disabled={!ok}
                          className={"flex items-center gap-3 p-3 " + (ok ? "" : "cursor-not-allowed opacity-50")}>
                      <RegionFlag country={v.country} size={17} />
                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                        <span className="trunc text-[13.5px] font-bold text-white">{v.label}</span>
                        <span className="flex items-center gap-1.5 text-[11.5px] text-tx-faint">
                          <StockDot on={ok} />{ok ? `In stock · from ${money(from!)}/mo` : "Sold out here"}
                        </span>
                      </span>
                    </Pick>
                  );
                })}
              </div>
            </Band>

            {variant.memory.length > 0 && (
              <Band n={2} id="ded-memory" title="Memory" help="Dedicated RAM. Upgrades are installed before handover." live done>
                <OptionGrid list={variant.memory} on={memoryId} ok={memOk} pick={chooseMemory} />
              </Band>
            )}
            {variant.storage.length > 0 && (
              <Band n={3} id="ded-storage" title="Storage" help="Disks in software RAID unless you ask us otherwise." live done>
                <OptionGrid list={variant.storage} on={storageId} ok={diskOk} pick={chooseStorage} />
              </Band>
            )}
            {variant.bandwidth.length > 1 && (
              <Band n={4} id="ded-network" title="Network" help="Unmetered public bandwidth. DDoS protection is always included." live done>
                <OptionGrid list={variant.bandwidth} on={bandwidthId} ok={() => true} pick={setBandwidthId} />
              </Band>
            )}

            <Band n={5} id="ded-os" title="Operating system" help="Installed and hardened by our team. You get full root." live done>
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {DEDICATED_OS.map((o) => (
                  <Pick key={o.id} on={o.id === os} onClick={() => setOs(o.id)} className="flex items-center gap-3 p-3">
                    <Icon name="terminal" size={15} />
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="trunc text-[13.5px] font-bold text-white">{o.label}</span>
                      <span className="trunc text-[11.3px] text-tx-faint">{o.note}</span>
                    </span>
                  </Pick>
                ))}
              </div>
            </Band>

            <Band n={6} id="ded-term" title="Billing" help="Pay monthly, or a year up front. Renews at the same price." live done>
              <div className="grid gap-2.5 sm:grid-cols-2">
                {([1, 12] as const).map((t) => (
                  <Pick key={t} on={term === t} onClick={() => setTerm(t)} className="flex flex-col gap-1 p-3.5">
                    <span className="text-[14px] font-extrabold text-white">{t === 1 ? "Monthly" : "Annual"}</span>
                    <span className="text-[12.5px] font-semibold text-tx-body">{monthly != null ? renewalLabel(monthly, t) : "—"}</span>
                    <span className="text-[11px] text-tx-faint">{t === 1 ? "Billed every month. Cancel any time." : "Billed once a year, up front."}</span>
                  </Pick>
                ))}
              </div>
            </Band>

            <Band n={7} id="ded-name" title="Name it" help="Optional. Shown on your dashboard and invoices." live done>
              <input value={label} onChange={(e) => setLabel(e.target.value.slice(0, 40))} placeholder="e.g. Production database" className={FIELD + " max-w-[420px]"} aria-label="Server name" />
            </Band>
          </div>

          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="card card-glass flex flex-col gap-3.5 p-4" style={{ "--tone": "#3fd0ff" } as React.CSSProperties}>
              <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">Your server</span>
              <ul className="flex flex-col gap-2 text-[12.5px] text-tx-body">
                <li className="flex items-center gap-2"><Icon name="cpu" size={13} />{build.cpu} · {build.cores}c/{build.threads}t</li>
                <li className="flex items-center gap-2"><Icon name="ram" size={13} />{mem ? mem.label : `${build.ramGb} GB`}</li>
                <li className="flex items-center gap-2"><Icon name="database" size={13} />{disk ? disk.label : build.storage}</li>
                {(bw || build.bandwidth) && <li className="flex items-center gap-2"><Icon name="nodes" size={13} />{bw ? bw.label : build.bandwidth}</li>}
                <li className="flex items-center gap-2"><RegionFlag country={variant.country} size={9} />{variant.label}</li>
                <li className="flex items-center gap-2"><Icon name="terminal" size={13} />{osObj.label}</li>
              </ul>
              <div className="h-px bg-rim-soft" />
              {canContinue ? (
                <>
                  <div className="flex items-baseline justify-between">
                    <span className="text-[12px] text-tx-mute">{term === 12 ? "Annual" : "Monthly"}</span>
                    <span className="num text-[24px]">{renewalLabel(monthly!, term)}</span>
                  </div>
                  <div className="flex items-baseline justify-between text-[12px] text-tx-mute">
                    <span>One-time setup</span>
                    <span className="font-semibold text-tx-body">{variant.setupCents > 0 ? money(variant.setupCents) : "Free"}</span>
                  </div>
                  <EtaNote />
                </>
              ) : (
                <p className="rounded-[10px] border border-[rgba(255,196,70,0.35)] bg-[rgba(60,40,0,0.45)] px-3 py-2 text-[12px] text-[#f1d28a]">
                  This combination isn&apos;t in stock in {variant.label}. Pick another memory or storage option, or another location.
                </p>
              )}
              <button type="button" disabled={!canContinue} onClick={() => setStep(2)} className="btn-primary w-full">
                Review order <span aria-hidden>→</span>
              </button>
              <span className="text-center text-[11px] text-tx-faint">Tax, if any, is shown on the next step.</span>
            </section>
          </aside>
        </div>
      )}

      {step === 2 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="card flex min-w-0 flex-col gap-4 p-4 sm:p-5">
            <div className="flex items-start justify-between gap-3">
              <div>
                <span className="text-[17px] font-extrabold tracking-[-0.02em] text-white">Review your order</span>
                <p className="text-[12px] text-tx-mute">Priced just now from live stock.</p>
              </div>
              <button type="button" onClick={() => setStep(1)} className="btn-ghost btn-xs">Change</button>
            </div>
            {!quote || quoting ? (
              <ReviewSkeleton />
            ) : !quote.ok ? (
              <ErrorBox msg={quote.error} onBack={() => setStep(1)} onRetry={runQuote} />
            ) : (
              <>
                <dl className="grid gap-3 sm:grid-cols-2">
                  {[
                    ["Processor", `${quote.quote.spec.cpu}`, `${quote.quote.spec.cores} cores · ${quote.quote.spec.threads} threads`],
                    ["Memory", `${quote.quote.spec.ramGb} GB`, "Dedicated to you"],
                    ["Storage", quote.quote.spec.storage, "Software RAID"],
                    ["Network", quote.quote.spec.bandwidth || "—", "DDoS protection included"],
                    ["Location", quote.quote.regionLabel, ""],
                    ["Operating system", quote.quote.osLabel, "Full root access"],
                  ].map(([k, v, sub]) => (
                    <div key={k} className="rounded-[11px] border border-rim bg-surface px-3 py-2.5">
                      <dt className="nx-label uppercase">{k}</dt>
                      <dd className="text-[13px] font-bold text-white">{v}</dd>
                      {sub && <dd className="text-[11px] text-tx-faint">{sub}</dd>}
                    </div>
                  ))}
                </dl>
                <WhatNext />
              </>
            )}
          </section>
          <aside className="xl:self-start">
            <section className="card flex flex-col gap-3 p-4 sm:p-5">
              <span className="text-[15px] font-extrabold text-white">Order summary</span>
              {q ? (
                <>
                  <Money rows={[
                    [`${q.quote.termLabel} term`, money(q.quote.money.termCents)],
                    ["One-time setup", q.quote.money.setupCents ? money(q.quote.money.setupCents) : "Free"],
                    ...(q.quote.money.taxCents ? [[`Tax (${q.quote.money.taxRatePercent}%${q.quote.money.taxCountry ? ` ${q.quote.money.taxCountry}` : ""})`, money(q.quote.money.taxCents)] as [string, string]] : []),
                  ]} total={["Total today", money(q.quote.money.totalCents)]} />
                  <p className="text-[11.5px] text-tx-mute">Renews at <b className="text-tx-body">{q.quote.renewal}</b>{q.quote.money.taxCents ? " plus tax" : ""}. Cancel any time before renewal.</p>
                  {balanceCents > 0 && (
                    <label className="flex cursor-pointer items-center gap-2.5 rounded-[10px] border border-rim bg-surface px-3 py-2.5 text-[12.5px] text-tx-body">
                      <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} className="accent-[#4c8dff]" />
                      <span className="flex-1">Use my wallet balance ({money(balanceCents)})</span>
                      {useWallet && <span className="font-bold text-mint">−{money(q.walletApplied)}</span>}
                    </label>
                  )}
                  <div className="flex items-baseline justify-between rounded-[10px] bg-[rgba(26,85,207,0.14)] px-3 py-2.5">
                    <span className="text-[12.5px] text-tx-body">{q.cardCents > 0 ? "Charged to your card" : "Paid from your wallet"}</span>
                    <span className="num text-[19px]">{money(q.cardCents > 0 ? q.cardCents : q.walletApplied)}</span>
                  </div>
                  <button type="button" onClick={goPay} className="btn-primary w-full">Continue to payment <span aria-hidden>→</span></button>
                </>
              ) : (
                <div className="flex flex-col gap-2" aria-hidden><div className="h-4 animate-pulse rounded bg-rim-soft" /><div className="h-4 w-2/3 animate-pulse rounded bg-rim-soft" /><div className="h-10 animate-pulse rounded-full bg-rim-soft" /></div>
              )}
            </section>
          </aside>
        </div>
      )}

      {step === 3 && q && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="card flex min-w-0 flex-col gap-4 p-4 sm:p-5">
            <div className="flex items-center gap-2.5">
              <Icon name="lock" size={16} />
              <div>
                <span className="text-[17px] font-extrabold text-white">Payment</span>
                <p className="text-[12px] text-tx-mute">Secure and encrypted. {walletOnly ? "Your wallet covers this order." : "Card details are handled by our payment processor and never touch our servers."}</p>
              </div>
            </div>
            {walletOnly ? (
              <div className="flex items-center gap-3 rounded-[12px] border border-[rgba(17,200,142,0.35)] bg-[rgba(4,40,30,0.45)] p-4">
                <Icon name="card" size={18} />
                <div className="min-w-0 flex-1">
                  <div className="text-[13.5px] font-bold text-white">Wallet balance</div>
                  <div className="text-[12px] text-tx-mute">{money(q.walletApplied)} will be taken from your {money(balanceCents)} balance.</div>
                </div>
              </div>
            ) : checkout ? (
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={onConfirmReady} onBusy={onBusy} />
            ) : preparing ? (
              <div className="flex flex-col items-center gap-2 py-10 text-center"><Icon name="lock" size={22} className="opacity-70" /><span className="text-[13.5px] font-bold text-white">Preparing your secure card form…</span></div>
            ) : null}
            {payError && <ErrorBox msg={payError} onBack={() => setStep(2)} />}
          </section>
          <aside className="xl:self-start">
            <section className="card flex flex-col gap-3 p-4 sm:p-5">
              <span className="text-[15px] font-extrabold text-white">Order summary</span>
              <p className="text-[12.5px] text-tx-body">{q.quote.spec.cpu} · {q.quote.spec.ramGb} GB · {q.quote.regionLabel}</p>
              <Money rows={[
                ["Total today", money(q.quote.money.totalCents)],
                ...(q.walletApplied > 0 ? [["From wallet", `−${money(checkout?.walletApplied ?? q.walletApplied)}`] as [string, string]] : []),
              ]} total={[walletOnly ? "From wallet" : "To pay by card", money(walletOnly ? q.walletApplied : checkout?.cardCents ?? q.cardCents)]} />
              <p className="text-[11.5px] text-tx-mute">Renews at <b className="text-tx-body">{q.quote.renewal}</b>. <EtaNote className="ml-0.5" /></p>
              <button type="button" onClick={payNow} disabled={paying || preparing || (!walletOnly && !canConfirm)} className="btn-primary w-full">
                {paying ? "Processing…" : `Pay ${money(walletOnly ? q.walletApplied : checkout?.cardCents ?? q.cardCents)}`}
              </button>
              <button type="button" onClick={() => setStep(2)} className="text-[12px] font-semibold text-[#8dbde8] hover:text-white">Back to review</button>
              <span className="text-center text-[10.5px] text-tx-faint">Signed in as {email}</span>
            </section>
          </aside>
        </div>
      )}
    </div>
  );
}

function BuildHeader({ build }: { build: OrderBuild }) {
  return (
    <section className="card relative overflow-hidden p-4 sm:p-5">
      <span aria-hidden className="pointer-events-none absolute -right-10 -top-16 h-[220px] w-[360px] opacity-70"
            style={{ background: "radial-gradient(60% 60% at 50% 50%, rgba(64,150,255,0.22), transparent 70%), radial-gradient(40% 50% at 70% 40%, rgba(168,60,255,0.18), transparent 72%)", filter: "blur(10px)" }} />
      <div className="relative flex flex-wrap items-end justify-between gap-4">
        <div className="min-w-0">
          <span className="text-[10.5px] font-extrabold uppercase tracking-[0.18em] text-[#b48cff]">{build.tier}</span>
          <h2 className="text-[22px] font-extrabold tracking-[-0.03em] text-white sm:text-[26px]">{build.cpu}</h2>
          <p className="text-[12.5px] text-tx-mute">{build.cores} cores · {build.threads} threads{build.baseGhz ? ` · ${build.baseGhz} GHz` : ""}{build.boostGhz ? ` (boost ${build.boostGhz} GHz)` : ""} · single-tenant, full root</p>
        </div>
        <div className="text-right">
          <div className="text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">from</div>
          <div className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[26px] text-transparent">{money(build.fromMonthlyCents)}<span className="text-[12px] text-tx-dim">/mo</span></div>
        </div>
      </div>
    </section>
  );
}

function OptionGrid({ list, on, ok, pick }: { list: OrderOption[]; on: string | null; ok: (id: string) => boolean; pick: (id: string) => void }) {
  return (
    <div className="grid gap-2.5 sm:grid-cols-2">
      {list.map((o) => {
        const avail = ok(o.id);
        return (
          <Pick key={o.id} on={o.id === on} onClick={() => avail && pick(o.id)} disabled={!avail}
                className={"flex items-center gap-3 p-3 " + (avail ? "" : "cursor-not-allowed opacity-45")}>
            <span className={"grid h-[17px] w-[17px] flex-none place-items-center rounded-full border " + (o.id === on ? "border-[#4c8dff]" : "border-rim-hi")} aria-hidden>
              {o.id === on && <span className="h-[8px] w-[8px] rounded-full bg-[#4c8dff]" />}
            </span>
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="text-[13px] font-bold leading-snug text-white">{o.label}</span>
              {!avail && <span className="text-[11px] text-tx-faint">Not in stock here</span>}
            </span>
            <span className="flex-none text-[12.5px] font-bold text-tx-body">{o.isDefault || o.extraMonthlyCents === 0 ? "Included" : `+${money(o.extraMonthlyCents)}/mo`}</span>
          </Pick>
        );
      })}
    </div>
  );
}

function Money({ rows, total }: { rows: [string, string][]; total: [string, string] }) {
  return (
    <dl className="flex flex-col gap-1.5 text-[12.5px]">
      {rows.map(([k, v]) => (
        <div key={k} className="flex items-baseline justify-between gap-3"><dt className="text-tx-mute">{k}</dt><dd className="font-semibold text-tx-body">{v}</dd></div>
      ))}
      <div className="mt-1 flex items-baseline justify-between gap-3 border-t border-rim-soft pt-2"><dt className="font-bold text-white">{total[0]}</dt><dd className="num text-[20px]">{total[1]}</dd></div>
    </dl>
  );
}

function WhatNext() {
  const steps = [
    { icon: "card", t: "You pay", d: "Your machine is reserved the moment payment clears." },
    { icon: "gear", t: "We build it", d: "Our engineers install your OS, harden it and run burn-in checks." },
    { icon: "checkcircle", t: "Online within 24 hours", d: "Its IP addresses and your login appear on its dashboard." },
  ];
  return (
    <div className="rounded-[12px] border border-rim bg-surface p-3.5">
      <span className="nx-label uppercase">What happens next</span>
      <ol className="mt-2.5 grid gap-3 sm:grid-cols-3">
        {steps.map((s, i) => (
          <li key={s.t} className="flex items-start gap-2.5">
            <span className="grid h-6 w-6 flex-none place-items-center rounded-full bg-[linear-gradient(135deg,#2f7eef,#6f2ee0)] text-[11px] font-extrabold text-white">{i + 1}</span>
            <span className="min-w-0"><span className="block text-[12.5px] font-bold text-white">{s.t}</span><span className="block text-[11.3px] text-tx-faint">{s.d}</span></span>
          </li>
        ))}
      </ol>
    </div>
  );
}

function ReviewSkeleton() {
  return (
    <div className="grid gap-3 sm:grid-cols-2" aria-busy="true" aria-label="Pricing your order">
      {Array.from({ length: 6 }, (_, i) => <div key={i} className="h-[62px] animate-pulse rounded-[11px] bg-rim-soft" />)}
    </div>
  );
}

function ErrorBox({ msg, onBack, onRetry }: { msg: string; onBack: () => void; onRetry?: () => void }) {
  return (
    <div className="flex flex-col items-start gap-2 rounded-[12px] border border-[rgba(239,66,108,0.35)] bg-[rgba(60,10,26,0.45)] p-3.5">
      <span className="flex items-center gap-2 text-[13px] font-bold text-white"><Icon name="warntriangle" size={14} />We couldn&apos;t continue</span>
      <span className="text-[12px] text-tx-body">{msg}</span>
      <div className="flex gap-2">
        <button type="button" onClick={onBack} className="btn-ghost btn-xs">Change the order</button>
        {onRetry && <button type="button" onClick={onRetry} className="btn-ghost btn-xs">Try again</button>}
        <Link href="/dashboard/support" className="btn-ghost btn-xs">Contact support</Link>
      </div>
    </div>
  );
}

