"use client";

import { Icon, Plate } from "./Icon";
import { Flag } from "./Bits";

/* Kept structural rather than importing a model type: these are presentation
   components and the shapes they render are assembled by the page. */
export type ServerStatus = "Online" | "Maintenance" | "Offline";
const money = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/* ── a metered bar ────────────────────────────────────────────────────────
   Three of these per card, so they have to read at a glance: the track is the
   capacity, the fill turns amber then rose as it runs out. */
export function Meter({ label, pct, sub }: { label: string; pct: number; sub?: string }) {
  const tone = pct >= 85 ? "#ef426c" : pct >= 70 ? "#efa828" : "#3fbcd8";
  return (
    <div className="flex min-w-0 flex-col gap-1">
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-[10.5px] font-bold uppercase tracking-[0.1em] text-tx-faint">{label}</span>
        <span className="text-[11px] font-bold text-white">{pct}%</span>
      </div>
      <span className="block h-[4px] overflow-hidden rounded-full bg-well">
        <span className="block h-full rounded-full transition-[width] duration-700"
              style={{ width: `${pct}%`, background: tone, boxShadow: `0 0 8px -1px ${tone}` }} />
      </span>
      {sub && <span className="trunc text-[10px] text-tx-faint">{sub}</span>}
    </div>
  );
}
