input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): one dedicated server's dashboard, in the
 * portal's own language (components/nx Panel / StatCard / chips). Takes only the
 * brand-safe CustomerServerView (lib/dedicated/customer-view.ts).
 *
 * Status timeline, specs, IPs (once assigned), login delivery, billing (renewal
 * stated as charged: "$X/yr" for an annual term), invoices and support.
 * Power/OS controls are REQUESTS: each opens a support ticket our team carries
 * out. In `preview` (admin preview) nothing is sent anywhere.
 */
import { useState, useTransition } from "react";
import Link from "next/link";
import type { CustomerInvoiceRow, CustomerServerView, RequestKind } from "@/lib/dedicated/customer-view";
import { REQUEST_LABEL } from "@/lib/dedicated/customer-view";
import { serverTimeline, SETUP_ETA } from "@/lib/dedicated/order-core";
import { requestDedicatedAction, revealDedicatedCredentials } from "@/lib/actions-dedicated-customer";
import { Icon } from "@/components/nx/Icon";
import { Panel, StatCard } from "@/components/nx/PageShell";

const usd = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

export const STATUS_CHIP: Record<string, string> = {
  ACTIVE: "chip-mint",
  PENDING: "chip-violet",
  PROVISIONING: "chip-blue",
  SUSPENDED: "chip-amber",
  CANCELLED: "chip-slate",
};

const REQUEST_BUTTON: Record<RequestKind, string> = { REBOOT: "Request a reboot", REINSTALL: "Request an OS reinstall", RESCUE: "Request rescue mode" };
const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
};
const REQUEST_ICON: Record<RequestKind, string> = { REBOOT: "refresh", REINSTALL: "terminal", RESCUE: "lifebuoy" };

function CopyIp({ ip }: { ip: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" className="group flex min-w-0 items-center gap-2 font-mono text-[13px] text-white" title="Copy"
      onClick={() => { void navigator.clipboard?.writeText(ip); setDone(true); setTimeout(() => setDone(false), 1200); }}>
      <span className="trunc">{ip}</span>
      <span className="flex-none text-[10.5px] font-sans font-semibold text-tx-faint group-hover:text-tx-body">{done ? "Copied" : <Icon name="copy" size={11} />}</span>
    </button>
  );
}

export function DedicatedServerDashboard({ view, invoices, preview = false, justOrdered = false }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview?: boolean; justOrdered?: boolean;
}) {
  const [open, setOpen] = useState<RequestKind | null>(null);
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [cred, setCred] = useState<{ username: string; secret: string } | null>(null);
  const [pending, start] = useTransition();
  const live = view.statusKey === "ACTIVE";
  const building = view.statusKey === "PENDING" || view.statusKey === "PROVISIONING";
  const requested = new Set(view.openRequests.map((r) => r.kind));
  const timeline = serverTimeline({ statusKey: view.statusKey, orderedAt: view.orderedAt, provisionedAt: view.provisionedAt });

  const send = (kind: RequestKind) =>
    start(async () => {
      if (preview) { setMsg(`Preview: a "${REQUEST_LABEL[kind]}" request would open a support ticket for our team. Nothing was sent.`); setOpen(null); return; }
      const r = await requestDedicatedAction(view.id, kind, note);
      setMsg(r.ok ? "Request sent. Our team has it as a support ticket and will update you there." : r.error);
      if (r.ok) { setOpen(null); setNote(""); }
    });

  const reveal = () =>
    start(async () => {
      if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
      const r = await revealDedicatedCredentials(view.id);
      if (r.ok) setCred({ username: r.username, secret: r.secret });
      else setMsg(r.error);
    });

  const [storageMain, storageSub] = [view.storage.split("(")[0].trim() || "—", view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Dedicated disks"];

  return (
    <div className="mx-auto flex w-full max-w-[1180px] flex-col gap-4">
      {/* HERO */}
      <header className="relative overflow-hidden">
        <span aria-hidden className="pointer-events-none absolute -top-10 right-[16%] hidden h-[210px] w-[52%] opacity-70 md:block"
              style={{ background: "radial-gradient(60% 120% at 50% 50%, rgba(64,150,255,0.20), transparent 70%), radial-gradient(38% 90% at 66% 42%, rgba(168,60,255,0.16), transparent 72%)", filter: "blur(14px)" }} />
        <div className="relative flex flex-wrap items-start justify-between gap-x-6 gap-y-3 pb-1">
          <div className="flex min-w-0 flex-col gap-1">
            <Link href={preview ? "#" : "/dashboard/dedicated"} className="flex items-center gap-1 text-[11.5px] font-semibold text-tx-faint hover:text-tx-body">
              <span aria-hidden>←</span> Dedicated servers
            </Link>
            <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#f21cff]">Dedicated server</span>
            <h1 className="trunc text-[27px] font-extrabold leading-[1.08] tracking-[-0.032em] text-white sm:text-[31px]">{view.label}</h1>
            <p className="trunc text-[13px] text-tx-mute">{view.hostname ?? "Hostname set at handover"} · {view.region}</p>
          </div>
          <span className={"chip-tone mt-1 flex-none " + (STATUS_CHIP[view.statusKey] ?? "chip-violet")}>
            <span aria-hidden className={"h-1.5 w-1.5 rounded-full " + (live ? "bg-[#11c88e] shadow-[0_0_8px_rgba(17,200,142,0.9)]" : "bg-current")} />
            {view.status}
          </span>
        </div>
      </header>

      {justOrdered && (
        <section className="flex items-start gap-3 rounded-[14px] border border-[rgba(17,200,142,0.38)] bg-[rgba(4,40,30,0.5)] p-4" role="status">
          <Icon name="checkcircle" size={18} />
          <div>
            <div className="text-[14px] font-extrabold text-white">Order confirmed. Thank you.</div>
            <div className="text-[12.5px] text-tx-body">Our team is building your server now. It will be {SETUP_ETA.toLowerCase()}; we&apos;ll notify you and post its IP addresses and login right here.</div>
          </div>
        </section>
      )}

      {view.statusKey === "SUSPENDED" && (
        <p className="rounded-[12px] border border-[rgba(255,196,70,0.38)] bg-[rgba(60,40,0,0.45)] px-3.5 py-2.5 text-[12.5px] text-[#f1d28a]">
          This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} <Link href={preview ? "#" : "/dashboard/support"} className="font-bold underline">Contact support</Link> to restore it.
        </p>
      )}

      {/* TIMELINE */}
      {view.statusKey !== "CANCELLED" && (
        <Panel title="Status" sub={building ? `${SETUP_ETA} from your order` : live && view.provisionedAt ? `Online since ${day(view.provisionedAt)}` : undefined}>
          <ol className="grid gap-3 sm:grid-cols-3">
            {timeline.map((t, i) => (
              <li key={t.key} className="relative flex items-start gap-3">
                <span className={"grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold " +
                  (t.state === "done" ? "bg-[linear-gradient(135deg,#14c5e4,#11c88e)] text-[#012019]"
                    : t.state === "current" ? "bg-[linear-gradient(135deg,#2f7eef,#6f2ee0)] text-white ring-[3px] ring-[rgba(111,46,224,0.28)]"
                    : "border border-rim-hi text-tx-faint")}>
                  {t.state === "done" ? <Icon name="check" size={12} tone="inherit" /> : i + 1}
                </span>
                <span className="min-w-0">
                  <span className={"block text-[13px] font-bold " + (t.state === "todo" ? "text-tx-faint" : "text-white")}>
                    {t.label}{t.state === "current" && <span className="ml-1.5 text-[11px] font-semibold text-[#b48cff] motion-safe:animate-pulse">in progress</span>}
                  </span>
                  <span className="block text-[11.5px] text-tx-faint">{t.at ? `${day(t.at)} · ` : ""}{t.note}</span>
                </span>
              </li>
            ))}
          </ol>
        </Panel>
      )}

      {/* SPECS */}
      <section aria-label="Hardware" className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard icon="cpu" value={`${view.cores} cores`} label={view.cpu} foot={<span className="text-[10.5px] text-tx-faint">{view.threads} threads</span>} />
        <StatCard icon="ram" value={`${view.ramGb} GB`} label="Memory" tone="violet" foot={<span className="text-[10.5px] text-tx-faint">Dedicated to you</span>} />
        <StatCard icon="database" value={storageMain} label="Storage" tone="mint" foot={<span className="text-[10.5px] text-tx-faint">{storageSub}</span>} />
        <StatCard icon="nodes" value={view.bandwidth.split(" ").slice(0, 2).join(" ") || "—"} label="Network" tone="amber" foot={<span className="text-[10.5px] text-tx-faint">DDoS protection included</span>} />
      </section>

      <div className="grid gap-4 lg:grid-cols-[1.35fr_1fr]">
        <div className="flex min-w-0 flex-col gap-4">
          <Panel title="IP addresses" sub={view.os ? `Operating system: ${view.os}` : undefined}>
            {view.ipv4.length + view.ipv6.length === 0 ? (
              <div className="flex items-center gap-3 rounded-[11px] border border-dashed border-rim-hi px-3.5 py-4">
                <Icon name="globe" size={16} />
                <span className="text-[12.5px] text-tx-mute">{building ? "Your addresses are assigned while the machine is built. They appear here at handover." : "No addresses assigned."}</span>
              </div>
            ) : (
              <ul className="flex flex-col divide-y divide-[var(--color-rim-soft)]">
                {view.ipv4.map((ip, i) => (
                  <li key={ip} className="flex items-center justify-between gap-3 py-2.5"><CopyIp ip={ip} /><span className="chip-tone chip-blue flex-none">IPv4{i === 0 ? " · primary" : ""}</span></li>
                ))}
                {view.ipv6.map((ip) => (
                  <li key={ip} className="flex items-center justify-between gap-3 py-2.5"><CopyIp ip={ip} /><span className="chip-tone chip-violet flex-none">IPv6</span></li>
                ))}
              </ul>
            )}
          </Panel>

          <Panel title="Server actions" sub="Our engineers carry these out. Each one opens a support ticket you can follow.">
            <div className="grid gap-2.5 sm:grid-cols-3">
              {(Object.keys(REQUEST_LABEL) as RequestKind[]).map((k) => (
                <button key={k} type="button" disabled={pending || !live || requested.has(k)} onClick={() => { setOpen(k); setMsg(null); }}
                  className="card card-i flex flex-col items-start gap-1.5 p-3 text-left disabled:pointer-events-none disabled:opacity-45">
                  <Icon name={REQUEST_ICON[k]} size={15} />
                  <span className="text-[12.5px] font-bold text-white">{requested.has(k) ? `${REQUEST_LABEL[k]} · requested` : REQUEST_BUTTON[k]}</span>
                  <span className="text-[11px] text-tx-faint">{REQUEST_HINT[k]}</span>
                </button>
              ))}
            </div>
            {!live && <p className="mt-2.5 text-[11.5px] text-tx-faint">Available once the server is online.</p>}
            {open && (
              <div className="mt-3 rounded-[12px] border border-[rgba(72,148,255,0.35)] bg-[rgba(26,85,207,0.1)] p-3.5">
                <label className="text-[12.5px] font-bold text-white" htmlFor="ded-note">{REQUEST_LABEL[open]}: anything we should know?</label>
                <textarea id="ded-note" value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000}
                  placeholder={open === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"}
                  className="mt-2 w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 py-2 text-[13px] text-white outline-none placeholder:text-tx-faint focus:border-brand-400/70" />
                {open === "REINSTALL" && <p className="mt-1.5 text-[11.5px] text-[#f1d28a]">A reinstall erases everything on the disks.</p>}
                <div className="mt-2.5 flex gap-2">
                  <button type="button" className="btn-primary btn-xs" disabled={pending} onClick={() => send(open)}>Send request</button>
                  <button type="button" className="btn-ghost btn-xs" onClick={() => setOpen(null)}>Cancel</button>
                </div>
              </div>
            )}
            {msg && <p className="mt-2.5 text-[12px] text-tx-body" role="status">{msg}</p>}
            {view.openRequests.length > 0 && (
              <ul className="mt-2.5 flex flex-col gap-1 text-[11.5px] text-tx-faint">
                {view.openRequests.map((r) => <li key={r.id}>{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind} requested {day(r.createdAt)} · with our team</li>)}
              </ul>
            )}
          </Panel>
        </div>

        <div className="flex min-w-0 flex-col gap-4">
          <Panel title="Login details">
            {view.credentialsReady ? (
              cred ? (
                <dl className="flex flex-col gap-2 text-[13px]">
                  <div className="flex justify-between gap-3"><dt className="text-tx-mute">Username</dt><dd className="font-mono text-white">{cred.username}</dd></div>
                  <div className="flex justify-between gap-3"><dt className="text-tx-mute">Password</dt><dd className="break-all font-mono text-white">{cred.secret}</dd></div>
                  <p className="pt-1 text-[11px] text-tx-faint">Change this password after your first login.</p>
                </dl>
              ) : (
                <div className="flex flex-col items-start gap-2.5">
                  <p className="text-[12.5px] text-tx-mute">Your login is ready. It is stored encrypted and shown only to you.</p>
                  <button type="button" className="btn-primary btn-sm" disabled={pending} onClick={reveal}><Icon name="key" size={12} tone="inherit" /> Show login details</button>
                </div>
              )
            ) : (
              <p className="flex items-center gap-2 text-[12.5px] text-tx-mute"><Icon name="lock" size={13} />Delivered here, encrypted, as soon as your server is handed over.</p>
            )}
          </Panel>

          <Panel title="Billing">
            <dl className="flex flex-col gap-2 text-[13px]">
              <div className="flex justify-between gap-3"><dt className="text-tx-mute">Renews at</dt><dd className="font-bold text-white">{view.renewal ?? "—"}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-tx-mute">Billing term</dt><dd className="text-white">{view.termLabel}</dd></div>
