                {invoices.map((inv) => (
                  <li key={inv.id} className="flex items-center justify-between gap-3 py-2 text-[12.5px]">
                    {preview ? <span className="text-tx-body">#{inv.number} · {day(inv.createdAt)}</span>
                      : <Link href={`/dashboard/invoices/${inv.id}`} className="text-tx-body hover:text-white">#{inv.number} · {day(inv.createdAt)}</Link>}
                    <span className="flex items-center gap-2"><span className="font-semibold text-white">{usd(inv.amountCents)}</span><span className={"chip-tone " + (inv.status === "PAID" ? "chip-mint" : "chip-slate")}>{inv.status.toLowerCase()}</span></span>
