      if (r.ok) setCred({ username: r.username, secret: r.secret });
      else setMsg(r.error);
    });

  const storageMain = view.storage.split("(")[0].trim() || "—";
  const storageSub = view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Dedicated disks";

  return (
    <div className="mx-auto flex w-full max-w-[1180px] flex-col gap-4">
