                  <li key={ip} className="flex items-center justify-between gap-3 py-2.5"><CopyIp ip={ip} /><span className="chip-tone chip-blue flex-none">IPv4{i === 0 ? " · primary" : ""}</span></li>
                ))}
                {view.ipv6.map((ip) => (
                  <li key={ip} className="flex items-center justify-between gap-3 py-2.5"><CopyIp ip={ip} /><span className="chip-tone chip-violet flex-none">IPv6</span></li>
                ))}
              </ul>
            )}
          </Panel>

