              <div className="flex justify-between gap-3"><dt className="text-tx-mute">Billing term</dt><dd className="text-white">{view.termLabel}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-tx-mute">Next renewal</dt><dd className="text-white" suppressHydrationWarning>{view.renewalDate ? day(view.renewalDate) : "—"}</dd></div>
            </dl>
            <p className="mt-2 text-[11px] text-tx-faint">We send a renewal invoice before this date.</p>
            <span className="nx-label mt-3 uppercase">Invoices</span>
            {invoices.length === 0 ? (
              <p className="mt-1.5 text-[12px] text-tx-mute">No invoices yet.</p>
            ) : (
              <ul className="mt-1 flex flex-col divide-y divide-[var(--color-rim-soft)]">
                {invoices.map((inv) => (
                  <li key={inv.id} className="flex items-center justify-between gap-3 py-2 text-[12.5px]">
                    {preview ? <span className="text-tx-body" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</span>
                      : <Link href={`/dashboard/invoices/${inv.id}`} className="text-tx-body hover:text-white" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</Link>}
                    <span className="flex items-center gap-2"><span className="font-semibold text-white">{usd(inv.amountCents)}</span><span className={"chip-tone " + (inv.status === "PAID" ? "chip-mint" : "chip-slate")}>{inv.status.toLowerCase()}</span></span>
                  </li>
                ))}
              </ul>
            )}
          </Panel>

          <section className="card flex items-center gap-3 p-4">
            <Icon name="lifebuoy" size={18} />
            <div className="min-w-0 flex-1">
              <div className="text-[13px] font-bold text-white">Need a hand with this server?</div>
              <div className="text-[11.5px] text-tx-faint">The same support team that runs the rest of your Nxeon stack.</div>
            </div>
            <Link href={preview ? "#" : "/dashboard/support"} className="btn-ghost btn-xs flex-none">Open a ticket</Link>
          </section>
        </div>
      </div>
    </div>
  );
}

