import { Panel, StatCard } from "@/components/nx/PageShell";

const usd = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

export const STATUS_CHIP: Record<string, string> = {
  ACTIVE: "chip-mint",
  PENDING: "chip-violet",
  PROVISIONING: "chip-blue",
  SUSPENDED: "chip-amber",
  CANCELLED: "chip-slate",
};

const REQUEST_BUTTON: Record<RequestKind, string> = { REBOOT: "Request a reboot", REINSTALL: "Request an OS reinstall", RESCUE: "Request rescue mode" };
const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
};
const REQUEST_ICON: Record<RequestKind, string> = { REBOOT: "refresh", REINSTALL: "terminal", RESCUE: "lifebuoy" };

function CopyIp({ ip }: { ip: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" className="group flex min-w-0 items-center gap-2 font-mono text-[13px] text-white" title="Copy"
      onClick={() => { void navigator.clipboard?.writeText(ip); setDone(true); setTimeout(() => setDone(false), 1200); }}>
      <span className="trunc">{ip}</span>
      <span className="flex-none font-sans text-[10.5px] font-semibold text-tx-faint group-hover:text-tx-body">{done ? "Copied" : <Icon name="copy" size={11} />}</span>
    </button>
  );
