/**
 * CUSTOMER-FACING (brand-voice checked): the customer's dedicated servers, in the
 * portal's card language. Empty state leads into the order flow.
 */
import Link from "next/link";
import type { CustomerServerView } from "@/lib/dedicated/customer-view";
import { Icon } from "@/components/nx/Icon";

const CHIP: Record<string, string> = { ACTIVE: "chip-mint", PENDING: "chip-violet", PROVISIONING: "chip-blue", SUSPENDED: "chip-amber", CANCELLED: "chip-slate" };

export function DedicatedServerList({ servers, hrefBase = "/dashboard/dedicated", orderHref = "/dashboard/dedicated/order" }: { servers: CustomerServerView[]; hrefBase?: string; orderHref?: string }) {
  if (servers.length === 0) {
    return (
      <section className="card relative flex flex-col items-center gap-2.5 overflow-hidden px-6 py-12 text-center">
        <span aria-hidden className="pointer-events-none absolute -top-20 left-1/2 h-[240px] w-[520px] -translate-x-1/2 opacity-70"
              style={{ background: "radial-gradient(50% 50% at 50% 50%, rgba(64,150,255,0.22), transparent 70%), radial-gradient(35% 45% at 62% 50%, rgba(168,60,255,0.18), transparent 72%)", filter: "blur(10px)" }} />
        <Icon name="server2" size={28} />
        <span className="relative text-[17px] font-extrabold tracking-[-0.02em] text-white">No dedicated servers yet</span>
        <span className="relative max-w-[52ch] text-[12.5px] text-tx-mute">A whole machine that is yours alone: every core, every gigabyte, full root. Pick an in-stock build and it&apos;s online within 24 hours.</span>
        <div className="relative mt-2 flex flex-wrap justify-center gap-2">
          <Link href={orderHref} className="btn-primary btn-sm">Browse builds <span aria-hidden>→</span></Link>
          <Link href="/dashboard/support" className="btn-ghost btn-sm">Ask for a custom build</Link>
        </div>
      </section>
    );
  }
  return (
    <ul className="grid gap-3 md:grid-cols-2">
      {servers.map((s) => (
        <li key={s.id}>
          <Link href={`${hrefBase}/${s.id}`} className="card card-i flex flex-col gap-3 p-4">
            <div className="flex items-start justify-between gap-3">
              <div className="flex min-w-0 items-center gap-3">
                <span className="grid h-[38px] w-[38px] flex-none place-items-center rounded-[10px] border border-rim-hi" style={{ background: "linear-gradient(180deg, rgba(24,74,180,0.55), rgba(4,20,60,0.9))" }}>
                  <Icon name="server2" size={15} />
                </span>
                <div className="min-w-0">
                  <h3 className="trunc text-[15px] font-extrabold tracking-[-0.02em] text-white">{s.label}</h3>
                  <p className="trunc text-[11.5px] text-tx-faint">{s.cpu} · {s.ramGb} GB · {s.region}</p>
                </div>
              </div>
              <span className={"chip-tone flex-none " + (CHIP[s.statusKey] ?? "chip-violet")}>{s.status}</span>
            </div>
            <div className="flex items-center justify-between gap-3 border-t border-rim-soft pt-2.5 text-[12px]">
              <span className="trunc font-mono text-tx-body">{s.ipv4[0] ?? "IP assigned at handover"}</span>
              <span className="flex-none text-tx-mute">{s.renewal ?? ""}</span>
            </div>
          </Link>
        </li>
      ))}
    </ul>
  );
}

