import { test } from "node:test";
import assert from "node:assert/strict";

/**
 * lib/preview-access.ts — the private-preview gate shared by "dedicated" and
 * "modbuilder". DB pointed at a closed port first: any read failure must fail CLOSED.
 */
process.env.DATABASE_URL = "postgresql://nobody:nothing@127.0.0.1:1/none?connect_timeout=2";

test("allowlist parsing: comma/space/semicolon separated, case-insensitive, junk dropped", async () => {
  const { parsePreviewEmails, emailInPreviewList } = await import("../lib/preview-access.ts");
  assert.deepEqual(parsePreviewEmails(" A@x.com, b@Y.com;c@z.io  notanemail ,"), ["a@x.com", "b@y.com", "c@z.io"]);
  assert.deepEqual(parsePreviewEmails(""), []);
  assert.deepEqual(parsePreviewEmails(null), []);
  const list = parsePreviewEmails("Nicholas.SJ.Albanese@gmail.com");
  assert.equal(emailInPreviewList("nicholas.sj.albanese@gmail.com", list), true);
  assert.equal(emailInPreviewList(" NICHOLAS.sj.albanese@GMAIL.com ", list), true);
  assert.equal(emailInPreviewList("someone@gmail.com", list), false);
  assert.equal(emailInPreviewList("", list), false);
  assert.equal(emailInPreviewList(null, list), false);
  // no substring tricks
  assert.equal(emailInPreviewList("xnicholas.sj.albanese@gmail.com", list), false);
});

test("default allowlist is exactly the owner's customer account", async () => {
  const { DEFAULT_PREVIEW_EMAILS, PREVIEW_FEATURES, PREVIEW_ACCESS_SETTING } = await import("../lib/preview-access.ts");
