  assert.equal(await isPreviewUser({ email: "nicholas.sj.albanese@gmail.com" }, "dedicated"), false);
  assert.equal(await isPreviewUser(null, "dedicated"), false);
  assert.equal(await isPreviewUser({ email: null }, "modbuilder"), false);
  assert.deepEqual(await previewAllowlist("nope" as never), []);
});
