import { test } from "node:test";
import assert from "node:assert/strict";
import { addMonths, orderMoney, parseDedicatedIntent, parseStampedMoney, renewalLabel, serverTimeline, termLabel, DEDICATED_OS } from "../lib/dedicated/order-core.ts";
import { walletSplit } from "../lib/wallet-split.ts";

/** Pure pieces of the dedicated checkout (lib/dedicated/order-core.ts). */

const good = { itemId: "cmux4lzvy0000hld5g3psc93q", region: "sgp1", os: "ubuntu-2404", termMonths: 12, memoryId: null, storageId: "cmux4lzvy0001hld5g3psc93q", bandwidthId: "", label: " My <b>box</b> ", orderKey: "a1b2c3d4e5f6a7b8c9d0" };

test("intent parser accepts a clean intent and normalises it", () => {
  const i = parseDedicatedIntent(good)!;
  assert.ok(i);
  assert.equal(i.termMonths, 12);
  assert.equal(i.memoryId, null);
  assert.equal(i.bandwidthId, null);
  assert.equal(i.label, "My bbox/b");
});

test("intent parser refuses anything malformed (ids, region, os, term, key)", () => {
  for (const bad of [
    { ...good, itemId: "../../etc" },
    { ...good, region: "sgp" },
    { ...good, region: "SGP1" },
    { ...good, os: "windows-2022" },
    { ...good, termMonths: 3 },
    { ...good, termMonths: "12" },
    { ...good, memoryId: "x" },
    { ...good, orderKey: "short" },
    null,
    "string",
  ]) assert.equal(parseDedicatedIntent(bad), null, JSON.stringify(bad));
});

test("money: annual = 12 x monthly, setup once, tax on the net, integer cents", () => {
  const m = orderMoney({ monthlyCents: 18999, termMonths: 12, setupCents: 5000, taxRatePercent: 9, taxCountry: "SG" });
  assert.equal(m.termCents, 227988);
  assert.equal(m.netCents, 232988);
  assert.equal(m.taxCents, Math.round(232988 * 0.09));
  assert.equal(m.totalCents, m.netCents + m.taxCents);
  const z = orderMoney({ monthlyCents: 2699, termMonths: 1, setupCents: 0, taxRatePercent: 0, taxCountry: "US" });
  assert.deepEqual([z.totalCents, z.taxCents, z.taxCountry], [2699, 0, ""]);
});

test("renewal is stated as charged: /yr for annual, never a monthly split", () => {
  assert.equal(renewalLabel(18999, 1), "$189.99/mo");
  assert.equal(renewalLabel(18999, 12), "$2,279.88/yr");
  assert.equal(renewalLabel(10000, 3), "$300.00 every 3 months");
  assert.equal(termLabel(12), "Annual");
  assert.equal(termLabel(1), "Monthly");
});

test("stamped price round-trips and a tampered stamp is refused", () => {
  const m = orderMoney({ monthlyCents: 13399, termMonths: 1, setupCents: 10700, taxRatePercent: 20, taxCountry: "GB" });
  assert.deepEqual(parseStampedMoney(JSON.parse(JSON.stringify(m))), m);
  assert.equal(parseStampedMoney({ ...m, totalCents: m.totalCents - 1 }), null);
  assert.equal(parseStampedMoney({ ...m, termMonths: 6 }), null);
  assert.equal(parseStampedMoney({ ...m, monthlyCents: -5 }), null);
  assert.equal(parseStampedMoney(null), null);
});

test("wallet-then-card split of an order total (same helper the charge path uses)", () => {
  const total = orderMoney({ monthlyCents: 13399, termMonths: 1, setupCents: 0, taxRatePercent: 0 }).totalCents;
  assert.deepEqual(walletSplit({ dueCents: total, balanceCents: 20000, useWallet: true }).cardCents, 0);
  const s = walletSplit({ dueCents: total, balanceCents: 5000, useWallet: true });
  assert.deepEqual([s.walletApplied, s.cardCents], [5000, total - 5000]);
  assert.equal(walletSplit({ dueCents: total, balanceCents: 5000, useWallet: false }).cardCents, total);
});

test("renewal dates clamp to month end", () => {
  assert.equal(addMonths(new Date("2026-01-31T10:00:00Z"), 1).toISOString().slice(0, 10), "2026-02-28");
  assert.equal(addMonths(new Date("2026-10-06T10:00:00Z"), 12).toISOString().slice(0, 10), "2027-10-06");
});

test("status timeline follows the manual lifecycle", () => {
  const at = "2026-10-06T00:00:00Z";
  const st = (k: string, p: string | null = null) => serverTimeline({ statusKey: k, orderedAt: at, provisionedAt: p }).map((t) => t.state).join(",");
  assert.equal(st("PENDING"), "done,current,todo");
  assert.equal(st("PROVISIONING"), "done,current,todo");
  assert.equal(st("ACTIVE", at), "done,done,done");
  assert.equal(st("SUSPENDED", at), "done,done,done");
});

test("OS list is Linux only (no licence resale) with unique ids", () => {
  assert.equal(new Set(DEDICATED_OS.map((o) => o.id)).size, DEDICATED_OS.length);
  assert.ok(!DEDICATED_OS.some((o) => /windows/i.test(o.label)));
});
EOF
