import { test, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * DB-backed checks of the dedicated-server checkout against a THROWAWAY Postgres
 * holding a real catalogue sync (scripts/dedicated-catalog-sync.ts is read-only
 * public GETs). Drives the REAL code: catalogue/configurator loaders, the quote,
 * wallet placement, and the card leg through lib/fulfil-checkout.ts with a FAKE
 * Stripe session object (no Stripe call, no network).
 *
 * Opt-in and fail-closed: runs only when DEDICATED_TEST_DATABASE_URL is set AND
 * equals DATABASE_URL AND is 127.0.0.1 on a non-5432 port with database `dedprev`.
 *
 *   initdb a scratch cluster on e.g. :55447, createdb dedprev,
 *   DATABASE_URL=postgresql://postgres@127.0.0.1:55447/dedprev npx prisma db push
 *   DATABASE_URL=... npx tsx scripts/dedicated-catalog-sync.ts
 *   DATABASE_URL=... DEDICATED_TEST_DATABASE_URL=$DATABASE_URL npx tsx --test test/dedicated-order-db.test.ts
 */
const url = process.env.DEDICATED_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/dedprev$/.test(url);
const skip = safe ? false : "set DEDICATED_TEST_DATABASE_URL (throwaway 127.0.0.1 /dedprev db with a synced catalogue) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let order: typeof import("../lib/dedicated/order.ts");
let gate: typeof import("../lib/dedicated/gate.ts");
let fulfil: typeof import("../lib/fulfil-checkout.ts")["fulfilRetrievedCheckoutSession"];
let userId = "";

const key = () => `t${Date.now()}${Math.random().toString(36).slice(2, 10)}`;

before(async () => {
  if (!safe) return;
  process.env.STRIPE_SECRET_KEY = "sk_test_fake_never_called";
  db = (await import("../lib/db.ts")).db;
  order = await import("../lib/dedicated/order.ts");
  gate = await import("../lib/dedicated/gate.ts");
  fulfil = (await import("../lib/fulfil-checkout.ts")).fulfilRetrievedCheckoutSession;
  const u = await db.user.create({ data: { email: `ded-${Date.now()}@example.test`, passwordHash: "x", name: "Ded Test", balanceCents: 0 } });
  userId = u.id;
});
after(async () => { if (safe) await db.$disconnect(); });

async function anInStockIntent() {
  const cards = await order.loadOrderCatalog(true);
  assert.ok(cards.length > 0, "the synced catalogue yields orderable cards");
  for (const c of cards) {
    if (!c.regions.some((r) => r.inStock)) continue;
    const b = await order.loadOrderBuild(c.id, true);
    const v = b?.variants.find((x) => x.inStock.length);
    if (!b || !v) continue;
    const [m, d] = v.inStock[0].split("|");
    const bw = v.bandwidth.find((o) => o.isDefault)?.id ?? null;
    return { build: b, variant: v, intent: { itemId: v.itemId, region: v.region, os: "ubuntu-2404", termMonths: 1 as const, memoryId: m || null, storageId: d || null, bandwidthId: bw, label: "DB test box", orderKey: key() } };
  }
  throw new Error("no in-stock build in the synced catalogue");
}

test("gate: owner email by default, Setting overrides, everyone else refused", { skip }, async () => {
  await db.setting.deleteMany({ where: { key: { startsWith: "preview_access_emails" } } });
  await db.setting.deleteMany({ where: { key: "dedicated_public_enabled" } });
  assert.equal((await gate.dedicatedAccessFor({ email: "nicholas.sj.albanese@gmail.com" })).allowed, true);
  assert.equal((await gate.dedicatedAccessFor({ email: "Nicholas.SJ.Albanese@gmail.com" })).preview, true);
  assert.equal((await gate.dedicatedAccessFor({ email: "someone@else.com" })).allowed, false);
  assert.equal((await gate.dedicatedAccessFor(null)).allowed, false);
  await db.setting.create({ data: { key: "preview_access_emails", value: "" } });
  assert.equal((await gate.dedicatedAccessFor({ email: "nicholas.sj.albanese@gmail.com" })).allowed, false, "empty list = nobody");
  await db.setting.create({ data: { key: "preview_access_emails_dedicated", value: "qa@example.test" } });
  assert.equal((await gate.dedicatedAccessFor({ email: "qa@example.test" })).allowed, true, "per-feature list wins");
  const { isPreviewUser } = await import("../lib/preview-access.ts");
  assert.equal(await isPreviewUser({ email: "qa@example.test" }, "modbuilder"), false, "per-feature list does not leak to another feature");
  await db.setting.deleteMany({ where: { key: { startsWith: "preview_access_emails" } } });
  await db.setting.create({ data: { key: "dedicated_public_enabled", value: "true" } });
  assert.deepEqual(await gate.dedicatedAccessFor({ email: "anyone@x.com" }), { allowed: true, isPublic: true, preview: false });
  await db.setting.deleteMany({ where: { key: "dedicated_public_enabled" } });
});

test("displayed === charged: the configurator's price table equals the server quote", { skip }, async () => {
  const { variant, intent } = await anInStockIntent();
  const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  const q = await order.quoteDedicatedOrder(intent, user, { previewAll: true });
  assert.equal(q.money.monthlyCents, variant.prices[`${intent.memoryId ?? ""}|${intent.storageId ?? ""}|${intent.bandwidthId ?? ""}`]);
  assert.equal(q.money.setupCents, variant.setupCents);
  assert.ok(q.money.monthlyCents >= q.costMonthlyCents, "never below cost");
  const annual = await order.quoteDedicatedOrder({ ...intent, termMonths: 12 }, user, { previewAll: true });
  assert.equal(annual.money.termCents, q.money.monthlyCents * 12);
  const cq = order.toCustomerQuote(annual);
  assert.match(cq.renewal, /\/yr$/);
  const json = JSON.stringify(cq);
  assert.ok(!json.includes(q.item.planCode) && !/ovh|kimsufi|vrack/i.test(json), "customer quote is brand-safe");
});

test("out-of-stock or foreign options are refused", { skip }, async () => {
  const { intent } = await anInStockIntent();
  const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  await assert.rejects(order.quoteDedicatedOrder({ ...intent, memoryId: "cmzzzzzzzzzzzzzzzzzzzzzzz" }, user, { previewAll: true }), order.DedicatedOrderError);
  await assert.rejects(order.quoteDedicatedOrder({ ...intent, region: "zzz9" }, user, { previewAll: true }), order.DedicatedOrderError);
  await assert.rejects(order.quoteDedicatedOrder(intent, user, { previewAll: false }), order.DedicatedOrderError, "not visible = not orderable outside the preview");
});

test("wallet path: refused without funds (nothing written), then placed exactly once", { skip }, async () => {
  const { intent } = await anInStockIntent();
  let user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  await db.user.update({ where: { id: userId }, data: { balanceCents: 0 } });
  user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  await assert.rejects(order.placeDedicatedOrder(user, intent, { previewAll: true, via: "wallet" }), /Insufficient balance/);
  assert.equal(await db.dedicatedServer.count({ where: { orderKey: intent.orderKey } }), 0);

  const q = await order.quoteDedicatedOrder(intent, user, { previewAll: true });
  await db.user.update({ where: { id: userId }, data: { balanceCents: q.money.totalCents + 1234 } });
  user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  const first = await order.placeDedicatedOrder(user, intent, { previewAll: true, via: "wallet" });
  const again = await order.placeDedicatedOrder(user, intent, { previewAll: true, via: "wallet" });
  assert.equal(first.created, true);
  assert.equal(again.serverId, first.serverId);
  assert.equal(again.created, false);
  const after = await db.user.findUniqueOrThrow({ where: { id: userId } });
  assert.equal(after.balanceCents, 1234, "debited the total exactly once");
  const s = await db.dedicatedServer.findUniqueOrThrow({ where: { id: first.serverId } });
  assert.equal(s.status, "PENDING");
  assert.equal(s.userId, userId);
  assert.equal(s.renewalMonthlyCents, q.money.monthlyCents);
  assert.equal(s.termMonths, 1);
  assert.equal(s.region, intent.region);
  assert.ok(s.datacenter && s.costMonthlyCents != null, "admin-only fulfilment fields recorded");
  const inv = await db.invoice.findUniqueOrThrow({ where: { id: s.invoiceIds[0] } });
  assert.equal(inv.status, "PAID");
  assert.equal(inv.amountCents, q.money.totalCents);
  assert.equal(await db.notification.count({ where: { userId, href: `/dashboard/dedicated/${s.id}` } }), 1);
});

test("card path: fulfilment credits the card leg, debits the STAMPED total once, lands PENDING", { skip }, async () => {
  const { intent } = await anInStockIntent();
  const cardIntent = { ...intent, termMonths: 12 as const, orderKey: key() };
  const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  const q = await order.quoteDedicatedOrder(cardIntent, user, { previewAll: true });
  const start = 2000;
  await db.user.update({ where: { id: userId }, data: { balanceCents: start } });
  const cardCents = q.money.totalCents - start;
  const sid = `cs_test_ded_${Date.now()}`;
  const session = {
    id: sid, payment_status: "paid", amount_total: cardCents, currency: "usd", payment_intent: null, customer: null,
    metadata: { nxeonUserId: userId, nxeonDedicatedOrder: JSON.stringify(cardIntent), nxeonDedicatedOrderPrice: JSON.stringify(q.money) },
  } as never;
  const r1 = await fulfil(session, "");
  const r2 = await fulfil(session, "");
  assert.equal(r1.kind, "dedicatedOrder");
  assert.equal(r1.fulfilled, true, r1.error);
  assert.match(r1.redirect, /^\/dashboard\/dedicated\/[a-z0-9]+\?ordered=1$/);
  assert.equal(r2.fulfilled, false, "second delivery (webhook + redirect race) is a no-op");
  const servers = await db.dedicatedServer.findMany({ where: { orderKey: cardIntent.orderKey } });
  assert.equal(servers.length, 1);
  assert.equal(servers[0].termMonths, 12);
  const after = await db.user.findUniqueOrThrow({ where: { id: userId } });
  assert.equal(after.balanceCents, 0, "wallet ends at start + card leg - total = 0");
  const inv = await db.invoice.findUniqueOrThrow({ where: { id: servers[0].invoiceIds[0] } });
  assert.equal(inv.amountCents, q.money.totalCents);
  // the card leg must not ALSO produce a top-up invoice (isPurchaseLegSession)
  assert.equal(await db.invoice.count({ where: { userId, description: { contains: "top-up" } } }), 0);
});

test("a tampered stamp is never fulfilled as a purchase or a top-up order", { skip }, async () => {
  const { intent } = await anInStockIntent();
  const sid = `cs_test_ded_bad_${Date.now()}`;
  const session = {
    id: sid, payment_status: "paid", amount_total: 5000, currency: "usd", payment_intent: null, customer: null,
    metadata: { nxeonUserId: userId, nxeonDedicatedOrder: JSON.stringify({ ...intent, orderKey: key() }), nxeonDedicatedOrderPrice: JSON.stringify({ monthlyCents: 1, termMonths: 1, setupCents: 0, taxCents: 0, totalCents: 999999 }) },
  } as never;
  const r = await fulfil(session, "");
  assert.equal(r.kind, "none");
  assert.equal(r.fulfilled, false);
  assert.ok(r.error);
});

