// Dedicated private-preview flow: real browser walk-through + screenshots.
// Usage: node shots.js <base> <outDir> <authSecret>
const path = require("path");
const NM = "/tank/nxeon-wt-dedicated2/node_modules/";
const { chromium } = require(NM + "playwright");
const { execSync } = require("child_process");

const [base, out, secret] = process.argv.slice(2);
const OWNER = "cmrztujaw0002hlazl58i3lsi";
const OTHER = "cmothercustomer0000000001";
const ADMIN = "cmadminpreview00000000001";
const psql = (sql) => execSync(`psql -h 127.0.0.1 -p 55447 -U postgres dedprev -Atc ${JSON.stringify(sql)}`).toString().trim();

async function token(sub) {
  const { SignJWT } = await import(NM + "jose/dist/node/esm/index.js").catch(() => import(NM + "jose/dist/webapi/index.js")).catch(() => require(NM + "jose"));
  return new SignJWT({ sub, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(secret));
}

const log = (...a) => console.log(...a);

async function ctxFor(browser, sub, mobile) {
  const ctx = await browser.newContext(mobile
    ? { viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, colorScheme: "dark" }
    : { viewport: { width: 1440, height: 900 }, colorScheme: "dark" });
  if (sub) {
    const u = new URL(base);
    await ctx.addCookies([
      { name: "nxeon_session", value: await token(sub), domain: u.hostname, path: "/", httpOnly: true },
      { name: "nxeon_authed", value: "1", domain: u.hostname, path: "/" },
    ]);
  }
  return ctx;
}

async function shot(page, name, full = true) {
  await page.waitForTimeout(900);
  await page.screenshot({ path: path.join(out, name + ".png"), fullPage: full });
  log("shot", name, page.url());
}

async function overflow(page) {
  return page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
}

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const watch = (page, tag) => {
    page.on("pageerror", (e) => errors.push(`${tag} PAGEERROR ${e.message}`));
    page.on("console", (m) => { if (m.type() === "error") errors.push(`${tag} CONSOLE ${m.text().slice(0, 200)}`); });
  };

  for (const mobile of [false, true]) {
    const sfx = mobile ? "mobile" : "desktop";
    psql(`update "User" set "balanceCents"=5000 where id='${OWNER}'`);
    const ctx = await ctxFor(browser, OWNER, mobile);
    const page = await ctx.newPage();
    watch(page, sfx);

    // 0. dashboard list before any order (empty state)
    await page.goto(`${base}/dashboard/dedicated`, { waitUntil: "networkidle" });
    await shot(page, `00-dashboard-list-empty-${sfx}`);
    // 1. marketing page (preview account)
    await page.goto(`${base}/dedicated-servers`, { waitUntil: "networkidle" });
    await shot(page, `01-marketing-page-${sfx}`);
    // 2. catalogue
    await page.goto(`${base}/dashboard/dedicated/order`, { waitUntil: "networkidle" });
    await shot(page, `02-catalogue-${sfx}`);
    log("overflow catalogue", await overflow(page));
    // filter example: Singapore + 64GB
    const sel = page.locator("select").first();
    const sgp = await sel.locator("option", { hasText: "Singapore" }).first().getAttribute("value").catch(() => null);
    if (sgp) { await sel.selectOption(sgp); await page.locator("select").nth(2).selectOption("64"); await shot(page, `02b-catalogue-filtered-${sfx}`); }
    // filter to nothing -> designed empty state
    await page.locator("select").nth(4).selectOption("50");
    await page.locator("select").nth(2).selectOption("512");
    await shot(page, `02c-catalogue-no-match-${sfx}`, false);
    await page.getByRole("button", { name: "Clear filters" }).first().click();

    // pick a build priced above the $50 wallet so the card leg is exercised: the 3rd cheapest card
    const links = page.locator('a:has-text("Configure")');
    const n = await links.count();
    await links.nth(Math.min(4, n - 1)).click();
    await page.waitForURL(/\/dashboard\/dedicated\/order\/.+/);
    await page.waitForLoadState("networkidle");
    // 3. configure
    await shot(page, `03-configure-${sfx}`);
    log("overflow configure", await overflow(page));
    // choose annual if offered + a name
    await page.getByRole("button", { name: /Annual/ }).first().click().catch(() => {});
    await page.getByLabel("Server name").fill(mobile ? "Mobile test box" : "Preview test box");
    await shot(page, `03b-configure-annual-${sfx}`);
    // 4. review
    await page.getByRole("button", { name: /Review order/ }).click();
    await page.getByText("Order summary").first().waitFor();
    await page.waitForSelector("text=Continue to payment", { timeout: 20000 });
    await shot(page, `04-review-${sfx}`);
    log("overflow review", await overflow(page));
    // 5. pay: card leg (wallet $50 applied)
    await page.getByRole("button", { name: /Continue to payment/ }).click();
    const frame = page.frameLocator('iframe[name^="__privateStripeFrame"]').first();
    await page.waitForSelector('iframe[name^="__privateStripeFrame"]', { timeout: 40000 });
    await page.waitForTimeout(4000);
    await shot(page, `05-pay-card-${sfx}`);
    if (!mobile) {
      // Stripe TEST MODE card. Never a live key here (checked by the caller).
      try {
        const num = frame.locator('input[name="number"]');
        await num.waitFor({ timeout: 20000 });
        await num.fill("4242424242424242");
        await frame.locator('input[name="expiry"]').fill("12 / 34");
        await frame.locator('input[name="cvc"]').fill("123");
        const country = frame.locator('select[name="country"]');
        if (await country.count()) await country.selectOption("US").catch(() => {});
        const zip = frame.locator('input[name="postalCode"]');
        if (await zip.count()) await zip.fill("10001");
        await shot(page, `05b-pay-card-filled-${sfx}`);
        await page.getByRole("button", { name: /^Pay \$/ }).click();
        await page.waitForURL(/\/dashboard\/dedicated\/[a-z0-9]+\?ordered=1/, { timeout: 90000 });
        await page.waitForLoadState("networkidle");
        await shot(page, `06-server-ordered-card-${sfx}`);
        log("CARD ORDER OK", page.url());
      } catch (e) {
        log("CARD PAYMENT STEP FAILED", e.message);
        await shot(page, `05x-pay-card-error-${sfx}`);
      }
    }

    // wallet-only path: top up the throwaway wallet and order again
    psql(`update "User" set "balanceCents"=900000 where id='${OWNER}'`);
    await page.goto(`${base}/dashboard/dedicated/order`, { waitUntil: "networkidle" });
    await page.locator('a:has-text("Configure")').first().click();
    await page.waitForURL(/\/dashboard\/dedicated\/order\/.+/);
    await page.waitForLoadState("networkidle");
    await page.getByRole("button", { name: /Review order/ }).click();
    await page.waitForSelector("text=Continue to payment", { timeout: 20000 });
    await shot(page, `07-review-wallet-${sfx}`);
    await page.getByRole("button", { name: /Continue to payment/ }).click();
    await page.waitForSelector("text=Wallet balance", { timeout: 20000 });
    await shot(page, `08-pay-wallet-${sfx}`);
    await page.getByRole("button", { name: /^Pay \$/ }).click();
    await page.waitForURL(/\/dashboard\/dedicated\/[a-z0-9]+\?ordered=1/, { timeout: 60000 });
    await page.waitForLoadState("networkidle");
    await shot(page, `09-server-ordered-wallet-${sfx}`);
    log("overflow server", await overflow(page));
    const serverId = /dedicated\/([a-z0-9]+)/.exec(page.url())[1];

    // dashboard list with servers
    await page.goto(`${base}/dashboard/dedicated`, { waitUntil: "networkidle" });
    await shot(page, `10-dashboard-list-${sfx}`);

    // staff fulfil by hand (simulated in the throwaway DB): IPs + ACTIVE
    psql(`update "DedicatedServer" set status='ACTIVE', "provisionedAt"=now(), ipv4='{203.0.113.40,203.0.113.41}', ipv6='{2001:db8:40::1/64}', hostname='box1.example.com' where id='${serverId}'`);
    await page.goto(`${base}/dashboard/dedicated/${serverId}`, { waitUntil: "networkidle" });
    await shot(page, `11-server-online-${sfx}`);
    await ctx.close();

    // portal rail with the nav entry (desktop only)
    // non-preview account: 404 everywhere, no nav entry
    const octx = await ctxFor(browser, OTHER, mobile);
    const op = await octx.newPage();
    for (const [p, name] of [["/dedicated-servers", "12-other-account-marketing-404"], ["/dashboard/dedicated", "13-other-account-dashboard-404"], ["/dashboard/dedicated/order", "14-other-account-order-404"]]) {
      const r = await op.goto(`${base}${p}`, { waitUntil: "networkidle" });
      log("OTHER", p, r.status());
      await shot(op, `${name}-${sfx}`, false);
    }
    const navHas = await op.goto(`${base}/dashboard`, { waitUntil: "networkidle" }).then(() => op.locator('a[href="/dashboard/dedicated"]').count());
    log("OTHER nav entries", navHas);
    await octx.close();

    // signed-out
    const actx = await ctxFor(browser, null, mobile);
    const ap = await actx.newPage();
    const r1 = await ap.goto(`${base}/dedicated-servers`, { waitUntil: "networkidle" });
    log("ANON /dedicated-servers", r1.status());
    await shot(ap, `15-signed-out-marketing-404-${sfx}`, false);
    await ap.goto(`${base}/dashboard/dedicated/order`, { waitUntil: "networkidle" });
    log("ANON /dashboard/dedicated/order ->", ap.url());
    await actx.close();

    // admin: managed servers list + the order's build sheet
    const adctx = await ctxFor(browser, ADMIN, mobile);
    const adp = await adctx.newPage();
    await adp.goto(`${base}/admin/dedicated/servers`, { waitUntil: "networkidle" });
    await shot(adp, `16-admin-servers-${sfx}`);
    const pend = psql(`select id from "DedicatedServer" where "userId"='${OWNER}' and status='PENDING' order by "createdAt" desc limit 1`);
    if (pend) { await adp.goto(`${base}/admin/dedicated/servers/${pend}`, { waitUntil: "networkidle" }); await shot(adp, `17-admin-order-detail-${sfx}`); }
    await adctx.close();
  }

  // owner nav entry check
  const nctx = await ctxFor(browser, OWNER, false);
  const np = await nctx.newPage();
  await np.goto(`${base}/dashboard`, { waitUntil: "networkidle" });
  log("OWNER nav entries", await np.locator('a[href="/dashboard/dedicated"]').count());
  await shot(np, `18-owner-portal-nav-desktop`, false);
  await nctx.close();

  await browser.close();
  log("ERRORS", errors.length ? "\n" + errors.join("\n") : "none");
})().catch((e) => { console.error(e); process.exit(1); });

