/**
 * How the OVH admin controls reach OVH.
 *
 *  - READS go through `adminOvhGet` (GET only, hard-wired).
 *  - WRITES go through `ovhAdminWrite` in ./write.ts and NOWHERE else
 *    (test/ovh-admin.test.ts enforces this on the source tree).
 *
 * Screenshot/dev stub: with NXEON_OVH_ADMIN_STUB=1 on a non-production
 * process, both are served by an in-memory fake (./stub.ts) so the panels can
 * be rendered without touching the real account. The flag is ignored when
 * NODE_ENV=production, so a stray env var on prod cannot fake OVH state.
 */
import { ovh } from "../ovh";

export const OVH_ADMIN_STUB = process.env.NXEON_OVH_ADMIN_STUB === "1" && process.env.NODE_ENV !== "production";

export type OvhGetter = (path: string) => Promise<any>;
export type OvhSender = (method: "POST" | "PUT" | "DELETE", path: string, body?: unknown) => Promise<any>;

export async function adminOvhGet(path: string): Promise<any> {
  if (OVH_ADMIN_STUB) return (await import("./stub")).stubGet(path);
  return ovh("GET", path);
}

/** Only ./write.ts may import this. */
export async function rawOvhSend(method: "POST" | "PUT" | "DELETE", path: string, body?: unknown): Promise<any> {
  if (OVH_ADMIN_STUB) return (await import("./stub")).stubSend(method, path, body);
  return ovh(method, path, body);
}

export function ovhAdminConfigured(): boolean {
  if (OVH_ADMIN_STUB) return true;
  return !!(process.env.OVH_APPLICATION_KEY && process.env.OVH_APPLICATION_SECRET && process.env.OVH_CONSUMER_KEY);
}

/**
 * THE single audited wrapper for every OVH write the admin controls make.
 *
 * Every POST/PUT/DELETE to OVH from lib/ovh-admin/** goes through
 * `ovhAdminWrite`, which, in order:
 *   1. refuses in sandbox (staging) unless the dev stub is on;
 *   2. checks the consumer key actually holds the right (graceful
 *      "needs OVH API right X" instead of a raw 403);
 *   3. rate-limits per actor (normal / dangerous classes) and per target;
 *   4. de-duplicates a double submit (same idempotency key within 30 s);
 *   5. reads the current state ("before") and returns a NO-OP if it already
 *      matches what was asked (idempotent: re-clicking "strict off" on an
 *      already-off IP sends nothing to OVH);
 *   6. writes an AuditLog row BEFORE sending (so a crash mid-call still leaves
 *      a trace) and another with the outcome;
 *   7. sends, then reads the state back ("after") and returns both, so the UI
 *      always shows what OVH really says, not what we hoped.
 *
 * Callers (lib/ovh-admin/actions.ts) are responsible for authentication,
 * input validation and typed confirmations BEFORE they get here.
 * test/ovh-admin.test.ts: "every OVH write goes through one audited wrapper".
 */
import { rawOvhSend, adminOvhGet, OVH_ADMIN_STUB } from "./transport";
import { parseCredentialRules, rulesAllow, needsRightMessage, rightsErrorFor, type AccessRule } from "./rights";

export type WriteMethod = "POST" | "PUT" | "DELETE";

export type WriteDeps = {
  send: (method: WriteMethod, path: string, body?: unknown) => Promise<any>;
  rules: () => Promise<AccessRule[] | null>;
  audit: (userId: string, action: string, detail: string) => Promise<void>;
  rateLimit: (key: string, opts: { max: number; windowMs: number }) => { ok: boolean; retryAfterSec: number };
  claimOnce: (key: string, ttlMs: number) => boolean;
  sandbox: boolean;
};

export type OvhWriteRequest<S> = {
  actor: { id: string };
  /** Audit action key, e.g. "ovh.game.strict". */
  action: string;
  /** Human target for the audit row, e.g. the IP or node name. */
  target: string;
  method: WriteMethod;
  path: string;
  body?: unknown;
  /** Reads the relevant OVH state; called before and after the write. */
  read: () => Promise<S>;
  /** True when `before` already equals the requested end state: nothing is sent. */
  isNoop?: (before: S) => boolean;
  idempotencyKey?: string;
  rateClass?: "normal" | "dangerous";
  /** Free text recorded in the audit row (reason, typed confirmation summary). */
  note?: string;
};

export type OvhWriteResult<S> =
  | { ok: true; noop: boolean; before: S; after: S; response: unknown }
  | { ok: false; error: string; before?: S; needsRight?: boolean };

export const RATE = {
  normal: { max: 30, windowMs: 10 * 60_000 },
  dangerous: { max: 3, windowMs: 60 * 60_000 },
  perTarget: { max: 12, windowMs: 10 * 60_000 },
} as const;

const RULES_TTL_MS = 5 * 60_000;
let rulesCache: { at: number; rules: AccessRule[] | null } | null = null;

/** The key's own access rules, cached 5 minutes. null = could not read them. */
export async function currentKeyRules(get: (p: string) => Promise<any> = adminOvhGet): Promise<AccessRule[] | null> {
  if (rulesCache && Date.now() - rulesCache.at < RULES_TTL_MS) return rulesCache.rules;
  let rules: AccessRule[] | null = null;
  try {
    rules = parseCredentialRules(await get("/auth/currentCredential"));
  } catch {
    rules = null;
  }
  rulesCache = { at: Date.now(), rules };
  return rules;
}

export function _resetRulesCacheForTests(): void {
  rulesCache = null;
}

async function defaultDeps(): Promise<WriteDeps> {
  const [{ recordAudit }, rl, { SANDBOX }] = await Promise.all([import("../audit"), import("../rate-limit"), import("../sandbox")]);
  return {
    send: rawOvhSend,
    rules: () => currentKeyRules(),
    audit: (u, a, d) => recordAudit(u, a, d),
    rateLimit: rl.checkRateLimit,
    claimOnce: rl.claimOnce,
    sandbox: SANDBOX && !OVH_ADMIN_STUB,
  };
}

const DEP_KEYS: (keyof WriteDeps)[] = ["send", "rules", "audit", "rateLimit", "claimOnce", "sandbox"];
function isFullDeps(d: Partial<WriteDeps> | undefined): d is WriteDeps {
  return !!d && DEP_KEYS.every((k) => d[k] !== undefined);
}

function summarise(v: unknown, max = 900): string {
  let s: string;
  try {
    s = JSON.stringify(v);
  } catch {
    s = String(v);
  }
  return (s ?? "null").length > max ? `${s.slice(0, max)}...` : s ?? "null";
}

export async function ovhAdminWrite<S>(req: OvhWriteRequest<S>, depsIn?: Partial<WriteDeps>): Promise<OvhWriteResult<S>> {
  const deps: WriteDeps = isFullDeps(depsIn) ? depsIn : { ...(await defaultDeps()), ...depsIn };
  const head = `${req.method} ${req.path} target=${req.target}`;

  if (deps.sandbox) return { ok: false, error: "OVH writes are disabled in sandbox/staging." };

  // 2. rights
  const rules = await deps.rules();
  if (rules && !rulesAllow(rules, req.method, req.path)) {
    return { ok: false, error: needsRightMessage(req.method, req.path), needsRight: true };
  }

  // 3. rate limits
  const cls = req.rateClass ?? "normal";
  const a = deps.rateLimit(`ovh-admin:${cls}:${req.actor.id}`, RATE[cls]);
  if (!a.ok) return { ok: false, error: `Too many OVH changes; try again in ${a.retryAfterSec}s.` };
  const t = deps.rateLimit(`ovh-admin:target:${req.target}`, RATE.perTarget);
  if (!t.ok) return { ok: false, error: `Too many changes to ${req.target}; try again in ${t.retryAfterSec}s.` };

  // 4. double-submit guard
  if (req.idempotencyKey && !deps.claimOnce(`ovh-admin:${req.actor.id}:${req.idempotencyKey}`, 30_000)) {
    return { ok: false, error: "That exact change was just submitted; refresh to see its result." };
  }

  // 5. before + no-op
  let before: S;
  try {
    before = await req.read();
  } catch (e) {
    return { ok: false, error: `Could not read the current OVH state, so nothing was changed: ${rightsErrorFor(e, "GET", req.path)}` };
  }
  if (req.isNoop?.(before)) {
    await deps.audit(req.actor.id, `${req.action}.noop`, `${head} already in the requested state ${req.note ? `note=${req.note} ` : ""}state=${summarise(before)}`);
    return { ok: true, noop: true, before, after: before, response: null };
  }

  // 6. audit, send, audit
  await deps.audit(req.actor.id, `${req.action}.request`, `${head} body=${summarise(req.body ?? null, 400)} ${req.note ? `note=${req.note} ` : ""}before=${summarise(before)}`);
  let response: unknown;
  try {
    response = await deps.send(req.method, req.path, req.body);
  } catch (e) {
    const error = rightsErrorFor(e, req.method, req.path);
    await deps.audit(req.actor.id, `${req.action}.error`, `${head} error=${error}`);
    return { ok: false, error, before, needsRight: /Needs OVH API right/.test(error) };
  }

  // 7. read back
  let after: S;
  try {
    after = await req.read();
  } catch {
    after = before;
  }
  await deps.audit(req.actor.id, `${req.action}.ok`, `${head} response=${summarise(response, 300)} after=${summarise(after)}`);
  return { ok: true, noop: false, before, after, response };
}
/**
 * Pure policy for the OVH admin controls: who counts as the OWNER, and the
 * single-use, short-lived challenge that guards node reboot / rescue boot.
 *
 * OWNER: the platform has no separate owner role (one ADMIN account today), so
 *  - if NXEON_OWNER_EMAILS is set (comma-separated), only those ADMIN emails;
 *  - otherwise the ADMIN account counts as owner ONLY while it is the sole
 *    ADMIN. A second ADMIN appearing makes owner-only controls fail closed
 *    until the env var names the owner explicitly.
 *
 * CHALLENGE (reboot / rescue): an action cannot be executed from one click or
 * from a stale page. `prepare` snapshots the node's customer-VM list and
 * returns a nonce; `execute` must present that nonce (single-use, 5-minute
 * TTL, bound to the same admin + node + action), the node's exact name typed,
 * and the VM count it was shown. If any VM was added/removed since the warning
 * was rendered the fingerprint differs and execution is refused.
 */
import { createHash, randomBytes } from "node:crypto";

export function parseOwnerEmails(raw: string | undefined | null): string[] {
  return (raw ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter((s) => s.includes("@"));
}

export function isOwner(user: { role: string; email: string }, ownerEmails: readonly string[], adminCount: number): { ok: true } | { ok: false; error: string } {
  if (user.role !== "ADMIN") return { ok: false, error: "Owner only." };
  if (ownerEmails.length > 0) {
    return ownerEmails.includes(user.email.toLowerCase()) ? { ok: true } : { ok: false, error: "Owner only (not listed in NXEON_OWNER_EMAILS)." };
  }
  if (adminCount === 1) return { ok: true };
  return { ok: false, error: "Owner only: more than one ADMIN exists, so set NXEON_OWNER_EMAILS to name the owner." };
}

export type PowerAction = "reboot" | "rescue_on" | "rescue_off" | "rescue_on_reboot" | "rescue_off_reboot";
export const POWER_ACTIONS: PowerAction[] = ["reboot", "rescue_on", "rescue_off", "rescue_on_reboot", "rescue_off_reboot"];

export function powerActionLabel(a: PowerAction): string {
  return {
    reboot: "Hard reboot",
    rescue_on: "Set netboot to RESCUE (no reboot)",
    rescue_off: "Set netboot back to DISK (no reboot)",
    rescue_on_reboot: "Boot into RESCUE now (netboot rescue + hard reboot)",
    rescue_off_reboot: "Boot back to DISK now (netboot disk + hard reboot)",
  }[a];
}

export function powerActionReboots(a: PowerAction): boolean {
  return a === "reboot" || a.endsWith("_reboot");
}

/** Stable fingerprint of the VMs the warning listed (id + status), order-independent. */
export function vmFingerprint(vms: readonly { id: string; status: string }[]): string {
  const s = [...vms].map((v) => `${v.id}:${v.status}`).sort().join("|");
  return createHash("sha256").update(s).digest("hex").slice(0, 32);
}

export type Challenge = {
  nonce: string;
  userId: string;
  nodeId: string;
  nodeName: string;
  action: PowerAction;
  fingerprint: string;
  vmCount: number;
  expiresAt: number;
};

export const CHALLENGE_TTL_MS = 5 * 60_000;

export class ChallengeStore {
  private m = new Map<string, Challenge>();
  constructor(private now: () => number = Date.now) {}

  issue(c: Omit<Challenge, "nonce" | "expiresAt">): Challenge {
    this.gc();
    const nonce = randomBytes(24).toString("hex");
    const ch = { ...c, nonce, expiresAt: this.now() + CHALLENGE_TTL_MS };
    this.m.set(nonce, ch);
    return ch;
  }

  /**
   * Single-use: the nonce is consumed on ANY attempt (right or wrong), so a
   * mistyped confirmation means starting again from a freshly rendered warning.
   */
  redeem(input: {
    nonce: unknown;
    userId: string;
    typedName: unknown;
    ackVmCount: unknown;
    currentFingerprint: (nodeId: string) => Promise<string> | string;
  }): Promise<{ ok: true; challenge: Challenge } | { ok: false; error: string }> {
    return (async () => {
      if (typeof input.nonce !== "string" || !/^[0-9a-f]{48}$/.test(input.nonce)) return { ok: false as const, error: "Missing or malformed confirmation token. Start again." };
      const ch = this.m.get(input.nonce);
      this.m.delete(input.nonce);
      if (!ch) return { ok: false as const, error: "This confirmation was already used or never issued. Start again." };
      if (this.now() > ch.expiresAt) return { ok: false as const, error: "This confirmation expired (5 minutes). Start again." };
      if (ch.userId !== input.userId) return { ok: false as const, error: "This confirmation belongs to another admin session." };
      if (typeof input.typedName !== "string" || input.typedName.trim() !== ch.nodeName) {
        return { ok: false as const, error: `Typed name does not match the node name exactly. Start again.` };
      }
      const ack = typeof input.ackVmCount === "number" ? input.ackVmCount : Number(input.ackVmCount);
      if (!Number.isInteger(ack) || ack !== ch.vmCount) return { ok: false as const, error: `Confirm the number of affected customer VMs (${ch.vmCount}). Start again.` };
      const fp = await input.currentFingerprint(ch.nodeId);
      if (fp !== ch.fingerprint) return { ok: false as const, error: "The VMs on this node changed since the warning was shown (stale page). Review the new list and start again." };
      return { ok: true as const, challenge: ch };
    })();
  }

  private gc() {
    const t = this.now();
    for (const [k, v] of this.m) if (v.expiresAt < t) this.m.delete(k);
  }
}

const g = globalThis as unknown as { __ovhPowerChallenges?: ChallengeStore };
export function powerChallenges(): ChallengeStore {
  g.__ovhPowerChallenges ??= new ChallengeStore();
  return g.__ovhPowerChallenges;
}

