export type NetworkRuleInput = {
  sequence: number;
  action: FwAction;
  protocol: FwProtocol;
  /** Only for tcp/udp. */
  destinationPort: { from: number; to: number } | null;
  source: string | null;
};

export function parseNetworkRule(raw: {
  sequence?: unknown;
  action?: unknown;
  protocol?: unknown;
  ports?: unknown;
  source?: unknown;
}): Result<NetworkRuleInput> {
  const seqS = typeof raw.sequence === "number" ? String(raw.sequence) : typeof raw.sequence === "string" ? raw.sequence.trim() : "";
  if (!/^\d{1,2}$/.test(seqS) || Number(seqS) > FW_MAX_SEQUENCE) return bad(`Sequence must be 0 to ${FW_MAX_SEQUENCE}.`);
  const action = typeof raw.action === "string" ? raw.action.trim() : "";
  if (!(FW_ACTIONS as readonly string[]).includes(action)) return bad("Action must be permit or deny.");
  const protocol = typeof raw.protocol === "string" ? raw.protocol.trim() : "";
  if (!(FW_PROTOCOLS as readonly string[]).includes(protocol)) return bad("Unknown protocol.");
  const portsRaw = typeof raw.ports === "string" ? raw.ports.trim() : raw.ports;
  let destinationPort: { from: number; to: number } | null = null;
  if (portsRaw !== undefined && portsRaw !== null && portsRaw !== "") {
    if (protocol !== "tcp" && protocol !== "udp") return bad("Ports only apply to tcp or udp rules.");
    const r = parsePortRange(portsRaw);
    if (!r.ok) return r;
    destinationPort = r.value;
  }
  const src = parseSourceCidr(raw.source);
  if (!src.ok) return src;
  return ok({ sequence: Number(seqS), action: action as FwAction, protocol: protocol as FwProtocol, destinationPort, source: src.value });
}

/** The exact POST body OVH's /ip/{ip}/firewall/{ip}/rule expects. */
export function networkRuleBody(r: NetworkRuleInput): Record<string, unknown> {
  const body: Record<string, unknown> = { sequence: r.sequence, action: r.action, protocol: r.protocol };
  if (r.destinationPort) {
    if (r.destinationPort.from === r.destinationPort.to) body.destinationPort = r.destinationPort.from;
    else body.destinationPortRange = { from: r.destinationPort.from, to: r.destinationPort.to };
  }
  if (r.source) body.source = r.source;
  return body;
}

