/**
 * A PTR target: a fully-qualified hostname (at least two labels, alphabetic
 * TLD), LDH labels of 1-63 chars, total <= 253. Lower-cased, returned WITH the
 * trailing dot OVH stores.
 */
export function parseReverseHostname(raw: unknown): Result<string> {
export function parseReverseHostname(raw: unknown): Result<string> {
  let s = typeof raw === "string" ? raw.trim().toLowerCase() : "";
  if (s.endsWith(".")) s = s.slice(0, -1);
  if (!s) return bad("Enter a hostname, e.g. mail.example.com.");
  if (s.length > 253) return bad("Hostname is longer than 253 characters.");
  const labels = s.split(".");
  if (labels.length < 2) return bad("Use a fully-qualified hostname (e.g. host.example.com), not a single label.");
  for (const l of labels) {
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l)) {
      return bad(`"${l || "(empty)"}" is not a valid hostname label (letters, digits and inner hyphens, 1-63 chars).`);
    }
  }
  if (!/^[a-z]{2,63}$/.test(labels[labels.length - 1])) return bad("The last label (TLD) must be letters only.");
  return ok(`${s}.`);
}

