export async function addNetworkRule(
  address: string,
  input: { sequence: string; action: string; protocol: string; ports?: string; source?: string },
): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const v = parseNetworkRule(input ?? {});
    if (!v.ok) return { ok: false, error: v.error };
    const rule = v.value;
    const body = networkRuleBody(rule);
    const current = await readNetwork(t.block, t.address);
    if (!current.exists) return { ok: false, error: "This IP is not on the OVH network firewall yet; add it first." };
    const portStr = rule.destinationPort ? (rule.destinationPort.from === rule.destinationPort.to ? `eq ${rule.destinationPort.from}` : `range ${rule.destinationPort.from} ${rule.destinationPort.to}`) : null;
    const identical = (n: NetView) =>
      n.rules.some((r) => r.sequence === rule.sequence && r.action === rule.action && r.protocol === rule.protocol && (r.destinationPort ?? null) === portStr && ((r.source ?? "any") === (rule.source ?? "any") || (rule.source === null && r.source === "0.0.0.0/0")));
    const taken = current.rules.find((r) => r.sequence === rule.sequence);
    if (taken && !identical(current)) return { ok: false, error: `Sequence ${rule.sequence} is already used by another rule; remove it first or pick a free sequence.` };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.rule.add",
      target: t.address,
      method: "POST",
      path: `/ip/${enc(t.block)}/firewall/${enc(t.address)}/rule`,
      body,
      read: () => readNetwork(t.block, t.address),
      isNoop: identical,
      idempotencyKey: `netfw-rule:${t.address}:${JSON.stringify(body)}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

export async function removeNetworkRule(address: string, sequence: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (typeof sequence !== "string" || !/^\d{1,2}$/.test(sequence) || Number(sequence) > 19) return { ok: false, error: "Invalid sequence." };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.rule.remove",
      target: t.address,
      method: "DELETE",
      path: `/ip/${enc(t.block)}/firewall/${enc(t.address)}/rule/${sequence}`,
      read: () => readNetwork(t.block, t.address),
      isNoop: (n) => !n.rules.some((x) => String(x.sequence) === sequence),
      idempotencyKey: `netfw-rule-rm:${t.address}:${sequence}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

