export type OpsWrite = (req: { action: string; method: "POST" | "PUT" | "DELETE"; path: string; body?: unknown; target: string; dangerous?: boolean }) => Promise<{ ok: true; response: any } | { ok: false; error: string }>;
export type OpsClient = { get: (path: string) => Promise<any>; write: OpsWrite };

export type JobInput = { id: string; kind: DedicatedJobKind | string; payload: any; state: any; dryRun: boolean; userId: string };
export type ServerInput = { id: string; serviceName: string | null; status: string; label: string; ipv4: string[]; ipv6: string[]; os: string | null };

export type Effects = {
  /** Fields to set on the DedicatedServer row. */
  server?: { status?: "ACTIVE"; provisionedAt?: true; ipv4?: string[]; ipv6?: string[]; hostname?: string; os?: string; credentialsUser?: string; credentialsDeliveredAt?: true; renewalAddMonthlyCents?: number; extraIpAddMonthlyCents?: number };
