export type StepResult = {
  status: "WAITING" | "DONE" | "FAILED";
  step: string;
  progress: number;
  state?: any;
  error?: string;
  effects?: Effects;
};

export type StepDeps = { client: OpsClient; protectedServiceNames: ReadonlySet<string>; now: () => Date; ovhSubsidiary?: string };

const enc = encodeURIComponent;
const fail = (step: string, error: string, effects?: Effects): StepResult => ({ status: "FAILED", step, progress: 100, error, effects });
const done = (step: string, effects?: Effects): StepResult => ({ status: "DONE", step, progress: 100, effects });
