/** Guards that apply to every job. Returns an error string or null. */
export function guardJob(job: JobInput, server: ServerInput, protectedNames: ReadonlySet<string>): string | null {
  const sn = server.serviceName?.trim() ?? "";
  if (!sn) return "This server is not linked to a physical machine yet.";
  if (protectedNames.has(sn) || protectedNames.has(sn.toLowerCase())) return "Refused: this machine is platform infrastructure, not a customer server.";
  if (!/^[a-z0-9][a-z0-9.-]{2,120}$/i.test(sn)) return "Refused: malformed service name.";
