    if (server.status !== "PENDING" && server.status !== "PROVISIONING") return "Handover only runs for a server that is not yet delivered.";
  } else if (job.kind === "IP_ORDER") {
    if (server.status !== "ACTIVE" && server.status !== "SUSPENDED") return "Extra IPs need a delivered server.";
  } else if (server.status !== "ACTIVE") {
    return "This action needs the server to be online.";
  }
