/** Poll one upstream task; null task id means the write returned no task. */
async function pollTask(client: OpsClient, base: string, taskId: number | null): Promise<"done" | "running" | "error"> {
  if (taskId === null) return "done";
  const t = parseTask(await client.get(`${base}/task/${taskId}`).catch(() => null));
  if (!t) return "running";
  if (taskInFlight(t)) return "running";
  return t.status === "done" ? "done" : "error";
}

const taskIdOf = (r: any): number | null => (r && typeof r === "object" && Number.isInteger(r.taskId) ? r.taskId : null);

