  const ids = await client.get(`${base}/boot?bootType=${type}`);
  return Array.isArray(ids) && ids.length ? Number(ids[0]) : null;
}

export async function runJobStep(job: JobInput, server: ServerInput, deps: StepDeps): Promise<StepResult> {
  const g = guardJob(job, server, deps.protectedServiceNames);
  if (g) return fail("Refused", g, job.kind === "IP_ORDER" ? { ipOrder: { status: "FAILED" } } : undefined);
  const { client } = deps;
  const sn = server.serviceName!.trim();
  const base = `/dedicated/server/${enc(sn)}`;
  const st = job.state ?? {};
  const p = job.payload ?? {};

  switch (job.kind) {
    /* ---------------- power ---------------- */
    case "REBOOT_HARD": {
      if (st.phase === "wait") {
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "running") return { status: "WAITING", step: "Restarting the machine", progress: 60, state: st };
        return r === "done" ? done("Restarted") : fail("Reboot failed", "The machine did not confirm the restart. Our team has been told.");
      }
      if (job.dryRun) return dry("a hard reboot");
      const w = await client.write({ action: "dedicated.reboot", method: "POST", path: `${base}/reboot`, target: sn, dangerous: true });
      if (!w.ok) return fail("Reboot failed", w.error);
      return { status: "WAITING", step: "Restarting the machine", progress: 30, state: { phase: "wait", taskId: taskIdOf(w.response) } };
    }

    /* ---------------- rescue ---------------- */
    case "RESCUE_ON":
    case "RESCUE_OFF": {
      const on = job.kind === "RESCUE_ON";
      if (st.phase === "wait") {
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "running") return { status: "WAITING", step: on ? "Booting the rescue system" : "Booting from disk", progress: 70, state: st };
        return r === "done" ? done(on ? "Rescue mode is ready" : "Booted back from disk") : fail("Boot failed", "The machine did not confirm the boot. Our team has been told.");
      }
      const bootId = await bootIdFor(client, base, on ? "rescue" : "harddisk");
      if (!bootId) return fail("Not available", on ? "Rescue mode is not available for this machine." : "No disk boot option found.");
      if (job.dryRun) return dry(on ? "set boot to rescue and restart" : "set boot to disk and restart");
      const body: Record<string, unknown> = { bootId };
      if (on && typeof p.sshKey === "string" && p.sshKey) body.rescueSshKey = p.sshKey;
      const w1 = await client.write({ action: on ? "dedicated.rescue.on" : "dedicated.rescue.off", method: "PUT", path: base, body, target: sn, dangerous: true });
      if (!w1.ok) return fail("Boot change failed", w1.error);
      const w2 = await client.write({ action: "dedicated.reboot", method: "POST", path: `${base}/reboot`, target: sn, dangerous: true });
      if (!w2.ok) return fail("Restart failed", w2.error);
      return { status: "WAITING", step: on ? "Booting the rescue system" : "Booting from disk", progress: 40, state: { phase: "wait", taskId: taskIdOf(w2.response) } };
    }

    /* ---------------- reinstall / handover ---------------- */
    case "REINSTALL":
    case "HANDOVER": {
      const handover = job.kind === "HANDOVER";
      if (st.phase === "wait") {
        const status = await client.get(`${base}/install/status`).catch(() => null);
        const steps: any[] = Array.isArray(status?.progress) ? status.progress : [];
        const doneSteps = steps.filter((s) => s?.status === "done").length;
        const errored = steps.find((s) => s?.status === "error");
        if (errored) return fail("Install failed", "The operating system install did not complete. Our team has been told.");
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "error") return fail("Install failed", "The operating system install did not complete. Our team has been told.");
        if (r === "running" || (steps.length > 0 && doneSteps < steps.length && !status?.done)) {
          const pct = steps.length ? Math.min(95, 20 + Math.round((doneSteps / steps.length) * 75)) : 50;
          const current = steps.find((s) => s?.status === "doing");
          return { status: "WAITING", step: current?.comment ? `Installing: ${String(current.comment).slice(0, 80)}` : "Installing the operating system", progress: pct, state: st };
