        if (!handover) return done(`${st.osLabel ?? "Operating system"} installed`, { server: { os: st.osLabel, hostname: st.hostname } });
        const cidrs = await serverCidrs(client, base).catch(() => [] as string[]);
        return done("Installed and handed over", {
          server: {
            status: "ACTIVE",
            provisionedAt: true,
            os: st.osLabel,
            hostname: st.hostname,
            credentialsUser: "root",
            ...(server.ipv4.length ? {} : { ipv4: cidrs.filter((c) => !c.includes(":")).map((c) => c.replace(/\/32$/, "")), ipv6: cidrs.filter((c) => c.includes(":")) }),
          },
          notifyReady: true,
        });
      }
      const compat = await client.get(`${base}/install/compatibleTemplates`);
      const names: string[] = [...(Array.isArray(compat?.ovh) ? compat.ovh : []), ...(Array.isArray(compat?.personal) ? compat.personal : [])].filter((x: unknown): x is string => typeof x === "string");
      const templates = offerableTemplates(names);
      const tpl = handover ? templateForOsLabel(String(p.osLabel ?? ""), templates) : templates.find((t) => t.name === p.templateName) ?? null;
      if (!tpl) return fail("Not available", handover ? `No install image matches "${p.osLabel}" on this machine. Pick another OS with the customer.` : "That operating system is not available for this machine.");
      if (typeof p.sshKey !== "string" || !p.sshKey) return fail("Missing key", "An SSH key is required so only you can log in.");
      if (typeof p.hostname !== "string" || !p.hostname) return fail("Missing hostname", "A hostname is required.");
      if (job.dryRun) return dry(`reinstall ${tpl.label} as ${p.hostname}`);
      const w = await client.write({
        action: handover ? "dedicated.handover.install" : "dedicated.reinstall",
        method: "POST",
        path: `${base}/reinstall`,
        body: { operatingSystem: tpl.name, customizations: { hostname: p.hostname, sshKey: p.sshKey } },
        target: sn,
        dangerous: true,
      });
      if (!w.ok) return fail("Install failed to start", w.error);
      return { status: "WAITING", step: "Installing the operating system", progress: 15, state: { phase: "wait", taskId: taskIdOf(w.response), osLabel: tpl.label, hostname: p.hostname } };
    }

    /* ---------------- reverse DNS ---------------- */
    case "REVERSE_SET": {
      const ip = String(p.ip ?? "");
      const block = ipBelongs(ip, await serverCidrs(client, base));
      if (!block) return fail("Refused", "That address does not belong to this server.");
      if (job.dryRun) return dry(`set reverse DNS of ${ip} to ${p.reverse}`);
      const w = await client.write({ action: "dedicated.reverse.set", method: "POST", path: `/ip/${enc(block)}/reverse`, body: { ipReverse: ip, reverse: p.reverse }, target: ip });
      return w.ok ? done(`Reverse DNS for ${ip} set`) : fail("Reverse DNS failed", w.error);
