    case "FW_ENABLE":
    case "FW_DISABLE":
    case "FW_RULE_ADD":
    case "FW_RULE_REMOVE": {
      const ip = String(p.ip ?? "");
      if (ip.includes(":")) return fail("Refused", "The network firewall covers IPv4 addresses.");
      const block = ipBelongs(ip, await serverCidrs(client, base));
      if (!block) return fail("Refused", "That address does not belong to this server.");
      const fwBase = `/ip/${enc(block)}/firewall`;
      const exists = await client.get(`${fwBase}/${enc(ip)}`).then(() => true).catch(() => false);
