/**
 * Order extra IPs upstream for THIS server (cart -> service option -> required
 * configuration -> checkout -> wait for delivery -> read the new block), then
 * add the monthly price to the server's renewal. Only ever reached after an
 * ADMIN approved a paid DedicatedIpOrder.
 */
async function ipOrderStep(job: JobInput, server: ServerInput, deps: StepDeps, base: string, sn: string): Promise<StepResult> {
  const { client } = deps;
  const p = job.payload ?? {};
  const st = job.state ?? {};
  const qty = Number(p.quantity) as ExtraIpSize;
  const prefix = prefixForSize(qty);
  const monthlyAdd = Math.max(0, Math.round(Number(p.unitMonthlyCents) * qty));

  if (st.phase === "wait") {
    const status = await client.get(`/me/order/${st.orderId}/status`).catch(() => null);
    if (status === "delivered" || status === "delivering") {
      const now = await serverCidrs(client, base).catch(() => [] as string[]);
      const fresh = now.filter((c) => !(st.before ?? []).includes(c) && !c.includes(":"));
      if (!fresh.length) return { status: "WAITING", step: "Waiting for the new addresses to route", progress: 85, state: st };
      return done(`${qty === 1 ? "Extra IP" : `/${prefix} block`} added`, {
        server: { ipv4: [...server.ipv4, ...fresh.map((c) => c.replace(/\/32$/, ""))], renewalAddMonthlyCents: monthlyAdd, extraIpAddMonthlyCents: monthlyAdd },
        ipOrder: { status: "DONE", ips: fresh },
      });
    }
    if (status === "cancelled" || status === "cancelling") return fail("Order cancelled", "The address order was cancelled upstream. Our team will refund or retry.", { ipOrder: { status: "FAILED" } });
    return { status: "WAITING", step: "Waiting for the addresses to be delivered", progress: 70, state: st };
  }

  // Find the option for this size before spending anything.
  const options = await client.get(`/order/cartServiceOption/baremetalServers/${enc(sn)}`);
  const list: any[] = Array.isArray(options) ? options : [];
  const opt = list.find((o) => /ip/i.test(String(o?.family ?? "")) && new RegExp(`(^|-)s?${prefix}(-|$)|/${prefix}\\b|-${qty}ip`, "i").test(String(o?.planCode ?? "")));
  if (!opt) return fail("Not available", `No ${qty === 1 ? "single IP" : `/${prefix} block`} is offered for this machine's location.`, { ipOrder: { status: "FAILED" } });
  const price = Array.isArray(opt.prices) ? opt.prices.find((x: any) => /P1M/.test(String(x?.duration ?? ""))) ?? opt.prices[0] : null;
  if (job.dryRun) return { ...dry(`order ${opt.planCode} for this server`), effects: { ipOrder: { status: "FAILED" } }, step: `Dry run: would order ${opt.planCode}. Nothing was bought; the order stays open for a real run.` };

  const before = await serverCidrs(client, base);
  const cart = await client.write({ action: "dedicated.ip.cart", method: "POST", path: "/order/cart", body: { ovhSubsidiary: deps.ovhSubsidiary ?? "WE", description: `nxeon-ip-${job.id}` }, target: sn });
  if (!cart.ok) return fail("Order failed", cart.error, { ipOrder: { status: "FAILED" } });
  const cartId = String(cart.response?.cartId ?? "");
  if (!cartId) return fail("Order failed", "No cart id returned.", { ipOrder: { status: "FAILED" } });
  const asg = await client.write({ action: "dedicated.ip.cart.assign", method: "POST", path: `/order/cart/${enc(cartId)}/assign`, target: sn });
  if (!asg.ok) return fail("Order failed", asg.error, { ipOrder: { status: "FAILED" } });
  const item = await client.write({
    action: "dedicated.ip.cart.item",
    method: "POST",
    path: `/order/cartServiceOption/baremetalServers/${enc(sn)}`,
    body: { cartId, planCode: opt.planCode, duration: price?.duration ?? "P1M", pricingMode: price?.pricingMode ?? "default", quantity: 1 },
    target: sn,
  });
  if (!item.ok) return fail("Order failed", item.error, { ipOrder: { status: "FAILED" } });
  const itemId = item.response?.itemId;
  const req = await client.get(`/order/cart/${enc(cartId)}/item/${itemId}/requiredConfiguration`).catch(() => []);
  for (const rc of Array.isArray(req) ? req : []) {
    const label = String(rc?.label ?? "");
    const value = label === "destination" ? sn : label === "country" ? String(p.country ?? "").toUpperCase() : null;
    if (!value) {
      if (rc?.required) return fail("Order failed", `Missing order detail "${label}".`, { ipOrder: { status: "FAILED" } });
      continue;
    }
    const c = await client.write({ action: "dedicated.ip.cart.config", method: "POST", path: `/order/cart/${enc(cartId)}/item/${itemId}/configuration`, body: { label, value }, target: sn });
    if (!c.ok) return fail("Order failed", c.error, { ipOrder: { status: "FAILED" } });
  }
  const co = await client.write({ action: "dedicated.ip.checkout", method: "POST", path: `/order/cart/${enc(cartId)}/checkout`, body: { autoPayWithPreferredPaymentMethod: true, waiveRetractationPeriod: true }, target: sn, dangerous: true });
  if (!co.ok) return fail("Order failed", co.error, { ipOrder: { status: "FAILED" } });
  return { status: "WAITING", step: "Waiting for the addresses to be delivered", progress: 55, state: { phase: "wait", orderId: co.response?.orderId, before }, effects: { ipOrder: { status: "ORDERING" } } };
}

