  const g = guardJob(job, server, deps.protectedServiceNames);
  if (g) return fail("Refused", g, job.kind === "IP_ORDER" ? { ipOrder: { status: "FAILED" } } : undefined);
  const { client } = deps;
  const sn = server.serviceName!.trim();
  const base = `/dedicated/server/${enc(sn)}`;
  const st = job.state ?? {};
  const p = job.payload ?? {};

  switch (job.kind) {
    /* ---------------- power ---------------- */
    case "REBOOT_HARD": {
      if (st.phase === "wait") {
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "running") return { status: "WAITING", step: "Restarting the machine", progress: 60, state: st };
        return r === "done" ? done("Restarted") : fail("Reboot failed", "The machine did not confirm the restart. Our team has been told.");
      }
      if (job.dryRun) return dry("a hard reboot");
      const w = await client.write({ action: "dedicated.reboot", method: "POST", path: `${base}/reboot`, target: sn, dangerous: true });
      if (!w.ok) return fail("Reboot failed", w.error);
      return { status: "WAITING", step: "Restarting the machine", progress: 30, state: { phase: "wait", taskId: taskIdOf(w.response) } };
    }

    /* ---------------- rescue ---------------- */
    case "RESCUE_ON":
    case "RESCUE_OFF": {
      const on = job.kind === "RESCUE_ON";
      if (st.phase === "wait") {
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "running") return { status: "WAITING", step: on ? "Booting the rescue system" : "Booting from disk", progress: 70, state: st };
        return r === "done" ? done(on ? "Rescue mode is ready" : "Booted back from disk") : fail("Boot failed", "The machine did not confirm the boot. Our team has been told.");
      }
      const bootId = await bootIdFor(client, base, on ? "rescue" : "harddisk");
      if (!bootId) return fail("Not available", on ? "Rescue mode is not available for this machine." : "No disk boot option found.");
      if (job.dryRun) return dry(on ? "set boot to rescue and restart" : "set boot to disk and restart");
      const body: Record<string, unknown> = { bootId };
      if (on && typeof p.sshKey === "string" && p.sshKey) body.rescueSshKey = p.sshKey;
      const w1 = await client.write({ action: on ? "dedicated.rescue.on" : "dedicated.rescue.off", method: "PUT", path: base, body, target: sn, dangerous: true });
      if (!w1.ok) return fail("Boot change failed", w1.error);
      const w2 = await client.write({ action: "dedicated.reboot", method: "POST", path: `${base}/reboot`, target: sn, dangerous: true });
      if (!w2.ok) return fail("Restart failed", w2.error);
      return { status: "WAITING", step: on ? "Booting the rescue system" : "Booting from disk", progress: 40, state: { phase: "wait", taskId: taskIdOf(w2.response) } };
    }

    /* ---------------- reinstall / handover ---------------- */
    case "REINSTALL":
    case "HANDOVER": {
      const handover = job.kind === "HANDOVER";
      if (st.phase === "wait") {
        const status = await client.get(`${base}/install/status`).catch(() => null);
        const steps: any[] = Array.isArray(status?.progress) ? status.progress : [];
        const doneSteps = steps.filter((s) => s?.status === "done").length;
        const errored = steps.find((s) => s?.status === "error");
        if (errored) return fail("Install failed", "The operating system install did not complete. Our team has been told.");
        const r = await pollTask(client, base, st.taskId ?? null);
        if (r === "error") return fail("Install failed", "The operating system install did not complete. Our team has been told.");
        if (r === "running" || (steps.length > 0 && doneSteps < steps.length && !status?.done)) {
          const pct = steps.length ? Math.min(95, 20 + Math.round((doneSteps / steps.length) * 75)) : 50;
          const current = steps.find((s) => s?.status === "doing");
          return { status: "WAITING", step: current?.comment ? `Installing: ${String(current.comment).slice(0, 80)}` : "Installing the operating system", progress: pct, state: st };
        }
        if (!handover) return done(`${st.osLabel ?? "Operating system"} installed`, { server: { os: st.osLabel, hostname: st.hostname } });
        const cidrs = await serverCidrs(client, base).catch(() => [] as string[]);
        return done("Installed and handed over", {
          server: {
            status: "ACTIVE",
            provisionedAt: true,
            os: st.osLabel,
            hostname: st.hostname,
            credentialsUser: "root",
            ...(server.ipv4.length ? {} : { ipv4: cidrs.filter((c) => !c.includes(":")).map((c) => c.replace(/\/32$/, "")), ipv6: cidrs.filter((c) => c.includes(":")) }),
          },
          notifyReady: true,
        });
      }
      const compat = await client.get(`${base}/install/compatibleTemplates`);
      const names: string[] = [...(Array.isArray(compat?.ovh) ? compat.ovh : []), ...(Array.isArray(compat?.personal) ? compat.personal : [])].filter((x: unknown): x is string => typeof x === "string");
      const templates = offerableTemplates(names);
      const tpl = handover ? templateForOsLabel(String(p.osLabel ?? ""), templates) : templates.find((t) => t.name === p.templateName) ?? null;
      if (!tpl) return fail("Not available", handover ? `No install image matches "${p.osLabel}" on this machine. Pick another OS with the customer.` : "That operating system is not available for this machine.");
      if (typeof p.sshKey !== "string" || !p.sshKey) return fail("Missing key", "An SSH key is required so only you can log in.");
      if (typeof p.hostname !== "string" || !p.hostname) return fail("Missing hostname", "A hostname is required.");
      if (job.dryRun) return dry(`reinstall ${tpl.label} as ${p.hostname}`);
      const w = await client.write({
        action: handover ? "dedicated.handover.install" : "dedicated.reinstall",
        method: "POST",
        path: `${base}/reinstall`,
        body: { operatingSystem: tpl.name, customizations: { hostname: p.hostname, sshKey: p.sshKey } },
        target: sn,
        dangerous: true,
      });
      if (!w.ok) return fail("Install failed to start", w.error);
      return { status: "WAITING", step: "Installing the operating system", progress: 15, state: { phase: "wait", taskId: taskIdOf(w.response), osLabel: tpl.label, hostname: p.hostname } };
    }

    /* ---------------- reverse DNS ---------------- */
    case "REVERSE_SET": {
      const ip = String(p.ip ?? "");
      const block = ipBelongs(ip, await serverCidrs(client, base));
      if (!block) return fail("Refused", "That address does not belong to this server.");
      if (job.dryRun) return dry(`set reverse DNS of ${ip} to ${p.reverse}`);
      const w = await client.write({ action: "dedicated.reverse.set", method: "POST", path: `/ip/${enc(block)}/reverse`, body: { ipReverse: ip, reverse: p.reverse }, target: ip });
      return w.ok ? done(`Reverse DNS for ${ip} set`) : fail("Reverse DNS failed", w.error);
    }

    /* ---------------- firewall ---------------- */
    case "FW_ENABLE":
    case "FW_DISABLE":
    case "FW_RULE_ADD":
    case "FW_RULE_REMOVE": {
      const ip = String(p.ip ?? "");
      if (ip.includes(":")) return fail("Refused", "The network firewall covers IPv4 addresses.");
      const block = ipBelongs(ip, await serverCidrs(client, base));
      if (!block) return fail("Refused", "That address does not belong to this server.");
      const fwBase = `/ip/${enc(block)}/firewall`;
      const exists = await client.get(`${fwBase}/${enc(ip)}`).then(() => true).catch(() => false);
      if (job.dryRun) return dry(`${job.kind.toLowerCase().replace(/_/g, " ")} on ${ip}`);
      if (!exists) {
        if (job.kind === "FW_DISABLE" || job.kind === "FW_RULE_REMOVE") return done("Nothing to change");
        const a = await client.write({ action: "dedicated.fw.add_ip", method: "POST", path: fwBase, body: { ipOnFirewall: ip }, target: ip });
        if (!a.ok) return fail("Firewall failed", a.error);
      }
      if (job.kind === "FW_ENABLE" || job.kind === "FW_DISABLE") {
        const w = await client.write({ action: "dedicated.fw.enabled", method: "PUT", path: `${fwBase}/${enc(ip)}`, body: { enabled: job.kind === "FW_ENABLE" }, target: ip });
        return w.ok ? done(job.kind === "FW_ENABLE" ? `Firewall on for ${ip}` : `Firewall off for ${ip}`) : fail("Firewall failed", w.error);
      }
      if (job.kind === "FW_RULE_ADD") {
        const w = await client.write({ action: "dedicated.fw.rule.add", method: "POST", path: `${fwBase}/${enc(ip)}/rule`, body: networkRuleBody(p.rule as NetworkRuleInput), target: ip });
        return w.ok ? done(`Rule ${p.rule?.sequence} added on ${ip}`) : fail("Firewall failed", w.error);
      }
      const w = await client.write({ action: "dedicated.fw.rule.remove", method: "DELETE", path: `${fwBase}/${enc(ip)}/rule/${Number(p.sequence)}`, target: ip });
      return w.ok ? done(`Rule ${p.sequence} removed on ${ip}`) : fail("Firewall failed", w.error);
    }

    /* ---------------- extra IPs (admin-approved purchase) ---------------- */
    case "IP_ORDER":
      return ipOrderStep(job, server, deps, base, sn);
  }
  return fail("Unknown action", `Unknown job kind ${job.kind}`);
}

/**
 * Order extra IPs upstream for THIS server (cart -> service option -> required
 * configuration -> checkout -> wait for delivery -> read the new block), then
 * add the monthly price to the server's renewal. Only ever reached after an
 * ADMIN approved a paid DedicatedIpOrder.
 */
async function ipOrderStep(job: JobInput, server: ServerInput, deps: StepDeps, base: string, sn: string): Promise<StepResult> {
  const { client } = deps;
  const p = job.payload ?? {};
  const st = job.state ?? {};
  const qty = Number(p.quantity) as ExtraIpSize;
  const prefix = prefixForSize(qty);
  const monthlyAdd = Math.max(0, Math.round(Number(p.unitMonthlyCents) * qty));

  if (st.phase === "wait") {
    const status = await client.get(`/me/order/${st.orderId}/status`).catch(() => null);
    if (status === "delivered" || status === "delivering") {
      const now = await serverCidrs(client, base).catch(() => [] as string[]);
      const fresh = now.filter((c) => !(st.before ?? []).includes(c) && !c.includes(":"));
      if (!fresh.length) return { status: "WAITING", step: "Waiting for the new addresses to route", progress: 85, state: st };
      return done(`${qty === 1 ? "Extra IP" : `/${prefix} block`} added`, {
        server: { ipv4: [...server.ipv4, ...fresh.map((c) => c.replace(/\/32$/, ""))], renewalAddMonthlyCents: monthlyAdd, extraIpAddMonthlyCents: monthlyAdd },
        ipOrder: { status: "DONE", ips: fresh },
      });
    }
    if (status === "cancelled" || status === "cancelling") return fail("Order cancelled", "The address order was cancelled upstream. Our team will refund or retry.", { ipOrder: { status: "FAILED" } });
    return { status: "WAITING", step: "Waiting for the addresses to be delivered", progress: 70, state: st };
  }

  // Find the option for this size before spending anything.
  const options = await client.get(`/order/cartServiceOption/baremetalServers/${enc(sn)}`);
  const list: any[] = Array.isArray(options) ? options : [];
  const opt = list.find((o) => /ip/i.test(String(o?.family ?? "")) && new RegExp(`(^|-)s?${prefix}(-|$)|/${prefix}\\b|-${qty}ip`, "i").test(String(o?.planCode ?? "")));
  if (!opt) return fail("Not available", `No ${qty === 1 ? "single IP" : `/${prefix} block`} is offered for this machine's location.`, { ipOrder: { status: "FAILED" } });
  const price = Array.isArray(opt.prices) ? opt.prices.find((x: any) => /P1M/.test(String(x?.duration ?? ""))) ?? opt.prices[0] : null;
  if (job.dryRun) return { ...dry(`order ${opt.planCode} for this server`), effects: { ipOrder: { status: "FAILED" } }, step: `Dry run: would order ${opt.planCode}. Nothing was bought; the order stays open for a real run.` };

  const before = await serverCidrs(client, base);
  const cart = await client.write({ action: "dedicated.ip.cart", method: "POST", path: "/order/cart", body: { ovhSubsidiary: deps.ovhSubsidiary ?? "WE", description: `nxeon-ip-${job.id}` }, target: sn });
  if (!cart.ok) return fail("Order failed", cart.error, { ipOrder: { status: "FAILED" } });
  const cartId = String(cart.response?.cartId ?? "");
  if (!cartId) return fail("Order failed", "No cart id returned.", { ipOrder: { status: "FAILED" } });
  const asg = await client.write({ action: "dedicated.ip.cart.assign", method: "POST", path: `/order/cart/${enc(cartId)}/assign`, target: sn });
  if (!asg.ok) return fail("Order failed", asg.error, { ipOrder: { status: "FAILED" } });
  const item = await client.write({
    action: "dedicated.ip.cart.item",
    method: "POST",
    path: `/order/cartServiceOption/baremetalServers/${enc(sn)}`,
    body: { cartId, planCode: opt.planCode, duration: price?.duration ?? "P1M", pricingMode: price?.pricingMode ?? "default", quantity: 1 },
    target: sn,
  });
  if (!item.ok) return fail("Order failed", item.error, { ipOrder: { status: "FAILED" } });
  const itemId = item.response?.itemId;
  const req = await client.get(`/order/cart/${enc(cartId)}/item/${itemId}/requiredConfiguration`).catch(() => []);
  for (const rc of Array.isArray(req) ? req : []) {
    const label = String(rc?.label ?? "");
    const value = label === "destination" ? sn : label === "country" ? String(p.country ?? "").toUpperCase() : null;
    if (!value) {
      if (rc?.required) return fail("Order failed", `Missing order detail "${label}".`, { ipOrder: { status: "FAILED" } });
      continue;
    }
    const c = await client.write({ action: "dedicated.ip.cart.config", method: "POST", path: `/order/cart/${enc(cartId)}/item/${itemId}/configuration`, body: { label, value }, target: sn });
    if (!c.ok) return fail("Order failed", c.error, { ipOrder: { status: "FAILED" } });
  }
  const co = await client.write({ action: "dedicated.ip.checkout", method: "POST", path: `/order/cart/${enc(cartId)}/checkout`, body: { autoPayWithPreferredPaymentMethod: true, waiveRetractationPeriod: true }, target: sn, dangerous: true });
  if (!co.ok) return fail("Order failed", co.error, { ipOrder: { status: "FAILED" } });
  return { status: "WAITING", step: "Waiting for the addresses to be delivered", progress: 55, state: { phase: "wait", orderId: co.response?.orderId, before }, effects: { ipOrder: { status: "ORDERING" } } };
}

