/**
 * A FAKE upstream for dedicated-server Phase 2 — used by unit tests and by the
 * demo (env NXEON_DEDICATED_OVH_MOCK=1 on a NON-production process). It models
 * the handful of endpoints lib/dedicated/ops.ts and live.ts touch, with tasks
 * that complete a few seconds after they start, and records every write.
 *
 * State is kept in memory (tests) or in a JSON file shared by the web process
 * and the worker (demo; NXEON_DEDICATED_OVH_MOCK_FILE, default in os.tmpdir()).
 * It is never used when NODE_ENV=production.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

export const DEDICATED_OVH_MOCK = process.env.NXEON_DEDICATED_OVH_MOCK === "1" && process.env.NODE_ENV !== "production";

type Rule = { sequence: number; action: string; protocol: string; destinationPort?: string | null; source?: string | null; state: string };
type Srv = {
  bootId: number;
  powerState: string;
  tasks: Record<string, { fn: string; startedAt: number; ms: number }>;
  install: { startedAt: number; template: string } | null;
  ips: string[];
  reverse: Record<string, string>;
  firewall: Record<string, { enabled: boolean; rules: Record<string, Rule> }>;
};
type MockState = { servers: Record<string, Srv>; nextTask: number; orders: Record<string, { at: number; sn: string; block: string }>; carts: Record<string, { items: Record<string, string> }>; writes: { method: string; path: string; body?: unknown; at: number }[] };

const file = () => process.env.NXEON_DEDICATED_OVH_MOCK_FILE || path.join(tmpdir(), "nxeon-dedicated-ovh-mock.json");

export class MockOvh {
  private mem: MockState | null = null;
  constructor(private persist: boolean, private now: () => number = Date.now, private taskMs = 6_000) {}

  private load(): MockState {
    if (!this.persist) return (this.mem ??= { servers: {}, nextTask: 1000, orders: {}, carts: {}, writes: [] });
    try {
      return JSON.parse(readFileSync(file(), "utf8")) as MockState;
    } catch {
      return { servers: {}, nextTask: 1000, orders: {}, carts: {}, writes: [] };
    }
  }
  private save(s: MockState) {
    if (this.persist) writeFileSync(file(), JSON.stringify(s));
    else this.mem = s;
  }

  /** Create a fake machine for a service name (idempotent). */
  seed(sn: string, ips: string[] = ["203.0.113.40/32", "2001:db8:40::/64"]) {
    const s = this.load();
    s.servers[sn] ??= { bootId: 1, powerState: "poweron", tasks: {}, install: null, ips, reverse: {}, firewall: {} };
    this.save(s);
  }

  writes() {
    return this.load().writes;
  }

