/**
 * READ-ONLY live view of a delivered dedicated server (Phase 2): power, boot
 * mode, hardware, network, its IP blocks with reverse DNS and firewall, and the
 * install images it supports. GETs only, through an injectable getter:
 * the real upstream client in production, the demo mock (lib/dedicated/ovh-mock)
 * when NXEON_DEDICATED_OVH_MOCK=1 on a non-production process.
 *
 * Returns a BRAND-SAFE projection: no upstream names, datacenter codes,
 * service names or template ids beyond the opaque install-image value.
 */
import { adminOvhGet } from "../ovh-admin/transport";
import { ovhAdminConfigured } from "../ovh-admin/transport";
import { readNetwork, readReverse } from "../ovh-admin/read";
import { parseNetworkSpec, parseServer } from "../ovh-admin/parse";
import { DEDICATED_OVH_MOCK, demoMock } from "./ovh-mock";
import { ipBelongs, offerableTemplates, type TemplateOption } from "./ops-core";

export type Getter = (path: string) => Promise<any>;

export function dedicatedGetter(): Getter | null {
  if (DEDICATED_OVH_MOCK) return (p) => demoMock().get(p);
  if (!ovhAdminConfigured()) return null;
  return adminOvhGet;
}

export type LiveFirewallRule = { sequence: number | null; action: string | null; protocol: string | null; port: string | null; source: string | null };
export type LiveIp = { ip: string; cidr: string; version: 4 | 6; reverse: string | null; firewall: { exists: boolean; enabled: boolean | null; rules: LiveFirewallRule[] } | null };

export type DedicatedLive = {
  ok: true;
  power: "on" | "off" | "unknown";
  bootMode: "disk" | "rescue" | "unknown";
  hardware: { cpu: string | null; cores: number | null; threads: number | null; ramGb: number | null; disks: string[] } | null;
  network: { linkMbps: number | null; inMbps: number | null; outMbps: number | null; unmetered: boolean; throttled: boolean; usedPercent: number | null; resetDate: string | null } | null;
  ips: LiveIp[];
  templates: TemplateOption[];
};

const clean = (s: unknown) => (typeof s === "string" ? s.replace(/\bovh(cloud)?\b/gi, "").replace(/\s{2,}/g, " ").trim() || null : null);

function hw(body: any): DedicatedLive["hardware"] {
  if (!body || typeof body !== "object") return null;
  const mem = body.memorySize?.value;
  const unit = String(body.memorySize?.unit ?? "MB");
  const ramGb = typeof mem === "number" ? Math.round(unit === "GB" ? mem : mem / 1024) : null;
  const n = Number(body.numberOfProcessors) || 1;
  const disks = (Array.isArray(body.diskGroups) ? body.diskGroups : []).map((d: any) => `${d?.numberOfDisks ?? "?"}x ${d?.diskSize?.value ?? "?"}${d?.diskSize?.unit ?? ""} ${clean(d?.diskType) ?? ""}`.trim());
  return { cpu: clean(body.processorName), cores: typeof body.coresPerProcessor === "number" ? body.coresPerProcessor * n : null, threads: typeof body.threadsPerProcessor === "number" ? body.threadsPerProcessor * n : null, ramGb, disks };
}

/** Everything the customer panel shows. Each section fails independently. */
export async function readDedicatedLive(serviceName: string, get: Getter, opts: { firewall?: boolean } = {}): Promise<DedicatedLive> {
  const base = `/dedicated/server/${encodeURIComponent(serviceName)}`;
  const [srvB, hwB, netB, ipsB, compatB, rescueIds] = await Promise.all([
    get(base).catch(() => null),
    get(`${base}/specifications/hardware`).catch(() => null),
    get(`${base}/specifications/network`).catch(() => null),
    get(`${base}/ips`).catch(() => []),
    get(`${base}/install/compatibleTemplates`).catch(() => null),
    get(`${base}/boot?bootType=rescue`).catch(() => []),
  ]);
  const srv = parseServer(srvB);
  const net = parseNetworkSpec(netB);
  const cidrs: string[] = Array.isArray(ipsB) ? ipsB.filter((x: unknown): x is string => typeof x === "string") : [];
  const rescue = Array.isArray(rescueIds) ? rescueIds.map(Number) : [];
  const ips: LiveIp[] = [];
  for (const c of cidrs.slice(0, 16)) {
    const v6 = c.includes(":");
    const [ip, bits] = c.split("/");
    if (!v6 && bits && bits !== "32") {
      // a block: list it once (reverse/firewall are per address; the customer picks one in the panel)
      ips.push({ ip, cidr: c, version: 4, reverse: null, firewall: null });
