/**
 * Worker sweep for dedicated-server Phase 2 jobs (DedicatedJob). The web tier
 * only enqueues; THIS is the only place an upstream write for a customer
 * dedicated server is made, always through lib/dedicated/ops.ts and, for the
 * real upstream, the single audited wrapper lib/ovh-admin/write.ts
 * (rights check, rate limits, AuditLog before + after).
 *
 * Modes, decided per job when it is claimed:
 *   - MOCK  (NXEON_DEDICATED_OVH_MOCK=1, non-production only): the fake upstream
 *           in lib/dedicated/ovh-mock.ts; full flow, nothing real is touched.
 *   - DRY   (Setting dedicated_ovh_dry_run, DEFAULT "true"): nothing is sent;
 *           the job finishes with "Dry run: ..." so the flow is demoable.
 *   - LIVE  (dedicated_ovh_dry_run=false): real upstream writes.
 *
 * Every tick: claim up to 4 jobs (QUEUED, or WAITING untouched for 10 s) with an
 * atomic status flip, run one step each, persist, apply effects. A job WAITING
 * for more than 3 hours fails ("timed out") and staff are told.
 */
import { db } from "../lib/db";
import { getSetting, getSettingBool } from "../lib/settings";
import { recordAudit } from "../lib/audit";
import { runJobStep, type OpsClient, type Effects, type JobInput } from "../lib/dedicated/ops";
import { DEDICATED_OVH_MOCK, demoMock } from "../lib/dedicated/ovh-mock";
import { JOB_LABEL, type DedicatedJobKind } from "../lib/dedicated/ops-core";

const WAIT_POLL_MS = 10_000;
const MAX_WAIT_MS = 3 * 60 * 60_000;

export type TickDeps = {
  client: (job: { userId: string; dryRun: boolean }) => OpsClient;
  notifyReady: (serverId: string) => Promise<void>;
  now: () => Date;
  dryRunDefault: () => Promise<boolean>;
  protectedNames: () => Promise<Set<string>>;
};

/** Upstream client for one job: mock, or the real audited writer. */
export function realClient(job: { userId: string }): OpsClient {
  if (DEDICATED_OVH_MOCK) {
    const m = demoMock();
    return {
      get: (p) => m.get(p),
      write: async (r) => {
        await recordAudit(job.userId, `${r.action}.mock`, `${r.method} ${r.path} target=${r.target}`);
        try {
          return { ok: true, response: await m.send(r.method, r.path, r.body) };
        } catch (e) {
          return { ok: false, error: String((e as Error)?.message ?? e) };
        }
      },
    };
  }
  return {
    get: async (p) => (await import("../lib/ovh-admin/transport")).adminOvhGet(p),
    write: async (r) => {
      const { ovhAdminWrite } = await import("../lib/ovh-admin/write");
      const { adminOvhGet } = await import("../lib/ovh-admin/transport");
      const res = await ovhAdminWrite({
        actor: { id: job.userId },
        action: r.action,
        target: r.target,
        method: r.method,
        path: r.path,
        body: r.body,
        read: async () => null,
        rateClass: r.dangerous ? "dangerous" : "normal",
      }, undefined);
      void adminOvhGet;
      return res.ok ? { ok: true, response: res.response } : { ok: false, error: res.error };
    },
  };
}

async function defaultProtectedNames(): Promise<Set<string>> {
  const nodes = await db.node.findMany({ select: { providerServerId: true, name: true } });
  const extra = (await getSetting("dedicated_ovh_protected_services", "")).split(/[,\s]+/).filter(Boolean);
  const out = new Set<string>();
  for (const n of nodes) if (n.providerServerId) { out.add(n.providerServerId); out.add(n.providerServerId.toLowerCase()); }
  for (const e of extra) { out.add(e); out.add(e.toLowerCase()); }
  return out;
}

async function defaultNotifyReady(serverId: string): Promise<void> {
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s) return;
  await db.notification.create({ data: { userId: s.userId, title: "Your dedicated server is online", body: `${s.label} is installed and ready. Its IP addresses are on the server page.`, href: `/dashboard/dedicated/${s.id}` } }).catch(() => {});
  if (DEDICATED_OVH_MOCK) return; // demo: never send real email
  const u = await db.user.findUnique({ where: { id: s.userId }, select: { email: true, name: true } });
  if (!u) return;
  const { sendMail } = await import("../lib/mailer");
  const base = process.env.APP_URL ?? "https://nxeon.cloud";
  await sendMail({ to: u.email, template: "dedicated_server_ready", userId: s.userId, vars: { name: u.name.split(" ")[0] || "there", label: s.label, ip: s.ipv4[0] ?? "", url: `${base}/dashboard/dedicated/${s.id}` } });
}

export function defaultTickDeps(): TickDeps {
  return {
    client: realClient,
    notifyReady: defaultNotifyReady,
    now: () => new Date(),
    dryRunDefault: async () => (DEDICATED_OVH_MOCK ? false : await getSettingBool("dedicated_ovh_dry_run", true)),
    protectedNames: defaultProtectedNames,
  };
}

async function applyEffects(serverId: string, e: Effects | undefined, ipOrderId: string | null) {
  if (!e) return;
  if (e.server) {
    const s = e.server;
    await db.dedicatedServer.update({
      where: { id: serverId },
      data: {
        ...(s.status ? { status: s.status } : {}),
        ...(s.provisionedAt ? { provisionedAt: new Date() } : {}),
        ...(s.ipv4 ? { ipv4: s.ipv4 } : {}),
        ...(s.ipv6 ? { ipv6: s.ipv6 } : {}),
        ...(s.hostname ? { hostname: s.hostname } : {}),
        ...(s.os ? { os: s.os } : {}),
        ...(s.credentialsUser ? { credentialsUser: s.credentialsUser } : {}),
        ...(s.renewalAddMonthlyCents ? { renewalMonthlyCents: { increment: s.renewalAddMonthlyCents } } : {}),
        ...(s.extraIpAddMonthlyCents ? { extraIpMonthlyCents: { increment: s.extraIpAddMonthlyCents } } : {}),
      },
    });
  }
  if (e.ipOrder && ipOrderId) {
    await db.dedicatedIpOrder.update({ where: { id: ipOrderId }, data: { status: e.ipOrder.status, ...(e.ipOrder.ips ? { ips: e.ipOrder.ips } : {}) } });
  }
}

/** One sweep tick. Returns how many jobs it advanced. */
export async function dedicatedJobsTick(deps: TickDeps = defaultTickDeps()): Promise<number> {
  const now = deps.now();
  // Time out stale waits first.
  const stale = await db.dedicatedJob.findMany({ where: { status: "WAITING", startedAt: { lt: new Date(now.getTime() - MAX_WAIT_MS) } }, select: { id: true, dedicatedServerId: true, kind: true, payload: true } });
  for (const j of stale) {
    await db.dedicatedJob.update({ where: { id: j.id }, data: { status: "FAILED", step: "Timed out", error: "This took far longer than expected. Our team has been told.", finishedAt: now } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: j.dedicatedServerId, action: `job_timeout_${j.kind.toLowerCase()}`, detail: j.id } }).catch(() => {});
  }
  const candidates = await db.dedicatedJob.findMany({
    where: { OR: [{ status: "QUEUED" }, { status: "WAITING", updatedAt: { lt: new Date(now.getTime() - WAIT_POLL_MS) } }] },
    orderBy: { createdAt: "asc" },
    take: 4,
  });
  if (!candidates.length) return 0;
  const protectedNames = await deps.protectedNames();
  const dryDefault = await deps.dryRunDefault();
  let n = 0;
  for (const c of candidates) {
    // atomic claim: only one worker advances a job at a time
    const claimed = await db.dedicatedJob.updateMany({ where: { id: c.id, status: c.status, updatedAt: c.updatedAt }, data: { status: "RUNNING", attempts: { increment: 1 }, ...(c.status === "QUEUED" ? { startedAt: now, dryRun: dryDefault } : {}) } });
    if (claimed.count !== 1) continue;
    const job = await db.dedicatedJob.findUniqueOrThrow({ where: { id: c.id } });
    const server = await db.dedicatedServer.findUnique({ where: { id: job.dedicatedServerId } });
    if (!server) {
      await db.dedicatedJob.update({ where: { id: job.id }, data: { status: "FAILED", step: "Refused", error: "Server not found.", finishedAt: now } });
      continue;
    }
    const input: JobInput = { id: job.id, kind: job.kind, payload: job.payload, state: job.state, dryRun: job.dryRun, userId: job.userId };
    let r;
    try {
      r = await runJobStep(input, { id: server.id, serviceName: server.providerServiceName, status: server.status, label: server.label, ipv4: server.ipv4, ipv6: server.ipv6, os: server.os }, { client: deps.client({ userId: job.userId, dryRun: job.dryRun }), protectedServiceNames: protectedNames, now: deps.now });
    } catch (e) {
      r = { status: "FAILED" as const, step: "Failed", progress: 100, error: `Unexpected error: ${String((e as Error)?.message ?? e).slice(0, 300)}` };
    }
    const ipOrderId = job.kind === "IP_ORDER" ? String((job.payload as any)?.ipOrderId ?? "") || null : null;
    await applyEffects(server.id, r.effects, ipOrderId);
    const terminal = r.status === "DONE" || r.status === "FAILED";
    await db.dedicatedJob.update({
      where: { id: job.id },
      data: { status: r.status, step: r.step.slice(0, 300), progress: Math.max(0, Math.min(100, r.progress)), ...(r.state !== undefined ? { state: r.state } : {}), error: r.error?.slice(0, 500) ?? null, ...(terminal ? { finishedAt: deps.now() } : {}) },
    });
    if (terminal) {
      await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: job.userId, action: `job_${r.status.toLowerCase()}_${job.kind.toLowerCase()}`, detail: `${job.id}${job.dryRun ? " (dry run)" : ""}: ${r.step}${r.error ? ` / ${r.error}` : ""}`.slice(0, 500) } }).catch(() => {});
      await recordAudit(job.userId, `dedicated.job.${r.status.toLowerCase()}`, `${job.id} ${job.kind} server=${server.id}${job.dryRun ? " dry" : ""} ${r.error ?? ""}`).catch(() => {});
      if (r.status === "FAILED") {
        const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
        if (admins.length) await db.notification.createMany({ data: admins.map((a) => ({ userId: a.id, title: `Dedicated action failed: ${JOB_LABEL[job.kind as DedicatedJobKind] ?? job.kind}`, body: `${server.label}: ${r.error ?? r.step}`, href: `/admin/dedicated/servers/${server.id}` })) }).catch(() => {});
      }
      if (r.effects?.notifyReady) await deps.notifyReady(server.id).catch(() => {});
    }
    n++;
  }
  return n;
}

