"use server";

/**
 * CUSTOMER Phase 2 actions on a delivered dedicated server: read the live panel,
 * ENQUEUE automated actions, buy extra IPs, reveal a stored rescue password.
 *
 * The web tier never writes upstream: every action here only validates and
 * creates a DedicatedJob; worker/dedicated-jobs.ts runs it. Each action is
 * gated (lib/dedicated/gate.ts), owner-checked against OUR DedicatedServer row
 * (the upstream service name is looked up from that row, never taken from the
 * client), blocked while impersonating, rate-limited, and audited.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { recordAudit } from "./audit";
import { decryptSecret } from "./crypto-box";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";
import { createDedicatedIpOrderPaymentSession, type CustomCheckout } from "./stripe";
import { parseNetworkRule, parseReverseHostname } from "./ovh-admin/validate";
import { dedicatedAccessFor } from "./dedicated/gate";
import { dedicatedGetter, readDedicatedLive, serverBlocks, type DedicatedLive } from "./dedicated/live";
import { DEDICATED_OVH_MOCK } from "./dedicated/ovh-mock";
import { CUSTOMER_JOB_KINDS, DISRUPTIVE_KINDS, JOB_LABEL, confirmMatches, ipBelongs, isExtraIpSize, isSshPublicKey, isTerminal, parseServerHostname, type DedicatedJobKind } from "./dedicated/ops-core";
import { IpOrderError, placeDedicatedIpOrder, quoteExtraIps, type IpQuote } from "./dedicated/ip-order";
import { getSettingBool } from "./settings";

type Fail = { ok: false; error: string };
const NF: Fail = { ok: false, error: "Not found" };

async function owned(serverId: string) {
  const user = await requireUser();
  if (!(await dedicatedAccessFor(user)).allowed) throw new Error("Not found");
  if (typeof serverId !== "string" || !/^[a-z0-9]{8,40}$/i.test(serverId)) throw new Error("Not found");
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || s.userId !== user.id) throw new Error("Not found");
  return { user, server: s };
}

export type CustomerJob = { id: string; kind: string; label: string; status: string; step: string; progress: number; error: string | null; dryRun: boolean; createdAt: string; finishedAt: string | null };
export type PanelMode = "live" | "dry" | "mock" | "unavailable";
export type DedicatedPanel = {
  ok: true;
  mode: PanelMode;
  live: DedicatedLive | null;
  liveError: string | null;
  jobs: CustomerJob[];
  sshKeys: { id: string; name: string }[];
  ipOrders: { id: string; quantity: number; status: string; chargedCents: number; ips: string[]; createdAt: string }[];
  rescueSecretStored: boolean;
};

const liveCache = new Map<string, { at: number; v: DedicatedLive }>();

function toCustomerJob(j: { id: string; kind: string; status: string; step: string; progress: number; error: string | null; dryRun: boolean; createdAt: Date; finishedAt: Date | null }): CustomerJob {
  const ipStep = j.kind === "IP_ORDER" && !isTerminal(j.status) ? "Ordering your addresses" : j.step;
  return { id: j.id, kind: j.kind, label: JOB_LABEL[j.kind as DedicatedJobKind] ?? "Action", status: j.status, step: ipStep, progress: j.progress, error: j.error, dryRun: j.dryRun, createdAt: j.createdAt.toISOString(), finishedAt: j.finishedAt?.toISOString() ?? null };
}

/** Everything the server page's live panel needs. Read-only. */
export async function loadDedicatedPanel(serverId: string, fresh = false): Promise<DedicatedPanel | Fail> {
  try {
    const { user, server } = await owned(serverId);
    const [jobs, keys, orders, dry] = await Promise.all([
      db.dedicatedJob.findMany({ where: { dedicatedServerId: server.id, kind: { not: "HANDOVER" } }, orderBy: { createdAt: "desc" }, take: 12 }),
      db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true }, orderBy: { createdAt: "asc" } }),
      db.dedicatedIpOrder.findMany({ where: { dedicatedServerId: server.id }, orderBy: { createdAt: "desc" }, take: 10 }),
      getSettingBool("dedicated_ovh_dry_run", true),
    ]);
    const get = dedicatedGetter();
    let live: DedicatedLive | null = null;
    let liveError: string | null = null;
    if (server.status === "ACTIVE" && server.providerServiceName && get) {
      const c = liveCache.get(server.id);
      if (!fresh && c && Date.now() - c.at < 20_000) live = c.v;
      else {
        try {
          live = await readDedicatedLive(server.providerServiceName, get);
          liveCache.set(server.id, { at: Date.now(), v: live });
        } catch {
          liveError = "Live status is unavailable right now.";
        }
      }
    }
    return {
      ok: true,
      mode: DEDICATED_OVH_MOCK ? "mock" : !get ? "unavailable" : dry ? "dry" : "live",
      live,
      liveError,
      jobs: jobs.map(toCustomerJob),
      sshKeys: keys,
      ipOrders: orders.map((o) => ({ id: o.id, quantity: o.quantity, status: o.status, chargedCents: o.chargedCents, ips: o.ips, createdAt: o.createdAt.toISOString() })),
      rescueSecretStored: !!server.rescueSecretEnc,
    };
  } catch {
    return NF;
  }
}

/** Progress of this server's recent jobs (polled by the panel). */
export async function pollDedicatedJobs(serverId: string): Promise<{ ok: true; jobs: CustomerJob[] } | Fail> {
  try {
    const { server } = await owned(serverId);
    const jobs = await db.dedicatedJob.findMany({ where: { dedicatedServerId: server.id, kind: { not: "HANDOVER" } }, orderBy: { createdAt: "desc" }, take: 12 });
    return { ok: true, jobs: jobs.map(toCustomerJob) };
  } catch {
    return NF;
  }
}

export type ActionInput = {
  templateName?: string;
  hostname?: string;
  sshKeyId?: string;
  confirm?: string;
  ip?: string;
  reverse?: string;
  rule?: { sequence?: string; action?: string; protocol?: string; ports?: string; source?: string };
  sequence?: string;
};

/** Validate + enqueue one automated action. Never writes upstream. */
export async function enqueueDedicatedAction(serverId: string, kind: string, input: ActionInput = {}): Promise<{ ok: true; jobId: string } | Fail> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Server actions are disabled while you are viewing this account as an admin." };
    }
    const { user, server } = await owned(serverId);
    if (!(CUSTOMER_JOB_KINDS as string[]).includes(kind)) return { ok: false, error: "Unknown action." };
    const k = kind as DedicatedJobKind;
    if (server.status !== "ACTIVE") return { ok: false, error: "This is available once the server is online." };
    if (!server.providerServiceName) return { ok: false, error: "This server is still being set up by our team." };
    const disruptive = DISRUPTIVE_KINDS.includes(k);
    if (!checkRateLimit(`ded-ops:${user.id}`, { max: 30, windowMs: 60 * 60_000 }).ok) return { ok: false, error: "Too many actions in the last hour. Please wait a little." };
    if (disruptive && !checkRateLimit(`ded-ops-d:${server.id}`, { max: 6, windowMs: 60 * 60_000 }).ok) return { ok: false, error: "This server has been restarted several times in the last hour. Please wait before trying again." };
    const active = await db.dedicatedJob.findMany({ where: { dedicatedServerId: server.id, status: { in: ["QUEUED", "RUNNING", "WAITING"] } }, select: { kind: true } });
    if (active.length >= 3) return { ok: false, error: "A few actions are still running. Wait for them to finish." };
    if (disruptive && active.some((a) => DISRUPTIVE_KINDS.includes(a.kind as DedicatedJobKind))) return { ok: false, error: "Another restart, rescue or reinstall is still in progress." };

    let payload: Record<string, unknown> = {};
    const key = async (required: boolean) => {
      if (!input.sshKeyId) {
        if (required) throw new Error("Pick one of your SSH keys. Add one in Settings first if you have none.");
        return null;
      }
      const sk = await db.sshKey.findFirst({ where: { id: String(input.sshKeyId), userId: user.id } });
      if (!sk || !isSshPublicKey(sk.publicKey)) throw new Error("That SSH key isn't valid. Pick another or re-add it in Settings.");
      return sk.publicKey.trim();
    };
    const get = dedicatedGetter();
    const blocks = async () => (get ? serverBlocks(server.providerServiceName!, get) : []);

    if (k === "REINSTALL") {
      if (!confirmMatches(server.label, input.confirm)) return { ok: false, error: `Type the server name "${server.label}" exactly to confirm. This erases every disk.` };
      const hostname = parseServerHostname(input.hostname);
      if (!hostname) return { ok: false, error: "Enter a valid hostname (letters, digits, hyphens and dots)." };
      if (!get) return { ok: false, error: "Reinstall is unavailable right now." };
      const live = await readDedicatedLive(server.providerServiceName, get, { firewall: false });
      const tpl = live.templates.find((t) => t.name === input.templateName);
      if (!tpl) return { ok: false, error: "Pick an operating system from the list." };
      payload = { templateName: tpl.name, osLabel: tpl.label, hostname, sshKey: await key(true) };
    } else if (k === "RESCUE_ON") {
      payload = { sshKey: await key(false) };
    } else if (k === "REVERSE_SET") {
      const h = parseReverseHostname(input.reverse);
      if (!h.ok) return { ok: false, error: h.error };
      const ip = String(input.ip ?? "").trim();
      if (!ipBelongs(ip, await blocks())) return { ok: false, error: "That address does not belong to this server." };
      payload = { ip, reverse: h.value };
    } else if (k === "FW_ENABLE" || k === "FW_DISABLE" || k === "FW_RULE_ADD" || k === "FW_RULE_REMOVE") {
      const ip = String(input.ip ?? "").trim();
      if (ip.includes(":") || !ipBelongs(ip, await blocks())) return { ok: false, error: "Pick one of this server's IPv4 addresses." };
      payload = { ip };
      if (k === "FW_RULE_ADD") {
        const v = parseNetworkRule(input.rule ?? {});
        if (!v.ok) return { ok: false, error: v.error };
        payload.rule = v.value;
      }
      if (k === "FW_RULE_REMOVE") {
        if (!/^\d{1,2}$/.test(String(input.sequence ?? "")) || Number(input.sequence) > 19) return { ok: false, error: "Invalid rule." };
        payload.sequence = Number(input.sequence);
      }
    }

    const job = await db.dedicatedJob.create({ data: { dedicatedServerId: server.id, userId: user.id, kind: k, payload: payload as object } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: user.id, action: `job_queued_${k.toLowerCase()}`, detail: job.id } });
    await recordAudit(user.id, `dedicated.job.queued`, `${job.id} ${k} server=${server.id}`);
    liveCache.delete(server.id);
    revalidatePath(`/dashboard/dedicated/${server.id}`);
    return { ok: true, jobId: job.id };
  } catch (e) {
    const m = e instanceof Error ? e.message : "";
    return { ok: false, error: m && m !== "UNAUTHORIZED" ? m : "Not found" };
  }
}

/** Reveal a rescue password our team stored (key-based rescue needs none). */
export async function revealDedicatedRescueSecret(serverId: string): Promise<{ ok: true; secret: string } | Fail> {
  try {
    const { user, server } = await owned(serverId);
    if (!checkRateLimit(`ded-rescue:${user.id}`, { max: 20, windowMs: 60 * 60_000 }).ok) return { ok: false, error: "Try again later." };
    if (!server.rescueSecretEnc) return { ok: false, error: "No rescue password is stored. Rescue mode uses your SSH key." };
    const secret = decryptSecret(server.rescueSecretEnc);
    if (!secret) return { ok: false, error: "Could not read the stored password. Please contact support." };
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: server.id, actorId: user.id, action: "rescue_secret_viewed" } });
    return { ok: true, secret };
  } catch {
    return NF;
  }
}

/* ---------------- extra IPs ---------------- */

export async function quoteDedicatedExtraIps(serverId: string, quantity: number, useWallet = true): Promise<{ ok: true; quote: IpQuote; walletApplied: number; cardCents: number; balanceCents: number } | Fail> {
  try {
    const { user, server } = await owned(serverId);
    const q = await quoteExtraIps(server.id, user.id, quantity);
    const sp = walletSplit({ dueCents: q.chargeCents, balanceCents: user.balanceCents, useWallet });
    return { ok: true, quote: q, walletApplied: sp.walletApplied, cardCents: sp.cardCents, balanceCents: user.balanceCents };
  } catch (e) {
    return e instanceof IpOrderError ? { ok: false, error: e.message } : NF;
  }
}

export async function payDedicatedExtraIps(serverId: string, quantity: number, orderKey: string, useWallet = true): Promise<{ ok: true; orderId: string } | { ok: true; checkout: CustomCheckout; cardCents: number } | Fail> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, server } = await owned(serverId);
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!isExtraIpSize(quantity)) return { ok: false, error: "Pick 1, 4 or 8 addresses." };
    if (typeof orderKey !== "string" || !/^[A-Za-z0-9_-]{12,64}$/.test(orderKey)) return { ok: false, error: "Refresh and try again." };
