export async function adminStartHandover(serverId: string, input: { hostname?: string; sshKeyId?: string; osLabel?: string }): Promise<R> {
  try {
    const admin = await requireAdmin();
    const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
    if (!s) return { ok: false, error: "Not found" };
    if (!s.providerServiceName) return { ok: false, error: "Set the upstream service name first (Edit record)." };
    if (s.status !== "PENDING" && s.status !== "PROVISIONING") return { ok: false, error: "Handover is for a server that is not delivered yet." };
    const node = await db.node.findFirst({ where: { providerServerId: s.providerServiceName }, select: { name: true } });
    if (node) return { ok: false, error: `Refused: ${s.providerServiceName} is platform node ${node.name}.` };
    const running = await db.dedicatedJob.count({ where: { dedicatedServerId: s.id, status: { in: ["QUEUED", "RUNNING", "WAITING"] } } });
    if (running) return { ok: false, error: "A job is already running for this server." };
    const keys = await db.sshKey.findMany({ where: { userId: s.userId }, orderBy: { createdAt: "asc" } });
    const key = input.sshKeyId ? keys.find((k) => k.id === input.sshKeyId) : keys[0];
    if (!key || !isSshPublicKey(key.publicKey)) return { ok: false, error: "The customer has no valid SSH key on their account. Ask them to add one, or deliver credentials by hand." };
    const oc = (s.orderConfig ?? {}) as { osLabel?: string };
    const osLabel = (input.osLabel || oc.osLabel || s.os || "").trim();
    if (!osLabel) return { ok: false, error: "No operating system recorded for this order." };
    const hostname = parseServerHostname(input.hostname || s.hostname || `server-${s.id.slice(-6)}`);
    if (!hostname) return { ok: false, error: "Invalid hostname." };
    const job = await db.dedicatedJob.create({ data: { dedicatedServerId: s.id, userId: admin.id, kind: "HANDOVER", payload: { osLabel, hostname, sshKey: key.publicKey.trim() } } });
    await db.dedicatedServer.update({ where: { id: s.id }, data: { status: "PROVISIONING" } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: admin.id, action: "handover_queued", detail: `${job.id} os=${osLabel} key=${key.name}` } });
    await recordAudit(admin.id, "dedicated.handover.queued", `${s.id} job=${job.id}`);
    revalidatePath(`/admin/dedicated/servers/${s.id}`);
    return { ok: true, message: `Handover queued (job ${job.id}).` };
  } catch (e) {
    return err(e);
  }
}

export async function adminStoreRescueSecret(serverId: string, secret: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const v = String(secret ?? "").trim();
    if (v.length > 200) return { ok: false, error: "Too long." };
    await db.dedicatedServer.update({ where: { id: serverId }, data: { rescueSecretEnc: v ? encryptSecret(v) : null } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: serverId, actorId: admin.id, action: v ? "rescue_secret_stored" : "rescue_secret_cleared" } });
    revalidatePath(`/admin/dedicated/servers/${serverId}`);
    return { ok: true, message: v ? "Stored (encrypted). The customer can reveal it." : "Cleared." };
  } catch (e) {
    return err(e);
  }
}

