import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { runJobStep, type JobInput, type OpsClient, type ServerInput, type StepResult } from "../lib/dedicated/ops.ts";
import { MockOvh } from "../lib/dedicated/ovh-mock.ts";
import { extraIpProrateCents, ipBelongs, offerableTemplates, parseServerHostname, templateLabel, isSshPublicKey } from "../lib/dedicated/ops-core.ts";

/**
 * Phase 2 write paths, driven against the in-memory FAKE upstream
 * (lib/dedicated/ovh-mock.ts). No real upstream call is possible here: the
 * client is the mock, and the recorded writes are asserted call by call.
 */
const ROOT = path.resolve(__dirname, "..");
const SN = "ns5550001.example";
const KEY = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGd3b0d8n4cC0f8m0v7nqv0rYw5gTqv1x2y3z4a5b6c7 me@laptop";

function setup() {
  let t = 1_000_000;
  const mock = new MockOvh(false, () => t, 5_000);
  mock.seed(SN);
  const client: OpsClient = {
    get: (p) => mock.get(p),
    write: async (r) => ({ ok: true, response: await mock.send(r.method, r.path, r.body) }),
  };
  const deps = { client, protectedServiceNames: new Set(["ns-node-1.example"]), now: () => new Date(t) };
  return { mock, deps, advance: (ms: number) => (t += ms) };
}
const server = (over: Partial<ServerInput> = {}): ServerInput => ({ id: "s1", serviceName: SN, status: "ACTIVE", label: "Prod DB", ipv4: ["203.0.113.40"], ipv6: [], os: "Ubuntu 24.04 LTS", ...over });
const job = (kind: string, payload: any = {}, over: Partial<JobInput> = {}): JobInput => ({ id: "j1", kind, payload, state: null, dryRun: false, userId: "u1", ...over });

async function runToEnd(j: JobInput, s: ServerInput, deps: any, advance: (ms: number) => void, max = 20): Promise<StepResult> {
  let state = j.state;
  for (let i = 0; i < max; i++) {
    const r = await runJobStep({ ...j, state }, s, deps);
    if (r.status !== "WAITING") return r;
    state = r.state;
    advance(3_000);
  }
  throw new Error("never finished");
}

test("protected infrastructure and malformed / unlinked servers are refused with NO write", async () => {
  const { mock, deps } = setup();
  for (const s of [server({ serviceName: "ns-node-1.example" }), server({ serviceName: null }), server({ serviceName: "../../me" })]) {
    const r = await runJobStep(job("REBOOT_HARD"), s, deps);
    assert.equal(r.status, "FAILED");
  }
  assert.equal((await runJobStep(job("REBOOT_HARD"), server({ status: "SUSPENDED" }), deps)).status, "FAILED");
  assert.equal((await runJobStep(job("HANDOVER", { osLabel: "Debian 12", hostname: "a", sshKey: KEY }), server(), deps)).status, "FAILED", "handover only before delivery");
  assert.equal(mock.writes().length, 0);
});

test("dry run sends nothing for every kind", async () => {
  const { mock, deps } = setup();
  const kinds: [string, any][] = [
    ["REBOOT_HARD", {}], ["RESCUE_ON", { sshKey: KEY }], ["RESCUE_OFF", {}],
    ["REINSTALL", { templateName: "debian12_64", hostname: "db1", sshKey: KEY }],
    ["REVERSE_SET", { ip: "203.0.113.40", reverse: "db1.example.com." }],
    ["FW_ENABLE", { ip: "203.0.113.40" }],
    ["FW_RULE_ADD", { ip: "203.0.113.40", rule: { sequence: 0, action: "permit", protocol: "tcp", destinationPort: { from: 22, to: 22 }, source: null } }],
  ];
  for (const [k, p] of kinds) {
    const r = await runJobStep(job(k, p, { dryRun: true }), server(), deps);
    assert.equal(r.status, "DONE", k);
    assert.match(r.step, /^Dry run/, k);
  }
  assert.equal(mock.writes().length, 0);
});

test("hard reboot: one POST to the server's own reboot endpoint, then waits for the task", async () => {
  const { mock, deps, advance } = setup();
  const r = await runToEnd(job("REBOOT_HARD"), server(), deps, advance);
  assert.equal(r.status, "DONE");
  assert.deepEqual(mock.writes().map((w) => `${w.method} ${w.path}`), [`POST /dedicated/server/${SN}/reboot`]);
});

test("rescue on: netboot rescue WITH the customer's key, then reboot; off: back to disk", async () => {
  const { mock, deps, advance } = setup();
  assert.equal((await runToEnd(job("RESCUE_ON", { sshKey: KEY }), server(), deps, advance)).status, "DONE");
  const w = mock.writes();
  assert.equal(w[0].method, "PUT");
  assert.deepEqual(w[0].body, { bootId: 2, rescueSshKey: KEY });
  assert.equal(w[1].path, `/dedicated/server/${SN}/reboot`);
  assert.equal((await runToEnd(job("RESCUE_OFF"), server(), deps, advance)).status, "DONE");
  assert.deepEqual(mock.writes()[2].body, { bootId: 1 }, "back to disk; no key sent");
});

test("reinstall: only a compatible, offerable image; body carries hostname + customer key only", async () => {
  const { mock, deps, advance } = setup();
  assert.equal((await runJobStep(job("REINSTALL", { templateName: "win2022-std_64", hostname: "a", sshKey: KEY }), server(), deps)).status, "FAILED", "licensed OS is not offered");
  assert.equal((await runJobStep(job("REINSTALL", { templateName: "made-up_64", hostname: "a", sshKey: KEY }), server(), deps)).status, "FAILED");
  assert.equal((await runJobStep(job("REINSTALL", { templateName: "debian12_64", hostname: "a", sshKey: "" }), server(), deps)).status, "FAILED", "no key, no install");
  assert.equal(mock.writes().length, 0);
  const steps: string[] = [];
  let st: any = null;
  for (let i = 0; i < 20; i++) {
    const r = await runJobStep(job("REINSTALL", { templateName: "debian12_64", hostname: "db1", sshKey: KEY }, { state: st }), server(), deps);
    steps.push(`${r.status}:${r.progress}`);
    if (r.status !== "WAITING") {
      assert.equal(r.status, "DONE");
      assert.equal(r.effects?.server?.os, "Debian 12");
      break;
    }
    st = r.state;
    advance(2_000);
  }
  const w = mock.writes();
  assert.equal(w.length, 1);
  assert.equal(w[0].path, `/dedicated/server/${SN}/reinstall`);
  assert.deepEqual(w[0].body, { operatingSystem: "debian12_64", customizations: { hostname: "db1", sshKey: KEY } });
  assert.ok(steps.some((s) => s.startsWith("WAITING")), "shows progress while installing");
});

test("handover: installs the ordered OS, then hands over ACTIVE with the server's IPs and notifies", async () => {
  const { deps, advance } = setup();
  const r = await runToEnd(job("HANDOVER", { osLabel: "Ubuntu 24.04 LTS", hostname: "prod-db", sshKey: KEY }), server({ status: "PROVISIONING", ipv4: [] }), deps, advance);
  assert.equal(r.status, "DONE");
  assert.equal(r.effects?.server?.status, "ACTIVE");
  assert.deepEqual(r.effects?.server?.ipv4, ["203.0.113.40"]);
  assert.equal(r.effects?.notifyReady, true);
  const bad = await runJobStep(job("HANDOVER", { osLabel: "Windows Server 2022", hostname: "x", sshKey: KEY }), server({ status: "PENDING" }), deps);
  assert.equal(bad.status, "FAILED");
});

test("reverse DNS and firewall only for the server's own addresses", async () => {
  const { mock, deps } = setup();
  assert.equal((await runJobStep(job("REVERSE_SET", { ip: "198.51.100.7", reverse: "x.example.com." }), server(), deps)).status, "FAILED");
  assert.equal((await runJobStep(job("FW_ENABLE", { ip: "198.51.100.7" }), server(), deps)).status, "FAILED");
  assert.equal(mock.writes().length, 0);
  assert.equal((await runJobStep(job("REVERSE_SET", { ip: "203.0.113.40", reverse: "db1.example.com." }), server(), deps)).status, "DONE");
  assert.equal(mock.writes()[0].path, `/ip/${encodeURIComponent("203.0.113.40/32")}/reverse`);
  assert.equal((await runJobStep(job("FW_RULE_ADD", { ip: "203.0.113.40", rule: { sequence: 0, action: "permit", protocol: "tcp", destinationPort: { from: 22, to: 22 }, source: null } }), server(), deps)).status, "DONE");
  const w = mock.writes().slice(1).map((x) => `${x.method} ${decodeURIComponent(x.path)}`);
  assert.deepEqual(w, ["POST /ip/203.0.113.40/32/firewall", "POST /ip/203.0.113.40/32/firewall/203.0.113.40/rule"]);
  assert.deepEqual(mock.writes()[2].body, { sequence: 0, action: "permit", protocol: "tcp", destinationPort: 22 });
});

test("extra IPs: cart -> option -> destination+country -> checkout, then attach + renewal add", async () => {
  const { mock, deps, advance } = setup();
  const r = await runToEnd(job("IP_ORDER", { ipOrderId: "o1", quantity: 8, unitMonthlyCents: 300, country: "sg" }), server(), deps, advance);
  assert.equal(r.status, "DONE");
  assert.equal(r.effects?.server?.renewalAddMonthlyCents, 2400);
  assert.equal(r.effects?.ipOrder?.status, "DONE");
  assert.match(r.effects!.ipOrder!.ips![0], /\/29$/);
  const w = mock.writes().map((x) => `${x.method} ${x.path.replace(/cart-\d+/, "C").replace(/item\/\d+/, "item/I")}`);
  assert.deepEqual(w, [
    "POST /order/cart",
    "POST /order/cart/C/assign",
    `POST /order/cartServiceOption/baremetalServers/${SN}`,
    "POST /order/cart/C/item/I/configuration",
    "POST /order/cart/C/item/I/configuration",
    "POST /order/cart/C/checkout",
  ]);
  const cfg = mock.writes().filter((x) => x.path.endsWith("/configuration")).map((x) => x.body);
  assert.deepEqual(cfg, [{ label: "destination", value: SN }, { label: "country", value: "SG" }]);
});

test("pure helpers: image names, hostnames, keys, IP membership, proration", () => {
  assert.equal(templateLabel("ubuntu2404-server_64"), "Ubuntu 24.04 LTS");
  assert.equal(templateLabel("ubuntu2310-server_64"), "Ubuntu 23.10");
  assert.equal(templateLabel("debian12_64"), "Debian 12");
  assert.equal(templateLabel("win2022-std_64"), null);
  assert.deepEqual(offerableTemplates(["win2022-std_64", "debian12_64", "debian12-desktop_64", "proxmox8_64"]).map((t) => t.name).sort(), ["debian12_64", "proxmox8_64"]);
  assert.equal(parseServerHostname("DB1.Example.com."), "db1.example.com");
  assert.equal(parseServerHostname("bad_host"), null);
  assert.equal(isSshPublicKey(KEY), true);
  assert.equal(isSshPublicKey("not a key"), false);
  assert.equal(ipBelongs("203.0.113.42", ["203.0.113.40/29"]), "203.0.113.40/29");
  assert.equal(ipBelongs("203.0.113.48", ["203.0.113.40/29"]), null);
  assert.equal(ipBelongs("203.0.113.40", ["203.0.113.40/32"]), "203.0.113.40/32");
  const now = new Date("2026-10-06T00:00:00Z");
  assert.equal(extraIpProrateCents({ unitMonthlyCents: 300, quantity: 4, renewalDate: new Date("2026-10-21T00:00:00Z"), termMonths: 1, now }), 600);
  assert.equal(extraIpProrateCents({ unitMonthlyCents: 300, quantity: 1, renewalDate: new Date("2027-10-06T00:00:00Z"), termMonths: 12, now }), 3600, "capped at the term");
});

test("the web tier never writes upstream: customer/admin action files only enqueue jobs", () => {
  for (const f of ["lib/actions-dedicated-ops.ts", "lib/actions-dedicated-ops-admin.ts", "lib/dedicated/live.ts", "lib/dedicated/ip-order.ts"]) {
    const src = readFileSync(path.join(ROOT, f), "utf8");
    assert.doesNotMatch(src, /ovhAdminWrite|rawOvhSend|runJobStep|\.send\(|ovh\("(POST|PUT|DELETE)"/, f);
  }
  const worker = readFileSync(path.join(ROOT, "worker/dedicated-jobs.ts"), "utf8");
  assert.match(worker, /ovhAdminWrite/, "real writes go through the single audited wrapper");
});

