  const r = await runToEnd(job("HANDOVER", { osLabel: "Ubuntu 24.04 LTS", hostname: "prod-db", sshKey: KEY }), server({ status: "PROVISIONING", ipv4: [] }), deps, advance);
  assert.equal(r.status, "DONE");
  assert.equal(r.effects?.server?.status, "ACTIVE");
  assert.deepEqual(r.effects?.server?.ipv4, ["203.0.113.40"]);
  assert.equal(r.effects?.notifyReady, true);
  const bad = await runJobStep(job("HANDOVER", { osLabel: "Windows Server 2022", hostname: "x", sshKey: KEY }), server({ status: "PENDING" }), deps);
  assert.equal(bad.status, "FAILED");
});

test("reverse DNS and firewall only for the server's own addresses", async () => {
  const { mock, deps } = setup();
  assert.equal((await runJobStep(job("REVERSE_SET", { ip: "198.51.100.7", reverse: "x.example.com." }), server(), deps)).status, "FAILED");
  assert.equal((await runJobStep(job("FW_ENABLE", { ip: "198.51.100.7" }), server(), deps)).status, "FAILED");
  assert.equal(mock.writes().length, 0);
  assert.equal((await runJobStep(job("REVERSE_SET", { ip: "203.0.113.40", reverse: "db1.example.com." }), server(), deps)).status, "DONE");
  assert.equal(mock.writes()[0].path, `/ip/${encodeURIComponent("203.0.113.40/32")}/reverse`);
  assert.equal((await runJobStep(job("FW_RULE_ADD", { ip: "203.0.113.40", rule: { sequence: 0, action: "permit", protocol: "tcp", destinationPort: { from: 22, to: 22 }, source: null } }), server(), deps)).status, "DONE");
  const w = mock.writes().slice(1).map((x) => `${x.method} ${decodeURIComponent(x.path)}`);
  assert.deepEqual(w, ["POST /ip/203.0.113.40/32/firewall", "POST /ip/203.0.113.40/32/firewall/203.0.113.40/rule"]);
  assert.deepEqual(mock.writes()[2].body, { sequence: 0, action: "permit", protocol: "tcp", destinationPort: 22 });
});

test("extra IPs: cart -> option -> destination+country -> checkout, then attach + renewal add", async () => {
  const { mock, deps, advance } = setup();
  const r = await runToEnd(job("IP_ORDER", { ipOrderId: "o1", quantity: 8, unitMonthlyCents: 300, country: "sg" }), server(), deps, advance);
  assert.equal(r.status, "DONE");
  assert.equal(r.effects?.server?.renewalAddMonthlyCents, 2400);
  assert.equal(r.effects?.ipOrder?.status, "DONE");
  assert.match(r.effects!.ipOrder!.ips![0], /\/29$/);
  const w = mock.writes().map((x) => `${x.method} ${x.path.replace(/cart-\d+/, "C").replace(/item\/\d+/, "item/I")}`);
  assert.deepEqual(w, [
    "POST /order/cart",
    "POST /order/cart/C/assign",
    `POST /order/cartServiceOption/baremetalServers/${SN}`,
    "POST /order/cart/C/item/I/configuration",
    "POST /order/cart/C/item/I/configuration",
    "POST /order/cart/C/checkout",
  ]);
  const cfg = mock.writes().filter((x) => x.path.endsWith("/configuration")).map((x) => x.body);
  assert.deepEqual(cfg, [{ label: "destination", value: SN }, { label: "country", value: "SG" }]);
});

test("pure helpers: image names, hostnames, keys, IP membership, proration", () => {
  assert.equal(templateLabel("ubuntu2404-server_64"), "Ubuntu 24.04 LTS");
  assert.equal(templateLabel("ubuntu2310-server_64"), "Ubuntu 23.10");
  assert.equal(templateLabel("debian12_64"), "Debian 12");
  assert.equal(templateLabel("win2022-std_64"), null);
  assert.deepEqual(offerableTemplates(["win2022-std_64", "debian12_64", "debian12-desktop_64", "proxmox8_64"]).map((t) => t.name).sort(), ["debian12_64", "proxmox8_64"]);
  assert.equal(parseServerHostname("DB1.Example.com."), "db1.example.com");
  assert.equal(parseServerHostname("bad_host"), null);
  assert.equal(isSshPublicKey(KEY), true);
  assert.equal(isSshPublicKey("not a key"), false);
  assert.equal(ipBelongs("203.0.113.42", ["203.0.113.40/29"]), "203.0.113.40/29");
  assert.equal(ipBelongs("203.0.113.48", ["203.0.113.40/29"]), null);
  assert.equal(ipBelongs("203.0.113.40", ["203.0.113.40/32"]), "203.0.113.40/32");
  const now = new Date("2026-10-06T00:00:00Z");
  assert.equal(extraIpProrateCents({ unitMonthlyCents: 300, quantity: 4, renewalDate: new Date("2026-10-21T00:00:00Z"), termMonths: 1, now }), 600);
  assert.equal(extraIpProrateCents({ unitMonthlyCents: 300, quantity: 1, renewalDate: new Date("2027-10-06T00:00:00Z"), termMonths: 12, now }), 3600, "capped at the term");
});

test("the web tier never writes upstream: customer/admin action files only enqueue jobs", () => {
  for (const f of ["lib/actions-dedicated-ops.ts", "lib/actions-dedicated-ops-admin.ts", "lib/dedicated/live.ts", "lib/dedicated/ip-order.ts"]) {
    const src = readFileSync(path.join(ROOT, f), "utf8");
    assert.doesNotMatch(src, /ovhAdminWrite|rawOvhSend|runJobStep|\.send\(|ovh\("(POST|PUT|DELETE)"/, f);
  }
  const worker = readFileSync(path.join(ROOT, "worker/dedicated-jobs.ts"), "utf8");
  assert.match(worker, /ovhAdminWrite/, "real writes go through the single audited wrapper");
});

