"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * dedicated server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out and this panel
 * polls its progress. Nothing here talks to an upstream API.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/nx/PageShell";
import { NxCardFields } from "@/components/nx/NxCardFields";

const usd = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
const FIELD = "h-[38px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 text-[13px] text-white outline-none placeholder:text-tx-faint focus:border-brand-400/70";

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

type Tab = "overview" | "power" | "reinstall" | "network";

export function DedicatedControlPanel({ serverId, label, primaryIp, initial }: { serverId: string; label: string; primaryIp: string | null; initial: DedicatedPanel | null }) {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [tab, setTab] = useState<Tab>("overview");
  const [msg, setMsg] = useState<{ tone: "ok" | "bad"; text: string } | null>(null);
  const [busy, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); }
  }, [serverId]);

  // Poll while something runs; refresh the live view when a job finishes.
  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run = (kind: string, input: Record<string, unknown> = {}, okText?: string) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows below." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  if (!panel) {
    return (
      <Panel title="Server controls">
        <p className="text-[12.5px] text-tx-mute">Controls are unavailable right now. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Contact support</Link> if you need anything done on this server.</p>
      </Panel>
    );
  }
  const live = panel.live;
  const tabs: { k: Tab; t: string; icon: string }[] = [
    { k: "overview", t: "Overview", icon: "activity" },
    { k: "power", t: "Power & rescue", icon: "bolt" },
    { k: "reinstall", t: "Reinstall", icon: "terminal" },
    { k: "network", t: "Network", icon: "nodes" },
  ];

  return (
    <section className="card flex min-w-0 flex-col gap-4 p-4" aria-label="Server controls">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex flex-col gap-0.5">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">Server controls</span>
          <span className="text-[11.5px] text-tx-faint">Carried out automatically, usually within a minute or two.</span>
        </span>
        {panel.mode !== "live" && (
          <span className={"chip-tone " + (panel.mode === "mock" ? "chip-violet" : "chip-amber")} title={panel.mode === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
            {panel.mode === "mock" ? "Demo machine" : panel.mode === "dry" ? "Test mode: nothing is sent" : "Unavailable"}
          </span>
        )}
      </div>

      <div className="noscroll -mx-1 flex gap-1 overflow-x-auto px-1" role="tablist">
        {tabs.map((t) => (
          <button key={t.k} type="button" role="tab" aria-selected={tab === t.k} onClick={() => setTab(t.k)} className={"chip flex-none " + (tab === t.k ? "chip-on" : "")}>
            <Icon name={t.icon} size={12} tone="inherit" />{t.t}
          </button>
        ))}
      </div>

      {msg && (
        <p role="status" className={"rounded-[10px] border px-3 py-2 text-[12.5px] " + (msg.tone === "ok" ? "border-[rgba(17,200,142,0.35)] bg-[rgba(4,40,30,0.45)] text-tx-body" : "border-[rgba(239,66,108,0.35)] bg-[rgba(60,10,26,0.45)] text-[#ffc2d1]")}>{msg.text}</p>
      )}

      {tab === "overview" && <Overview panel={panel} />}
      {tab === "power" && <Power panel={panel} busy={busy || active} run={run} serverId={serverId} primaryIp={primaryIp} />}
      {tab === "reinstall" && <Reinstall panel={panel} busy={busy || active} run={run} label={label} />}
      {tab === "network" && <Network panel={panel} busy={busy} run={run} serverId={serverId} onPaid={() => refresh(true)} />}

      <Activity jobs={jobs} />
      {!live && panel.liveError && <p className="text-[11.5px] text-tx-faint">{panel.liveError}</p>}
    </section>
  );
}

/* ---------------- overview ---------------- */

function Stat({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: string }) {
  return (
    <div className="flex min-w-0 items-start gap-2.5 rounded-[11px] border border-rim bg-surface px-3 py-2.5">
      <Icon name={icon} size={14} className="mt-[2px]" />
      <div className="min-w-0">
        <div className="nx-label uppercase">{k}</div>
        <div className="trunc text-[13px] font-bold text-white">{v}</div>
        {sub && <div className="trunc text-[11px] text-tx-faint">{sub}</div>}
      </div>
    </div>
  );
}

function Overview({ panel }: { panel: DedicatedPanel }) {
  const l = panel.live;
  if (!l) return <p className="text-[12.5px] text-tx-mute">Live status will appear here shortly.</p>;
  const net = l.network;
  return (
    <div className="flex flex-col gap-3">
      <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
        <Stat icon="bolt" k="Power" v={<span className="flex items-center gap-1.5"><span className={"h-1.5 w-1.5 rounded-full " + (l.power === "on" ? "bg-[#11c88e] shadow-[0_0_8px_rgba(17,200,142,0.9)]" : "bg-[#ef426c]")} />{l.power === "on" ? "On" : l.power === "off" ? "Off" : "Unknown"}</span>} />
        <Stat icon="database" k="Boots from" v={l.bootMode === "rescue" ? "Rescue system" : l.bootMode === "disk" ? "Disk" : "Unknown"} sub={l.bootMode === "rescue" ? "Boot back to disk when done" : undefined} />
        <Stat icon="nodes" k="Network port" v={net?.linkMbps ? (net.linkMbps >= 1000 ? `${net.linkMbps / 1000} Gbps` : `${net.linkMbps} Mbps`) : "—"} sub={net?.outMbps ? `${net.outMbps >= 1000 ? net.outMbps / 1000 + " Gbps" : net.outMbps + " Mbps"} public bandwidth` : undefined} />
        <Stat icon="linechart" k="Traffic" v={!net ? "—" : net.throttled ? "Limited" : net.unmetered ? "Unmetered" : `${net.usedPercent ?? 0}% of quota`} sub={net?.resetDate ? `Resets ${new Date(net.resetDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : undefined} />
      </div>
      {l.hardware && (
        <div className="rounded-[11px] border border-rim bg-surface px-3 py-2.5">
          <div className="nx-label uppercase">Hardware detected</div>
          <div className="mt-1 text-[12.5px] text-tx-body">
            {[l.hardware.cpu, l.hardware.cores ? `${l.hardware.cores} cores / ${l.hardware.threads ?? "?"} threads` : null, l.hardware.ramGb ? `${l.hardware.ramGb} GB RAM` : null, ...l.hardware.disks].filter(Boolean).join(" · ")}
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] text-tx-mute">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="font-semibold text-[#8dbde8] hover:text-white">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className={FIELD + " cursor-pointer"} aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

function Power({ panel, busy, run, serverId, primaryIp }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; primaryIp: string | null }) {
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="refresh" size={14} />Hard reboot</span>
        <span className="text-[11.8px] text-tx-faint">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={busy} onClick={() => { setConfirmReboot(false); run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="btn-primary btn-xs">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="btn-ghost btn-xs">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={busy} onClick={() => setConfirmReboot(true)} className="btn-ghost btn-xs w-fit">Reboot</button>
        )}
        <span className="text-[11px] text-tx-faint">A graceful restart is best done from inside the OS (<code className="font-mono">sudo reboot</code>).</span>
      </div>
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="lifebuoy" size={14} />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[11.8px] text-tx-faint">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="break-all rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">{secret}</code> : (
              <button type="button" className="btn-ghost btn-xs w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={busy} onClick={() => run("RESCUE_OFF", {}, "Booting back from disk.")} className="btn-primary btn-xs w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[11.8px] text-tx-faint">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={busy} onClick={() => run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="btn-ghost btn-xs w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] text-[#ffc2d1]">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[12px] border border-dashed border-rim-hi p-3.5 lg:col-span-2">
        <span className="flex items-center gap-2 text-[13px] font-bold text-white"><Icon name="monitor" size={14} />Remote console</span>
        <span className="text-[11.8px] text-tx-faint">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

/* ---------------- reinstall ---------------- */

function Reinstall({ panel, busy, run, label }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; label: string }) {
  const templates = panel.live?.templates ?? [];
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
  const [host, setHost] = useState("");
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [typed, setTyped] = useState("");
  const ok = !!tpl && !!host.trim() && !!keyId && typed.trim() === label;
  return (
    <div className="flex flex-col gap-3 rounded-[12px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.18)] p-3.5">
      <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="warntriangle" size={14} />Reinstall the operating system</span>
      <span className="text-[12px] text-tx-body">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-2.5 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="nx-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className={FIELD + " cursor-pointer"}>
            {templates.length === 0 && <option value="">Loading…</option>}
            {templates.map((t) => <option key={t.name} value={t.name}>{t.label}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className={FIELD} />
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="nx-label">Type <b className="text-white">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className={FIELD + " max-w-[360px]"} autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || busy} onClick={() => run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="btn-primary btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network ---------------- */

function Network({ panel, busy, run, serverId, onPaid }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; onPaid: () => void }) {
  const ips = panel.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col divide-y divide-[var(--color-rim-soft)] rounded-[12px] border border-rim bg-surface">
        {ips.length === 0 && <p className="p-3 text-[12.5px] text-tx-mute">No addresses found yet.</p>}
        {ips.map((ip) => (
          <IpRow key={ip.cidr} ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} busy={busy} run={run} />
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11px] text-tx-faint">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
      <ExtraIps panel={panel} serverId={serverId} onPaid={onPaid} />
    </div>
  );
}

function IpRow({ ip, open, onToggle, busy, run }: { ip: DedicatedPanel["live"] extends infer L ? L extends { ips: (infer I)[] } ? I : never : never; open: boolean; onToggle: () => void; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 items-center gap-2">
          <span className="trunc font-mono text-[13px] text-white">{single ? ip.ip : ip.cidr}</span>
          <span className={"chip-tone flex-none " + (ip.version === 6 ? "chip-violet" : "chip-blue")}>{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"chip-tone flex-none " + (fw.enabled ? "chip-mint" : "chip-slate")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="btn-ghost btn-xs">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] text-tx-faint">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-3 rounded-[10px] bg-well p-3">
          <div className="flex flex-col gap-1.5">
            <span className="nx-label">Reverse DNS (PTR)</span>
            <div className="flex flex-wrap gap-2">
              <input value={rev} onChange={(e) => setRev(e.target.value)} placeholder="mail.example.com" className={FIELD + " max-w-[320px] flex-1"} />
              <button type="button" disabled={busy || !rev.trim()} onClick={() => run("REVERSE_SET", { ip: ip.ip, reverse: rev }, "Saving reverse DNS.")} className="btn-ghost btn-xs">Save</button>
            </div>
            <span className="text-[11px] text-tx-faint">The hostname must already resolve to {ip.ip}.</span>
          </div>
          <div className="flex flex-col gap-1.5">
            <span className="flex items-center justify-between gap-2">
              <span className="nx-label">Network firewall</span>
              <button type="button" disabled={busy} onClick={() => run(fw?.enabled ? "FW_DISABLE" : "FW_ENABLE", { ip: ip.ip }, fw?.enabled ? "Turning the firewall off." : "Turning the firewall on.")} className="btn-ghost btn-xs">{fw?.enabled ? "Turn off" : "Turn on"}</button>
            </span>
            {fw?.rules.length ? (
              <ul className="flex flex-col gap-1">
                {fw.rules.map((r) => (
                  <li key={String(r.sequence)} className="flex items-center justify-between gap-2 rounded-[8px] border border-rim px-2.5 py-1.5 text-[12px]">
                    <span className="trunc text-tx-body"><b className="text-white">#{r.sequence}</b> {r.action} {r.protocol}{r.port ? ` ${r.port}` : ""}{r.source && r.source !== "0.0.0.0/0" ? ` from ${r.source}` : ""}</span>
                    <button type="button" disabled={busy} onClick={() => run("FW_RULE_REMOVE", { ip: ip.ip, sequence: String(r.sequence) }, "Removing the rule.")} className="flex-none text-[11px] font-semibold text-[#ffb3c4] hover:text-white">Remove</button>
                  </li>
                ))}
              </ul>
            ) : <span className="text-[11.5px] text-tx-faint">No rules yet. With the firewall on and no rules, traffic is allowed.</span>}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-6">
              <input value={rule.sequence} onChange={(e) => setRule({ ...rule, sequence: e.target.value })} className={FIELD} aria-label="Order (0-19)" placeholder="#" />
              <select value={rule.action} onChange={(e) => setRule({ ...rule, action: e.target.value })} className={FIELD} aria-label="Action"><option value="permit">Allow</option><option value="deny">Block</option></select>
              <select value={rule.protocol} onChange={(e) => setRule({ ...rule, protocol: e.target.value })} className={FIELD} aria-label="Protocol">{["tcp", "udp", "icmp", "ipv4"].map((p) => <option key={p} value={p}>{p.toUpperCase()}</option>)}</select>
              <input value={rule.ports} onChange={(e) => setRule({ ...rule, ports: e.target.value })} className={FIELD} placeholder="Port(s)" aria-label="Ports" disabled={rule.protocol !== "tcp" && rule.protocol !== "udp"} />
              <input value={rule.source} onChange={(e) => setRule({ ...rule, source: e.target.value })} className={FIELD} placeholder="From (any)" aria-label="Source" />
              <button type="button" disabled={busy} onClick={() => run("FW_RULE_ADD", { ip: ip.ip, rule: { ...rule, ports: rule.protocol === "tcp" || rule.protocol === "udp" ? rule.ports : "" } }, "Adding the rule.")} className="btn-ghost btn-xs h-[38px]">Add rule</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function ExtraIps({ panel, serverId, onPaid }: { panel: DedicatedPanel; serverId: string; onPaid: () => void }) {
  const router = useRouter();
  const [qty, setQty] = useState<1 | 4 | 8>(1);
  const [quote, setQuote] = useState<{ chargeCents: number; renewalAfter: string; monthlyCents: number; walletApplied: number; cardCents: number; balanceCents: number } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const key = useMemo(() => newKey(), []);
  const confirmRef = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const open = panel.ipOrders.find((o) => ["PAID", "APPROVED", "ORDERING"].includes(o.status));

  useEffect(() => {
    setCheckout(null);
    start(async () => {
      const r = await quoteDedicatedExtraIps(serverId, qty);
      if (r.ok) { setQuote({ ...r.quote, walletApplied: r.walletApplied, cardCents: r.cardCents, balanceCents: r.balanceCents }); setErr(null); } else setErr(r.error);
    });
  }, [qty, serverId]);

  const pay = () => start(async () => {
    setErr(null);
    const r = await payDedicatedExtraIps(serverId, qty, key, true);
    if (!r.ok) { setErr(r.error); return; }
    if ("orderId" in r) { onPaid(); router.refresh(); return; }
    setCheckout({ ...r.checkout, cardCents: r.cardCents });
  });

  const STATUS: Record<string, string> = { PAID: "Paid, awaiting our team", APPROVED: "Being ordered", ORDERING: "Being delivered", DONE: "Added", REJECTED: "Refunded", FAILED: "Delayed, our team is on it" };
  return (
    <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
      <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="plus" size={14} />Extra IPv4 addresses</span>
      {panel.ipOrders.length > 0 && (
        <ul className="flex flex-col gap-1">
          {panel.ipOrders.map((o) => (
            <li key={o.id} className="flex flex-wrap items-center justify-between gap-2 text-[12px]">
              <span className="text-tx-body">{o.quantity === 1 ? "1 address" : `${o.quantity} addresses`} · {usd(o.chargedCents)} · {when(o.createdAt)}</span>
              <span className={"chip-tone " + (o.status === "DONE" ? "chip-mint" : o.status === "REJECTED" ? "chip-slate" : "chip-violet")}>{STATUS[o.status] ?? o.status}</span>
              {o.ips.length > 0 && <span className="w-full font-mono text-[11.5px] text-tx-faint">{o.ips.join(", ")}</span>}
            </li>
          ))}
        </ul>
      )}
      {open ? (
        <span className="text-[11.8px] text-tx-faint">Your order is with our team. Addresses appear above once they are routed to this server.</span>
      ) : (
        <>
          <div className="flex flex-wrap gap-1.5">
            {([1, 4, 8] as const).map((n) => (
              <button key={n} type="button" onClick={() => setQty(n)} aria-pressed={qty === n} className={"chip " + (qty === n ? "chip-on" : "")}>{n === 1 ? "1 address" : `Block of ${n}`}</button>
            ))}
          </div>
          {quote && (
            <div className="flex flex-col gap-1 text-[12.5px]">
              <span className="flex justify-between gap-3"><span className="text-tx-mute">Today (until your renewal)</span><b className="text-white">{usd(quote.chargeCents)}</b></span>
              <span className="flex justify-between gap-3"><span className="text-tx-mute">Then your server renews at</span><b className="text-white">{quote.renewalAfter}</b></span>
              {quote.walletApplied > 0 && <span className="flex justify-between gap-3"><span className="text-tx-mute">From your wallet</span><span className="font-semibold text-mint">−{usd(quote.walletApplied)}</span></span>}
            </div>
          )}
          {checkout ? (
            <>
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={(fn) => { confirmRef.current = fn; setCanConfirm(!!fn); }} onBusy={(_b, e) => setErr(e)} />
              <button type="button" disabled={!canConfirm} onClick={() => void confirmRef.current?.()} className="btn-primary btn-sm w-fit">Pay {usd(checkout.cardCents)}</button>
            </>
          ) : (
            <button type="button" disabled={busy || !quote} onClick={pay} className="btn-primary btn-sm w-fit">{quote && quote.cardCents === 0 ? `Pay ${usd(quote.chargeCents)} from wallet` : "Continue to payment"}</button>
          )}
          <span className="text-[11px] text-tx-faint">Our team confirms availability in your location before the addresses are added. If they can&apos;t be added, the full amount goes back to your wallet.</span>
        </>
      )}
      {err && <span className="text-[11.5px] text-[#ffc2d1]">{err}</span>}
    </div>
  );
}

/* ---------------- activity ---------------- */

function Activity({ jobs }: { jobs: CustomerJob[] }) {
  if (!jobs.length) return null;
  return (
    <div className="flex flex-col gap-1.5">
      <span className="nx-label uppercase">Recent actions</span>
      <ul className="flex flex-col gap-1.5">
        {jobs.slice(0, 6).map((j) => (
          <li key={j.id} className="flex flex-col gap-1 rounded-[10px] border border-rim bg-surface px-3 py-2">
            <span className="flex flex-wrap items-center justify-between gap-2">
              <span className="text-[12.5px] font-bold text-white">{j.label}</span>
              <span className={"chip-tone " + (j.status === "DONE" ? "chip-mint" : j.status === "FAILED" ? "chip-rose" : "chip-blue")}>{JOB_STATUS_LABEL[j.status] ?? j.status}</span>
            </span>
            {!isTerminal(j.status) && <span className="block h-[4px] overflow-hidden rounded-full bg-well"><span className="block h-full rounded-full bg-[linear-gradient(90deg,#2f7eef,#6f2ee0)] transition-[width] duration-700" style={{ width: `${Math.max(6, j.progress)}%` }} /></span>}
            <span className="text-[11.3px] text-tx-faint" suppressHydrationWarning>{j.error ?? j.step} · {when(j.createdAt)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

toolu_01HRtCXgtdEswLjayF8mtPNf.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * dedicated server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out and this panel
 * polls its progress. Nothing here talks to an upstream API.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/nx/PageShell";
import { NxCardFields } from "@/components/nx/NxCardFields";

const usd = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
const FIELD = "h-[38px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 text-[13px] text-white outline-none placeholder:text-tx-faint focus:border-brand-400/70";

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

type Tab = "overview" | "power" | "reinstall" | "network";

export function DedicatedControlPanel({ serverId, label, primaryIp, initial }: { serverId: string; label: string; primaryIp: string | null; initial: DedicatedPanel | null }) {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [tab, setTab] = useState<Tab>("overview");
  const [msg, setMsg] = useState<{ tone: "ok" | "bad"; text: string } | null>(null);
  const [busy, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); }
  }, [serverId]);

  // Poll while something runs; refresh the live view when a job finishes.
  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run = (kind: string, input: Record<string, unknown> = {}, okText?: string) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows below." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  if (!panel) {
    return (
      <Panel title="Server controls">
        <p className="text-[12.5px] text-tx-mute">Controls are unavailable right now. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Contact support</Link> if you need anything done on this server.</p>
      </Panel>
    );
  }
  const live = panel.live;
  const tabs: { k: Tab; t: string; icon: string }[] = [
    { k: "overview", t: "Overview", icon: "activity" },
    { k: "power", t: "Power & rescue", icon: "bolt" },
    { k: "reinstall", t: "Reinstall", icon: "terminal" },
    { k: "network", t: "Network", icon: "nodes" },
  ];

  return (
    <section className="card flex min-w-0 flex-col gap-4 p-4" aria-label="Server controls">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex flex-col gap-0.5">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">Server controls</span>
          <span className="text-[11.5px] text-tx-faint">Carried out automatically, usually within a minute or two.</span>
        </span>
        {panel.mode !== "live" && (
          <span className={"chip-tone " + (panel.mode === "mock" ? "chip-violet" : "chip-amber")} title={panel.mode === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
            {panel.mode === "mock" ? "Demo machine" : panel.mode === "dry" ? "Test mode: nothing is sent" : "Unavailable"}
          </span>
        )}
      </div>

      <div className="noscroll -mx-1 flex gap-1 overflow-x-auto px-1" role="tablist">
        {tabs.map((t) => (
          <button key={t.k} type="button" role="tab" aria-selected={tab === t.k} onClick={() => setTab(t.k)} className={"chip flex-none " + (tab === t.k ? "chip-on" : "")}>
            <Icon name={t.icon} size={12} tone="inherit" />{t.t}
          </button>
        ))}
      </div>

      {msg && (
        <p role="status" className={"rounded-[10px] border px-3 py-2 text-[12.5px] " + (msg.tone === "ok" ? "border-[rgba(17,200,142,0.35)] bg-[rgba(4,40,30,0.45)] text-tx-body" : "border-[rgba(239,66,108,0.35)] bg-[rgba(60,10,26,0.45)] text-[#ffc2d1]")}>{msg.text}</p>
      )}

      {tab === "overview" && <Overview panel={panel} />}
      {tab === "power" && <Power panel={panel} busy={busy || active} run={run} serverId={serverId} primaryIp={primaryIp} />}
      {tab === "reinstall" && <Reinstall panel={panel} busy={busy || active} run={run} label={label} />}
      {tab === "network" && <Network panel={panel} busy={busy} run={run} serverId={serverId} onPaid={() => refresh(true)} />}

      <Activity jobs={jobs} />
      {!live && panel.liveError && <p className="text-[11.5px] text-tx-faint">{panel.liveError}</p>}
    </section>
  );
}

/* ---------------- overview ---------------- */

function Stat({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: string }) {
  return (
    <div className="flex min-w-0 items-start gap-2.5 rounded-[11px] border border-rim bg-surface px-3 py-2.5">
      <Icon name={icon} size={14} className="mt-[2px]" />
      <div className="min-w-0">
        <div className="nx-label uppercase">{k}</div>
        <div className="trunc text-[13px] font-bold text-white">{v}</div>
        {sub && <div className="trunc text-[11px] text-tx-faint">{sub}</div>}
      </div>
    </div>
  );
}

function Overview({ panel }: { panel: DedicatedPanel }) {
  const l = panel.live;
  if (!l) return <p className="text-[12.5px] text-tx-mute">Live status will appear here shortly.</p>;
  const net = l.network;
  return (
    <div className="flex flex-col gap-3">
      <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
        <Stat icon="bolt" k="Power" v={<span className="flex items-center gap-1.5"><span className={"h-1.5 w-1.5 rounded-full " + (l.power === "on" ? "bg-[#11c88e] shadow-[0_0_8px_rgba(17,200,142,0.9)]" : "bg-[#ef426c]")} />{l.power === "on" ? "On" : l.power === "off" ? "Off" : "Unknown"}</span>} />
        <Stat icon="database" k="Boots from" v={l.bootMode === "rescue" ? "Rescue system" : l.bootMode === "disk" ? "Disk" : "Unknown"} sub={l.bootMode === "rescue" ? "Boot back to disk when done" : undefined} />
        <Stat icon="nodes" k="Network port" v={net?.linkMbps ? (net.linkMbps >= 1000 ? `${net.linkMbps / 1000} Gbps` : `${net.linkMbps} Mbps`) : "—"} sub={net?.outMbps ? `${net.outMbps >= 1000 ? net.outMbps / 1000 + " Gbps" : net.outMbps + " Mbps"} public bandwidth` : undefined} />
        <Stat icon="linechart" k="Traffic" v={!net ? "—" : net.throttled ? "Limited" : net.unmetered ? "Unmetered" : `${net.usedPercent ?? 0}% of quota`} sub={net?.resetDate ? `Resets ${new Date(net.resetDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : undefined} />
      </div>
      {l.hardware && (
        <div className="rounded-[11px] border border-rim bg-surface px-3 py-2.5">
          <div className="nx-label uppercase">Hardware detected</div>
          <div className="mt-1 text-[12.5px] text-tx-body">
            {[l.hardware.cpu, l.hardware.cores ? `${l.hardware.cores} cores / ${l.hardware.threads ?? "?"} threads` : null, l.hardware.ramGb ? `${l.hardware.ramGb} GB RAM` : null, ...l.hardware.disks].filter(Boolean).join(" · ")}
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] text-tx-mute">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="font-semibold text-[#8dbde8] hover:text-white">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className={FIELD + " cursor-pointer"} aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

function Power({ panel, busy, run, serverId, primaryIp }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; primaryIp: string | null }) {
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="refresh" size={14} />Hard reboot</span>
        <span className="text-[11.8px] text-tx-faint">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={busy} onClick={() => { setConfirmReboot(false); run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="btn-primary btn-xs">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="btn-ghost btn-xs">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={busy} onClick={() => setConfirmReboot(true)} className="btn-ghost btn-xs w-fit">Reboot</button>
        )}
        <span className="text-[11px] text-tx-faint">A graceful restart is best done from inside the OS (<code className="font-mono">sudo reboot</code>).</span>
      </div>
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="lifebuoy" size={14} />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[11.8px] text-tx-faint">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="break-all rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">{secret}</code> : (
              <button type="button" className="btn-ghost btn-xs w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={busy} onClick={() => run("RESCUE_OFF", {}, "Booting back from disk.")} className="btn-primary btn-xs w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[11.8px] text-tx-faint">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={busy} onClick={() => run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="btn-ghost btn-xs w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] text-[#ffc2d1]">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[12px] border border-dashed border-rim-hi p-3.5 lg:col-span-2">
        <span className="flex items-center gap-2 text-[13px] font-bold text-white"><Icon name="monitor" size={14} />Remote console</span>
        <span className="text-[11.8px] text-tx-faint">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

/* ---------------- reinstall ---------------- */

function Reinstall({ panel, busy, run, label }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; label: string }) {
  const templates = panel.live?.templates ?? [];
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
  const [host, setHost] = useState("");
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [typed, setTyped] = useState("");
  const ok = !!tpl && !!host.trim() && !!keyId && typed.trim() === label;
  return (
    <div className="flex flex-col gap-3 rounded-[12px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.18)] p-3.5">
      <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="warntriangle" size={14} />Reinstall the operating system</span>
      <span className="text-[12px] text-tx-body">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-2.5 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="nx-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className={FIELD + " cursor-pointer"}>
            {templates.length === 0 && <option value="">Loading…</option>}
            {templates.map((t) => <option key={t.name} value={t.name}>{t.label}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className={FIELD} />
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="nx-label">Type <b className="text-white">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className={FIELD + " max-w-[360px]"} autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || busy} onClick={() => run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="btn-primary btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network ---------------- */

function Network({ panel, busy, run, serverId, onPaid }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; onPaid: () => void }) {
  const ips = panel.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col divide-y divide-[var(--color-rim-soft)] rounded-[12px] border border-rim bg-surface">
        {ips.length === 0 && <p className="p-3 text-[12.5px] text-tx-mute">No addresses found yet.</p>}
        {ips.map((ip) => (
          <IpRow key={ip.cidr} ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} busy={busy} run={run} />
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11px] text-tx-faint">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
      <ExtraIps panel={panel} serverId={serverId} onPaid={onPaid} />
    </div>
  );
}

function IpRow({ ip, open, onToggle, busy, run }: { ip: DedicatedPanel["live"] extends infer L ? L extends { ips: (infer I)[] } ? I : never : never; open: boolean; onToggle: () => void; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 items-center gap-2">
          <span className="trunc font-mono text-[13px] text-white">{single ? ip.ip : ip.cidr}</span>
          <span className={"chip-tone flex-none " + (ip.version === 6 ? "chip-violet" : "chip-blue")}>{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"chip-tone flex-none " + (fw.enabled ? "chip-mint" : "chip-slate")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="btn-ghost btn-xs">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] text-tx-faint">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-3 rounded-[10px] bg-well p-3">
          <div className="flex flex-col gap-1.5">
            <span className="nx-label">Reverse DNS (PTR)</span>
            <div className="flex flex-wrap gap-2">
              <input value={rev} onChange={(e) => setRev(e.target.value)} placeholder="mail.example.com" className={FIELD + " max-w-[320px] flex-1"} />
              <button type="button" disabled={busy || !rev.trim()} onClick={() => run("REVERSE_SET", { ip: ip.ip, reverse: rev }, "Saving reverse DNS.")} className="btn-ghost btn-xs">Save</button>
            </div>
            <span className="text-[11px] text-tx-faint">The hostname must already resolve to {ip.ip}.</span>
          </div>
          <div className="flex flex-col gap-1.5">
            <span className="flex items-center justify-between gap-2">
              <span className="nx-label">Network firewall</span>
              <button type="button" disabled={busy} onClick={() => run(fw?.enabled ? "FW_DISABLE" : "FW_ENABLE", { ip: ip.ip }, fw?.enabled ? "Turning the firewall off." : "Turning the firewall on.")} className="btn-ghost btn-xs">{fw?.enabled ? "Turn off" : "Turn on"}</button>
            </span>
            {fw?.rules.length ? (
              <ul className="flex flex-col gap-1">
                {fw.rules.map((r) => (
                  <li key={String(r.sequence)} className="flex items-center justify-between gap-2 rounded-[8px] border border-rim px-2.5 py-1.5 text-[12px]">
                    <span className="trunc text-tx-body"><b className="text-white">#{r.sequence}</b> {r.action} {r.protocol}{r.port ? ` ${r.port}` : ""}{r.source && r.source !== "0.0.0.0/0" ? ` from ${r.source}` : ""}</span>
                    <button type="button" disabled={busy} onClick={() => run("FW_RULE_REMOVE", { ip: ip.ip, sequence: String(r.sequence) }, "Removing the rule.")} className="flex-none text-[11px] font-semibold text-[#ffb3c4] hover:text-white">Remove</button>
                  </li>
                ))}
              </ul>
            ) : <span className="text-[11.5px] text-tx-faint">No rules yet. With the firewall on and no rules, traffic is allowed.</span>}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-6">
              <input value={rule.sequence} onChange={(e) => setRule({ ...rule, sequence: e.target.value })} className={FIELD} aria-label="Order (0-19)" placeholder="#" />
              <select value={rule.action} onChange={(e) => setRule({ ...rule, action: e.target.value })} className={FIELD} aria-label="Action"><option value="permit">Allow</option><option value="deny">Block</option></select>
              <select value={rule.protocol} onChange={(e) => setRule({ ...rule, protocol: e.target.value })} className={FIELD} aria-label="Protocol">{["tcp", "udp", "icmp", "ipv4"].map((p) => <option key={p} value={p}>{p.toUpperCase()}</option>)}</select>
              <input value={rule.ports} onChange={(e) => setRule({ ...rule, ports: e.target.value })} className={FIELD} placeholder="Port(s)" aria-label="Ports" disabled={rule.protocol !== "tcp" && rule.protocol !== "udp"} />
              <input value={rule.source} onChange={(e) => setRule({ ...rule, source: e.target.value })} className={FIELD} placeholder="From (any)" aria-label="Source" />
              <button type="button" disabled={busy} onClick={() => run("FW_RULE_ADD", { ip: ip.ip, rule: { ...rule, ports: rule.protocol === "tcp" || rule.protocol === "udp" ? rule.ports : "" } }, "Adding the rule.")} className="btn-ghost btn-xs h-[38px]">Add rule</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function ExtraIps({ panel, serverId, onPaid }: { panel: DedicatedPanel; serverId: string; onPaid: () => void }) {
  const router = useRouter();
  const [qty, setQty] = useState<1 | 4 | 8>(1);
  const [quote, setQuote] = useState<{ chargeCents: number; renewalAfter: string; monthlyCents: number; walletApplied: number; cardCents: number; balanceCents: number } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const key = useMemo(() => newKey(), []);
  const confirmRef = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const open = panel.ipOrders.find((o) => ["PAID", "APPROVED", "ORDERING"].includes(o.status));

  useEffect(() => {
    setCheckout(null);
    start(async () => {
      const r = await quoteDedicatedExtraIps(serverId, qty);
      if (r.ok) { setQuote({ ...r.quote, walletApplied: r.walletApplied, cardCents: r.cardCents, balanceCents: r.balanceCents }); setErr(null); } else setErr(r.error);
    });
  }, [qty, serverId]);

  const pay = () => start(async () => {
    setErr(null);
    const r = await payDedicatedExtraIps(serverId, qty, key, true);
    if (!r.ok) { setErr(r.error); return; }
    if ("orderId" in r) { onPaid(); router.refresh(); return; }
    setCheckout({ ...r.checkout, cardCents: r.cardCents });
  });

  const STATUS: Record<string, string> = { PAID: "Paid, awaiting our team", APPROVED: "Being ordered", ORDERING: "Being delivered", DONE: "Added", REJECTED: "Refunded", FAILED: "Delayed, our team is on it" };
  return (
    <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
      <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="plus" size={14} />Extra IPv4 addresses</span>
      {panel.ipOrders.length > 0 && (
        <ul className="flex flex-col gap-1">
          {panel.ipOrders.map((o) => (
            <li key={o.id} className="flex flex-wrap items-center justify-between gap-2 text-[12px]">
              <span className="text-tx-body">{o.quantity === 1 ? "1 address" : `${o.quantity} addresses`} · {usd(o.chargedCents)} · {when(o.createdAt)}</span>
              <span className={"chip-tone " + (o.status === "DONE" ? "chip-mint" : o.status === "REJECTED" ? "chip-slate" : "chip-violet")}>{STATUS[o.status] ?? o.status}</span>
              {o.ips.length > 0 && <span className="w-full font-mono text-[11.5px] text-tx-faint">{o.ips.join(", ")}</span>}
            </li>
          ))}
        </ul>
      )}
      {open ? (
        <span className="text-[11.8px] text-tx-faint">Your order is with our team. Addresses appear above once they are routed to this server.</span>
      ) : (
        <>
          <div className="flex flex-wrap gap-1.5">
            {([1, 4, 8] as const).map((n) => (
              <button key={n} type="button" onClick={() => setQty(n)} aria-pressed={qty === n} className={"chip " + (qty === n ? "chip-on" : "")}>{n === 1 ? "1 address" : `Block of ${n}`}</button>
            ))}
          </div>
          {quote && (
            <div className="flex flex-col gap-1 text-[12.5px]">
              <span className="flex justify-between gap-3"><span className="text-tx-mute">Today (until your renewal)</span><b className="text-white">{usd(quote.chargeCents)}</b></span>
              <span className="flex justify-between gap-3"><span className="text-tx-mute">Then your server renews at</span><b className="text-white">{quote.renewalAfter}</b></span>
              {quote.walletApplied > 0 && <span className="flex justify-between gap-3"><span className="text-tx-mute">From your wallet</span><span className="font-semibold text-mint">−{usd(quote.walletApplied)}</span></span>}
            </div>
          )}
          {checkout ? (
            <>
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={(fn) => { confirmRef.current = fn; setCanConfirm(!!fn); }} onBusy={(_b, e) => setErr(e)} />
              <button type="button" disabled={!canConfirm} onClick={() => void confirmRef.current?.()} className="btn-primary btn-sm w-fit">Pay {usd(checkout.cardCents)}</button>
            </>
          ) : (
            <button type="button" disabled={busy || !quote} onClick={pay} className="btn-primary btn-sm w-fit">{quote && quote.cardCents === 0 ? `Pay ${usd(quote.chargeCents)} from wallet` : "Continue to payment"}</button>
          )}
          <span className="text-[11px] text-tx-faint">Our team confirms availability in your location before the addresses are added. If they can&apos;t be added, the full amount goes back to your wallet.</span>
        </>
      )}
      {err && <span className="text-[11.5px] text-[#ffc2d1]">{err}</span>}
    </div>
  );
}

/* ---------------- activity ---------------- */

function Activity({ jobs }: { jobs: CustomerJob[] }) {
  if (!jobs.length) return null;
  return (
    <div className="flex flex-col gap-1.5">
      <span className="nx-label uppercase">Recent actions</span>
      <ul className="flex flex-col gap-1.5">
        {jobs.slice(0, 6).map((j) => (
          <li key={j.id} className="flex flex-col gap-1 rounded-[10px] border border-rim bg-surface px-3 py-2">
            <span className="flex flex-wrap items-center justify-between gap-2">
              <span className="text-[12.5px] font-bold text-white">{j.label}</span>
              <span className={"chip-tone " + (j.status === "DONE" ? "chip-mint" : j.status === "FAILED" ? "chip-rose" : "chip-blue")}>{JOB_STATUS_LABEL[j.status] ?? j.status}</span>
            </span>
            {!isTerminal(j.status) && <span className="block h-[4px] overflow-hidden rounded-full bg-well"><span className="block h-full rounded-full bg-[linear-gradient(90deg,#2f7eef,#6f2ee0)] transition-[width] duration-700" style={{ width: `${Math.max(6, j.progress)}%` }} /></span>}
            <span className="text-[11.3px] text-tx-faint" suppressHydrationWarning>{j.error ?? j.step} · {when(j.createdAt)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

