"use client";

/** ADMIN-ONLY Phase 2 controls: handover, extra-IP approvals, rescue password. Nothing here writes upstream; it enqueues worker jobs. */
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { adminApproveIpOrder, adminRejectIpOrder, adminStartHandover, adminStoreRescueSecret } from "@/lib/actions-dedicated-ops-admin";

type R = { ok: true; message?: string } | { ok: false; error: string };

function useAct() {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const run = (fn: () => Promise<R>) => start(async () => { const r = await fn(); setMsg(r.ok ? r.message ?? "Done." : r.error); if (r.ok) router.refresh(); });
  return { pending, msg, run };
}

export function HandoverForm({ id, defaultHostname, osLabel, keys, linked }: { id: string; defaultHostname: string; osLabel: string; keys: { id: string; name: string }[]; linked: boolean }) {
  const { pending, msg, run } = useAct();
  const [host, setHost] = useState(defaultHostname);
  const [keyId, setKeyId] = useState(keys[0]?.id ?? "");
  const [os, setOs] = useState(osLabel);
  return (
    <div className="space-y-2 text-xs">
      <p className="text-slate-400">Once the machine is bought upstream and its service name is saved (Edit record), this installs the ordered OS with the customer&apos;s SSH key, then the worker marks it ACTIVE, fills the IPs and notifies the customer. Customer gets root via their key only; we keep out-of-band control.</p>
      <div className="grid gap-2 sm:grid-cols-3">
        <label className="space-y-1"><span className="text-slate-500">Hostname</span><input className="input w-full text-xs" value={host} onChange={(e) => setHost(e.target.value)} /></label>
        <label className="space-y-1"><span className="text-slate-500">OS (as ordered)</span><input className="input w-full text-xs" value={os} onChange={(e) => setOs(e.target.value)} /></label>
        <label className="space-y-1"><span className="text-slate-500">Customer SSH key</span>
          <select className="input w-full text-xs" value={keyId} onChange={(e) => setKeyId(e.target.value)}>
            {keys.length === 0 && <option value="">Customer has no SSH key</option>}
            {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
          </select>
        </label>
      </div>
      <button type="button" className="btn-primary py-1.5 text-xs" disabled={pending || !linked || !keyId} onClick={() => run(() => adminStartHandover(id, { hostname: host, sshKeyId: keyId, osLabel: os }))}>Install &amp; hand over</button>
      {!linked && <p className="text-amber-300">Set the upstream service name first.</p>}
      {msg && <p className="text-slate-300">{msg}</p>}
    </div>
  );
}

export function IpOrderButtons({ orderId, status }: { orderId: string; status: string }) {
  const { pending, msg, run } = useAct();
  const [reason, setReason] = useState("");
  return (
    <span className="flex flex-wrap items-center gap-2">
      {status === "PAID" && <button type="button" className="btn-primary py-1 text-xs" disabled={pending} onClick={() => run(() => adminApproveIpOrder(orderId))}>Approve purchase</button>}
      {(status === "PAID" || status === "FAILED") && (
        <>
          <input className="input w-40 py-1 text-xs" placeholder="Reason (shown to customer)" value={reason} onChange={(e) => setReason(e.target.value)} />
          <button type="button" className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => run(() => adminRejectIpOrder(orderId, reason))}>Reject &amp; refund</button>
        </>
      )}
      {msg && <span className="text-slate-300">{msg}</span>}
    </span>
  );
}

export function RescueSecretForm({ id, stored }: { id: string; stored: boolean }) {
  const { pending, msg, run } = useAct();
  const [v, setV] = useState("");
  return (
    <div className="space-y-1 text-xs">
      <p className="text-slate-400">Only needed if rescue was started without an SSH key and a password was issued to us. Stored encrypted; the customer reveals it. {stored ? "A password is stored." : ""}</p>
      <div className="flex gap-2">
        <input className="input flex-1 py-1 text-xs" type="password" value={v} onChange={(e) => setV(e.target.value)} placeholder="Rescue password" autoComplete="off" />
        <button type="button" className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => run(() => adminStoreRescueSecret(id, v))}>{v ? "Store" : "Clear"}</button>
      </div>
      {msg && <p className="text-slate-300">{msg}</p>}
    </div>
  );
}

