cd /tank/nxeon-wt-dedicated2 && cat > lib/dedicated/brand.ts <<'EOF'
/**
 * Pure: which chip vendor a CPU / GPU model string belongs to, for the brand
 * logos on the catalogue, configurator and server pages. Client-safe.
 * AMD for Ryzen / EPYC / Threadripper / Opteron / Radeon, Intel for Xeon / Core
 * / Pentium / Celeron / Atom, NVIDIA for any NVIDIA / GeForce / RTX / Tesla / L4 / L40S / A100 / H100 GPU.
 */
export type ChipBrand = "amd" | "intel" | "nvidia";

export function cpuBrandOf(model: string | null | undefined): Exclude<ChipBrand, "nvidia"> | null {
  const s = (model ?? "").toLowerCase();
  if (/\bamd\b|ryzen|epyc|threadripper|opteron/.test(s)) return "amd";
  if (/\bintel\b|xeon|\bcore\b|\bi[3579]-\d|pentium|celeron|\batom\b/.test(s)) return "intel";
  return null;
}

export function gpuBrandOf(model: string | null | undefined): ChipBrand | null {
  const s = (model ?? "").toLowerCase();
  if (!s) return null;
  if (/nvidia|geforce|\brtx\b|\bgtx\b|tesla|quadro|\bl4\b|\bl40s?\b|\ba(10|30|40|100)\b|\bh(100|200)\b/.test(s)) return "nvidia";
  if (/radeon|instinct|\bamd\b/.test(s)) return "amd";
  return null;
}
EOF
