 *  they all end in a file extension) are left alone; anything this misses (a
 *  link a page script builds client-side) still lands via middleware's 301. */
export function unstage(html: string): string {
  if (!NXM_ROOT) return html;
  return html.replace(/(["'(=\s])\/nxm(\/[^"'\s)<>?#]*)?(?=["'\s)<>?#])/g, (m, pre: string, rest?: string) =>
    rest && /\.[a-z0-9]{2,5}$/i.test(rest) ? m : pre + (rest || "/"));
