import "server-only";
import { currentUser } from "@/lib/auth";
import { dedicatedPublicEnabled, requireDedicatedAccess } from "@/lib/dedicated/gate";
import { loadOrderCatalog, orderPreviewAll, type OrderCatalogCard } from "@/lib/dedicated/order";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, usd, type NxmLoad } from "./lib";

/**
 * /dedicated-servers (bare metal) — the NXM flagship page. GATED: 404 unless
 * the dedicated gate passes (Setting dedicated_public_enabled, or a private-
 * preview account; lib/dedicated/gate.ts). noindex unless public; the sitemap
 * lists it only when public (lib/sitemap-sections.ts EXCLUDE + dedicatedSitemapPaths).
 *
 * Every figure is real: the same in-stock catalogue + pricing rules the
 * checkout charges (lib/dedicated/order.ts). Buy links go straight into the
 * portal configurator; a signed-out visitor is sent through /register?next=,
 * the same register-then-continue pattern the rest of the site uses.
 */
const ORDER = "/dashboard/dedicated/order";
const LOGO: Record<string, string> = { amd: "/nxm/home/logos-amd.svg", intel: "/nxm/home/logos-intel.svg", nvidia: "/nxm/home/logos-nvidia.svg" };
const logo = (b: string | null, cls = "") => (b ? `<img class="dd-logo ${cls}" src="${LOGO[b]}" alt="${b === "amd" ? "AMD" : b === "intel" ? "Intel" : "NVIDIA"}">` : "");

async function inStockCards(): Promise<OrderCatalogCard[]> {
  const access = await requireDedicatedAccess();
  const cards = await loadOrderCatalog(await orderPreviewAll(access.preview));
  return cards.filter((c) => c.regions.some((r) => r.inStock));
}

export async function meta(_p: Record<string, string>) {
  const on = await dedicatedPublicEnabled();
  return {
    title: "Dedicated Servers & Bare Metal",
    description: "Bare metal dedicated servers with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. Live stock, monthly prices, online within 24 hours.",
    noindex: !on,
  };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const cards = await inStockCards();
  const user = await currentUser();
  const hrefFor = (id: string, region?: string) => {
    const dest = `${ORDER}/${encodeURIComponent(id)}${region ? `?region=${region}` : ""}`;
    return user ? dest : `/register?next=${encodeURIComponent(dest)}`;
  };
  const fromOf = (c: OrderCatalogCard) => Math.min(...c.regions.filter((r) => r.inStock).map((r) => r.fromMonthlyCents));
  const sorted = [...cards].sort((a, b) => fromOf(a) - fromOf(b));
  const cheapest = sorted[0] ?? null;

  // locations: every listed region, with how many builds are in stock there
  const regions = new Map<string, { code: string; label: string; area: string; inStock: number; listed: number }>();
  for (const c of cards) for (const r of c.regions) {
    const e = regions.get(r.code) ?? { code: r.code, label: r.label, area: r.area, inStock: 0, listed: 0 };
    e.listed++;
    if (r.inStock) e.inStock++;
    regions.set(r.code, e);
  }
  const regionList = [...regions.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  const regionsInStock = regionList.filter((r) => r.inStock > 0).length;

  const plate = cheapest
    ? `<div class="au-glass dd-plate"><div class="dd-plate-top"><b>In stock</b><span>${esc(cheapest.tier)}</span></div>
<div class="dd-face" aria-hidden="true">${"<i></i>".repeat(14)}</div>
<div class="dd-plate-body"><p class="dd-plate-cpu">${logo(cpuBrandOf(cheapest.cpu), "lg")}${esc(cheapest.cpu.replace(/^(AMD|Intel)\s+/i, ""))}</p>
<p class="dd-plate-sub">${cheapest.cores} cores · ${cheapest.threads} threads${cheapest.baseGhz ? ` · ${cheapest.baseGhz} GHz` : ""}</p>
<div class="dd-plate-spec"><div><span>Memory</span><b>${cheapest.ramGb} GB</b></div><div><span>Storage</span><b title="${esc(cheapest.storage)}">${esc(cheapest.storage.split("(")[0].trim() || "—")}</b></div></div>
<div class="dd-plate-foot"><span class="dd-price">${usd(fromOf(cheapest))}<small>/mo</small></span><a class="au-btn sm" href="${esc(hrefFor(cheapest.id))}">Configure</a></div></div></div>`
    : `<div class="au-glass dd-plate"><div class="dd-plate-body"><p class="dd-plate-cpu">Stock is being refreshed</p><p class="dd-plate-sub">Check back shortly, or ask our team for a custom build.</p></div></div>`;

  const locations = regionList.length
    ? `<ul class="dd-locs">${regionList.map((r) => `<li class="au-glass dd-loc${r.inStock ? " on" : ""}"><small>${esc(r.area)}</small><b>${esc(r.label)}</b><span>${r.inStock ? `${r.inStock} build${r.inStock === 1 ? "" : "s"} in stock` : "Sold out right now"}</span></li>`).join("")}</ul>`
    : `<p class="lede">Locations are being refreshed.</p>`;

  const data = {
    regions: regionList.map((r) => ({ code: r.code, label: r.label, inStock: r.inStock })),
    cards: sorted.map((c) => ({
      id: c.id,
      href: hrefFor(c.id),
      hrefTpl: hrefFor(c.id, "__REGION__"),
      tier: c.tier,
      cpuShort: c.cpu.replace(/^(AMD|Intel)\s+/i, ""),
      cpuBrand: cpuBrandOf(c.cpu),
      cpuBrandName: c.cpuBrand,
      gpu: c.gpu,
      gpuBrand: gpuBrandOf(c.gpu),
      cores: c.cores,
      threads: c.threads,
      ghz: c.baseGhz,
      ramGb: c.ramGb,
      maxRamGb: c.maxRamGb,
      storage: c.storage,
      storageGb: c.storageGb,
      bandwidth: c.bandwidth,
      setup: (c.regions.find((r) => r.inStock)?.setupCents ?? 0) / 100,
      regions: c.regions.map((r) => ({ code: r.code, label: r.label, inStock: r.inStock, from: r.fromMonthlyCents / 100 })),
    })),
  };

  const prices = sorted.map(fromOf);
  return {
    slots: {
      count: String(cards.length),
      from: cheapest ? usd(fromOf(cheapest)) : "—",
      maxThreads: String(cards.reduce((m, c) => Math.max(m, c.threads), 0)),
      regions: String(regionsInStock),
      "plate:html": plate,
      "locations:html": locations,
    },
    data,
    crumb: "Dedicated servers",
    jsonLd: prices.length
      ? [{
          "@context": "https://schema.org", "@type": "Product", name: "Nxeon Dedicated Servers (bare metal)",
          description: "Single-tenant bare metal dedicated servers with full root, dedicated IPv4 and DDoS protection, billed monthly or yearly.",
          brand: { "@type": "Brand", name: "Nxeon" },
          offers: { "@type": "AggregateOffer", priceCurrency: "USD", lowPrice: (Math.min(...prices) / 100).toFixed(2), highPrice: (Math.max(...prices) / 100).toFixed(2), offerCount: prices.length, availability: "https://schema.org/InStock", url: APP_URL + "/dedicated-servers" },
        }]
      : [],
  };
}

