// Full walk-through #2: portal order flow, Phase 2 controls (mock upstream), admin approvals/handover, NXM marketing.
// node shots2.js <base> <outDir> <authSecret> [sections]
const path = require("path");
const NM = "/tank/nxeon-wt-dedicated2/node_modules/";
const { chromium } = require(NM + "playwright");
const { execSync } = require("child_process");
const [base, out, secret, only] = process.argv.slice(2);
const OWNER = "cmrztujaw0002hlazl58i3lsi", OTHER = "cmothercustomer0000000001", ADMIN = "cmadminpreview00000000001";
const DEMO = "cmdemoactiveserver000001";
const psql = (sql) => execSync(`psql -h 127.0.0.1 -p 55447 -U postgres dedprev -Atc ${JSON.stringify(sql)}`).toString().trim();
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);
const want = (s) => !only || only.split(",").includes(s);

async function token(sub) {
  const { SignJWT } = await import(NM + "jose/dist/webapi/index.js");
  return new SignJWT({ sub, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(secret));
}
async function ctxFor(browser, sub, mobile) {
  const ctx = await browser.newContext(mobile ? { viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true } : { viewport: { width: 1440, height: 900 } });
  ctx.setDefaultTimeout(240000); ctx.setDefaultNavigationTimeout(240000);
  const host = new URL(base).hostname;
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "all", domain: host, path: "/" }]);
  if (sub) await ctx.addCookies([{ name: "nxeon_session", value: await token(sub), domain: host, path: "/", httpOnly: true }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  return ctx;
}
const errors = [];
function watch(page, tag) {
  page.on("pageerror", (e) => errors.push(`${tag} PAGEERROR ${e.message}`));
  page.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource/.test(m.text())) errors.push(`${tag} CONSOLE ${m.text().slice(0, 160)}`); });
}
async function shot(page, name, full = true) {
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(out, name + ".png"), fullPage: full });
  const ov = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  log("shot", name, ov > 0 ? `OVERFLOW ${ov}px` : "");
}
async function waitJobsIdle(page, maxMs = 120000) {
  const t0 = Date.now();
  while (Date.now() - t0 < maxMs) {
    const n = Number(psql(`select count(*) from "DedicatedJob" where status in ('QUEUED','RUNNING','WAITING')`));
    if (!n) return true;
    await page.waitForTimeout(2500);
  }
  return false;
}

(async () => {
  const browser = await chromium.launch();

  /* ---------- A. portal order flow (desktop card + mobile wallet) ---------- */
  if (want("order")) for (const mobile of [false, true]) {
    const sfx = mobile ? "mobile" : "desktop";
    psql(`update "User" set "balanceCents"=${mobile ? 900000 : 5000} where id='${OWNER}'`);
    const ctx = await ctxFor(browser, OWNER, mobile); const page = await ctx.newPage(); watch(page, sfx);
    await page.goto(`${base}/dashboard/dedicated/order`, { waitUntil: "networkidle" });
    await shot(page, `02-catalogue-${sfx}`);
    await page.locator("select").first().selectOption({ label: /Singapore/ }).catch(async () => {
      const v = await page.locator("select").first().locator("option", { hasText: "Singapore" }).first().getAttribute("value"); await page.locator("select").first().selectOption(v);
    });
    await page.getByRole("button", { name: "AMD" }).click();
    await shot(page, `02b-catalogue-filtered-amd-singapore-${sfx}`);
    await page.locator("select").nth(4).selectOption("50"); await page.locator("select").nth(2).selectOption("512");
    await shot(page, `02c-catalogue-no-match-${sfx}`, false);
    await page.getByRole("button", { name: "Clear filters" }).first().click();
    await page.getByRole("button", { name: /With NVIDIA or AMD GPU/ }).click();
    await shot(page, `02d-catalogue-gpu-${sfx}`, false);
    await page.getByRole("button", { name: "Any processor" }).click();
    await page.locator('a:has-text("Configure")').nth(mobile ? 0 : 3).click();
    await page.waitForURL(/\/dashboard\/dedicated\/order\/.+/); await page.waitForLoadState("networkidle");
    await shot(page, `03-configure-${sfx}`);
    await page.getByRole("button", { name: /Annual/ }).first().click().catch(() => {});
    await page.getByLabel("Server name").fill(mobile ? "Mobile box" : "Preview box");
    await shot(page, `03b-configure-annual-${sfx}`);
    await page.getByRole("button", { name: /Review order/ }).click();
    await page.waitForSelector("text=Continue to payment");
    await shot(page, `04-review-${sfx}`);
    await page.getByRole("button", { name: /Continue to payment/ }).click();
    if (!mobile) {
      await page.waitForSelector('iframe[name^="__privateStripeFrame"]', { timeout: 60000 }); await page.waitForTimeout(4000);
      await shot(page, `05-pay-card-${sfx}`);
      const f = page.frameLocator('iframe[name^="__privateStripeFrame"]').first();
      try {
        await f.locator('input[name="number"]').fill("4242424242424242");
        await f.locator('input[name="expiry"]').fill("12 / 34"); await f.locator('input[name="cvc"]').fill("123");
        const zip = f.locator('input[name="postalCode"]'); if (await zip.count()) await zip.fill("10001");
        await page.getByRole("button", { name: /^Pay \$/ }).click();
        await page.waitForURL(/\/dashboard\/dedicated\/[a-z0-9]+\?ordered=1/, { timeout: 120000 }); await page.waitForLoadState("networkidle");
        await shot(page, `06-server-ordered-card-${sfx}`); log("CARD ORDER OK", page.url());
      } catch (e) { log("CARD FAILED", e.message); await shot(page, `05x-card-error-${sfx}`); }
    } else {
      await page.waitForSelector("text=Wallet balance");
      await shot(page, `05-pay-wallet-${sfx}`);
      await page.getByRole("button", { name: /^Pay \$/ }).click();
      await page.waitForURL(/\/dashboard\/dedicated\/[a-z0-9]+\?ordered=1/, { timeout: 120000 }); await page.waitForLoadState("networkidle");
      await shot(page, `06-server-ordered-wallet-${sfx}`); log("WALLET ORDER OK", page.url());
    }
    await page.goto(`${base}/dashboard/dedicated`, { waitUntil: "networkidle" });
    await shot(page, `07-dashboard-list-${sfx}`);
    await ctx.close();
  }

  /* ---------- B. Phase 2 controls on the demo machine ---------- */
  if (want("ops")) {
    psql(`update "User" set "balanceCents"=900000 where id='${OWNER}'`);
    const ctx = await ctxFor(browser, OWNER, false); const page = await ctx.newPage(); watch(page, "ops");
    const go = async () => { await page.goto(`${base}/dashboard/dedicated/${DEMO}`, { waitUntil: "networkidle" }); };
    const tab = async (t) => { await page.getByRole("tab", { name: t }).click(); await page.waitForTimeout(500); };
    await go(); await shot(page, "20-ops-overview-desktop");
    await tab("Power & rescue"); await shot(page, "21-ops-power-desktop", false);
    await page.getByRole("button", { name: "Reboot", exact: true }).click();
    await page.getByRole("button", { name: /Yes, reboot now/ }).click();
    await page.waitForTimeout(2500); await shot(page, "22-ops-reboot-running-desktop");
    await waitJobsIdle(page); await page.waitForTimeout(5000); await shot(page, "23-ops-reboot-done-desktop");
    await go(); await tab("Power & rescue");
    await page.getByRole("button", { name: /Boot into rescue/ }).click();
    await waitJobsIdle(page); await go(); await tab("Power & rescue");
    await shot(page, "24-ops-rescue-active-desktop");
    await page.getByRole("button", { name: /Boot back to disk/ }).click(); await waitJobsIdle(page);
    await go(); await tab("Reinstall");
    await page.getByPlaceholder("db1.example.com").fill("db1.example.com");
    await page.getByLabel("Type the server name to confirm").fill("Demo bare metal");
    await shot(page, "25-ops-reinstall-form-desktop", false);
    await page.getByRole("button", { name: /Erase and reinstall/ }).click();
    await page.waitForTimeout(14000); await shot(page, "26-ops-reinstall-progress-desktop");
    await waitJobsIdle(page, 180000); await page.waitForTimeout(4000); await shot(page, "27-ops-reinstall-done-desktop");
    await go(); await tab("Network");
    await page.getByRole("button", { name: "Manage" }).first().click();
    await page.getByPlaceholder("mail.example.com").fill("db1.example.com");
    await page.getByRole("button", { name: "Save" }).click(); await waitJobsIdle(page);
    await page.getByRole("button", { name: "Turn on" }).click(); await waitJobsIdle(page);
    await go(); await tab("Network"); await page.getByRole("button", { name: "Manage" }).first().click();
    await page.getByRole("button", { name: "Add rule" }).click(); await waitJobsIdle(page);
    await go(); await tab("Network"); await page.getByRole("button", { name: "Manage" }).first().click();
    await shot(page, "28-ops-network-rdns-firewall-desktop");
    await page.getByRole("button", { name: "Block of 8" }).click(); await page.waitForTimeout(2500);
    await shot(page, "29-ops-extra-ips-quote-desktop", false);
    await page.getByRole("button", { name: /from wallet/ }).click(); await page.waitForTimeout(4000);
    await go(); await tab("Network"); await shot(page, "30-ops-extra-ips-awaiting-approval-desktop");
    // mobile views of the same panel
    const m = await ctxFor(browser, OWNER, true); const mp = await m.newPage(); watch(mp, "ops-m");
    await mp.goto(`${base}/dashboard/dedicated/${DEMO}`, { waitUntil: "networkidle" }); await shot(mp, "20-ops-overview-mobile");
    for (const [t, n] of [["Power & rescue", "21-ops-power-mobile"], ["Reinstall", "25-ops-reinstall-mobile"], ["Network", "28-ops-network-mobile"]]) { await mp.getByRole("tab", { name: t }).click(); await mp.waitForTimeout(600); await shot(mp, n); }
    await m.close();

    // admin approves the IP order -> worker orders, attaches, adds to renewal
    const a = await ctxFor(browser, ADMIN, false); const ap = await a.newPage(); watch(ap, "admin");
    await ap.goto(`${base}/admin/dedicated/servers/${DEMO}`, { waitUntil: "networkidle" });
    await shot(ap, "31-admin-ip-order-awaiting-approval-desktop");
    await ap.getByRole("button", { name: "Approve purchase" }).click(); await ap.waitForTimeout(2000);
    await waitJobsIdle(ap, 180000);
    await ap.goto(`${base}/admin/dedicated/servers/${DEMO}`, { waitUntil: "networkidle" }); await shot(ap, "32-admin-ip-order-done-desktop");
    await a.close();
    await go(); await tab("Network"); await shot(page, "33-ops-extra-ips-added-desktop");
    log("renewal now", psql(`select "renewalMonthlyCents", "extraIpMonthlyCents", array_to_string(ipv4, ',') from "DedicatedServer" where id='${DEMO}'`));
    await ctx.close();
  }

  /* ---------- C. admin handover of a paid PENDING order ---------- */
  if (want("handover")) {
    const sid = psql(`select id from "DedicatedServer" where "userId"='${OWNER}' and status='PENDING' order by "createdAt" desc limit 1`);
    if (sid) {
      psql(`update "DedicatedServer" set "providerServiceName"='ns-demo-2.example' where id='${sid}'`);
      const a = await ctxFor(browser, ADMIN, false); const ap = await a.newPage(); watch(ap, "handover");
      await ap.goto(`${base}/admin/dedicated/servers/${sid}`, { waitUntil: "networkidle" }); await shot(ap, "40-admin-handover-form-desktop");
      await ap.getByRole("button", { name: /Install & hand over/ }).click(); await ap.waitForTimeout(3000);
      const c = await ctxFor(browser, OWNER, false); const cp = await c.newPage();
      await cp.goto(`${base}/dashboard/dedicated/${sid}`, { waitUntil: "networkidle" }); await shot(cp, "41-customer-being-built-desktop");
      await waitJobsIdle(ap, 240000);
      await cp.goto(`${base}/dashboard/dedicated/${sid}`, { waitUntil: "networkidle" }); await shot(cp, "42-customer-handed-over-desktop");
      const cm = await ctxFor(browser, OWNER, true); const cmp = await cm.newPage();
      await cmp.goto(`${base}/dashboard/dedicated/${sid}`, { waitUntil: "networkidle" }); await shot(cmp, "42-customer-handed-over-mobile");
      await ap.goto(`${base}/admin/dedicated/servers/${sid}`, { waitUntil: "networkidle" }); await shot(ap, "43-admin-after-handover-desktop");
      log("handover status", psql(`select status, array_to_string(ipv4, ','), os, hostname from "DedicatedServer" where id='${sid}'`));
      await a.close(); await c.close(); await cm.close();
    } else log("no PENDING server for handover");
  }

  /* ---------- D. NXM marketing ---------- */
  if (want("nxm")) for (const mobile of [false, true]) {
    const sfx = mobile ? "mobile" : "desktop";
    const ctx = await ctxFor(browser, OWNER, mobile); const page = await ctx.newPage(); watch(page, "nxm-" + sfx);
    await page.goto(`${base}/nxm/dedicated-servers`, { waitUntil: "networkidle" });
    await shot(page, `50-nxm-dedicated-page-${sfx}`);
    await shot(page, `50b-nxm-dedicated-hero-${sfx}`, false);
    if (!mobile) {
      await page.locator('.nv-t[data-m="products"]').first().click().catch(() => {}); await page.waitForTimeout(700);
      await shot(page, `51-nxm-nav-products-menu-${sfx}`, false);
      await page.keyboard.press("Escape");
    } else {
      await page.locator(".nv-burger").click(); await page.waitForTimeout(800);
      await shot(page, `51-nxm-mobile-menu-${sfx}`, false);
      await page.locator(".nv-burger").click().catch(() => {}); await page.waitForTimeout(400);
    }
    await page.locator("#catalogue").scrollIntoViewIfNeeded();
    await page.locator('.dd-chip[data-brand="Intel"]').click(); await page.waitForTimeout(500);
    await page.locator("#catalogue").screenshot({ path: path.join(out, `52-nxm-catalogue-intel-${sfx}.png`) }); log("shot 52", sfx);
    await page.locator('.dd-chip[data-brand="GPU"]').click(); await page.waitForTimeout(500);
    await page.locator("#catalogue").screenshot({ path: path.join(out, `52b-nxm-catalogue-gpu-${sfx}.png`) });
    await page.locator('.dd-chip[data-brand="all"]').click();
    const first = page.locator("#dd-grid a").first(); log("nxm configure href", await first.getAttribute("href"));
    await first.click(); await page.waitForURL(/\/dashboard\/dedicated\/order\//); await page.waitForLoadState("networkidle");
    await shot(page, `53-nxm-to-configure-${sfx}`, false);
    await page.goto(`${base}/nxm/vps`, { waitUntil: "networkidle" });
    const up = page.locator('section[aria-label="Dedicated servers"]');
    log("vps upsell count", await up.count());
    if (await up.count()) { await up.scrollIntoViewIfNeeded(); await shot(page, `54-nxm-vps-need-more-power-${sfx}`, false); }
    await ctx.close();
    // signed-out visitor
    const anon = await ctxFor(browser, null, mobile); const ap = await anon.newPage();
    const r = await ap.goto(`${base}/nxm/dedicated-servers`, { waitUntil: "networkidle" }); log("ANON nxm", r.status());
    await shot(ap, `55-nxm-signed-out-404-${sfx}`, false);
    await ap.goto(`${base}/nxm/vps`, { waitUntil: "networkidle" });
    log("ANON vps: dedicated nav links", await ap.locator('a[href*="dedicated-servers"]').count());
    await anon.close();
    const oth = await ctxFor(browser, OTHER, mobile); const op = await oth.newPage();
    const r2 = await op.goto(`${base}/nxm/dedicated-servers`, { waitUntil: "networkidle" }); log("OTHER nxm", r2.status());
    await op.goto(`${base}/nxm/vps`, { waitUntil: "networkidle" });
    log("OTHER vps: dedicated links", await op.locator('a[href*="dedicated-servers"]').count());
    await oth.close();
  }

  /* ---------- E. gate checks in the portal ---------- */
  if (want("gate")) {
    const oth = await ctxFor(browser, OTHER, false); const op = await oth.newPage();
    for (const p of ["/dashboard/dedicated", "/dashboard/dedicated/order", `/dashboard/dedicated/${DEMO}`, "/dedicated-servers"]) {
      const r = await op.goto(`${base}${p}`, { waitUntil: "networkidle" }); log("OTHER", p, r.status());
    }
    await shot(op, "60-other-account-404-desktop", false);
    await op.goto(`${base}/dashboard`, { waitUntil: "networkidle" }); log("OTHER rail dedicated links", await op.locator('a[href="/dashboard/dedicated"]').count());
    await oth.close();
    const own = await ctxFor(browser, OWNER, false); const ow = await own.newPage();
    await ow.goto(`${base}/dashboard`, { waitUntil: "networkidle" }); log("OWNER rail dedicated links", await ow.locator('a[href="/dashboard/dedicated"]').count());
    await shot(ow, "61-owner-portal-rail-desktop", false);
    await own.close();
    const an = await ctxFor(browser, null, false); const anp = await an.newPage();
    const r = await anp.goto(`${base}/dedicated-servers`, { waitUntil: "networkidle" }); log("ANON /dedicated-servers", r.status());
    await anp.goto(`${base}/dashboard/dedicated/order`, { waitUntil: "networkidle" }); log("ANON portal ->", anp.url());
    await an.close();
  }

  await browser.close();
  log("ERRORS", errors.length ? "\n" + [...new Set(errors)].join("\n") : "none");
})().catch((e) => { console.error(e); process.exit(1); });

